DROP TABLE IF EXISTS `T_ACCOUNT_CHANGE_LOG`;
CREATE TABLE `T_ACCOUNT_CHANGE_LOG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ACCOUNT_APPLY_ID` bigint(20) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户请求流水号',
  `CHANGE_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新类型 MODIFY_ACCOUNT_NAME',
  `BEFORE_CHANGE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新前信息JSON格式',
