  `BANK_ACCOUNT_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户类型：PLATFORM_PAYEE-电商收款，OTHER_PAYEE-其他账户收款, B2B_PAYEE-B2b收款，SERVICE_TRADE_PAYEE-服贸收款,B2B_SUPPLIER_PAYEE-B2B供应商收款',
