-- ----------------------------
DROP TABLE IF EXISTS `T_ACCOUNT_ORDER`;
CREATE TABLE `T_ACCOUNT_ORDER`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `ACCOUNT_REQ_ID` bigint(20) NOT NULL COMMENT '账务系统请求流水号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '商户订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ORDER_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '订单状态：-1-处理失败，0-待处理，1-处理中，2-处理成功',
  `ORDER_TYPE` tinyint(2) NOT NULL COMMENT '记账交易类型：2-充值 3-提现 4-转账 5-撤销',
  `TRANSACTION_TYPE` int(11) NULL DEFAULT NULL,
  `ACCOUNTING_CCY` tinyint(2) NULL DEFAULT NULL COMMENT '记账币种 1：本币 2：外币 3：本币转外币 4：外币转本币',
  `FOREIGN_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '外币币种',
  `PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品大类',
  `SUB_PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品细类',
  `FUNDING_CHANNEL` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '资金渠道大类',
  `SUB_FUNDING_CHANNEL` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '资金渠道细类',
  `EXCHANGE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '汇率',
  `DOMESTIC_AMOUNT` decimal(19, 3) NULL DEFAULT NULL COMMENT '本币金额',
  `FOREIGN_AMOUNT` decimal(19, 3) NULL DEFAULT NULL COMMENT '外币金额',
  `CANCEL_REQ_ID` bigint(20) NULL DEFAULT NULL COMMENT '撤掉订单账务系统请求流水号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `OPERATOR_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '操作类型: 1-正常 2-定时补录  3-手动补录',
  `REQUEST_BUSINESS_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '请求业务类型：1-收款账户 2-供应链金融',
  `RECEIPT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账务系统凭证编号',
  `ACCOUNT_NATURE` tinyint(3) NULL DEFAULT NULL COMMENT '账户属性',
  `AFTER_BALANCE` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易后余额',
  `ACCOUNT_ENTITY_NO` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户主体编号',
  `COMPLETE_AT` datetime NULL DEFAULT NULL COMMENT '记账完成时间',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BANK_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户名',
  `BANK_ACCOUNT_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户号',
  `COUNTRY_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家代码',
  `RESERVE_INFO` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '预留字段信息',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卖家ID',
  `REFERENCE_INFO` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易附言',
  `OPPONENT_INFO` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手方信息',
  `PAYEE_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '收款用户编号',
  `BIZ_ORDER_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务订单类型:ORDER/FEE',
  `BIZ_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务大类,PAYMENT,PAYEE,PAYMENT_FEE,PAYEE_FEE等',
  `STORE_NO` bigint(19) NULL DEFAULT NULL COMMENT '店铺编号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ACCOUNT_REQ_ID`(`ACCOUNT_REQ_ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6342004 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '账务请求订单表' ROW_FORMAT = Dynamic;

