  `FOREIGN_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '外币币种',
  `PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品大类',
  `SUB_PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品细类',
  `FUNDING_CHANNEL` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '资金渠道大类',
  `SUB_FUNDING_CHANNEL` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '资金渠道细类',
  `EXCHANGE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '汇率',
  `DOMESTIC_AMOUNT` decimal(19, 3) NULL DEFAULT NULL COMMENT '本币金额',
  `FOREIGN_AMOUNT` decimal(19, 3) NULL DEFAULT NULL COMMENT '外币金额',
  `CANCEL_REQ_ID` bigint(20) NULL DEFAULT NULL COMMENT '撤掉订单账务系统请求流水号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `OPERATOR_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '操作类型: 1-正常 2-定时补录  3-手动补录',
  `REQUEST_BUSINESS_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '请求业务类型：1-收款账户 2-供应链金融',
  `RECEIPT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账务系统凭证编号',
  `ACCOUNT_NATURE` tinyint(3) NULL DEFAULT NULL COMMENT '账户属性',
  `AFTER_BALANCE` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易后余额',
  `ACCOUNT_ENTITY_NO` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户主体编号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ACCOUNT_REQ_ID`(`ACCOUNT_REQ_ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '账务请求订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ACC_AUTH_RECOR
-- ----------------------------
DROP TABLE IF EXISTS `T_ACC_AUTH_RECOR`;
CREATE TABLE `T_ACC_AUTH_RECOR`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `OCCUR_TIME` timestamp NOT NULL COMMENT '交易发生时间',
  `TRANS_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种',
  `TRANS_CURRENCY_AMT` decimal(19, 2) NOT NULL COMMENT '交易币种金额',
  `TRANS_RATE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种转换率',
  `LOCAL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡币种',
  `LOCAL_CURRENCY_AMT` decimal(19, 2) NOT NULL COMMENT '卡本币种交易金额',
  `RESP_CODE` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易响应码',
  `RESP_CODE_DESC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易响应码描述',
  `APPROVAL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '授权码',
  `DECLINE_REASON` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易拒绝原因',
  `MESSAGE_TYPE` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '信息类型',
  `MESSAGE_TYPE_DESC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '信息类型描述',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uidx_approval_code`(`APPROVAL_CODE`) USING BTREE,
  UNIQUE INDEX `uidx_reocrd_no`(`RECORD_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '授权交易记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_AGENT_AGREEMENT
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_AGREEMENT`;
CREATE TABLE `T_AGENT_AGREEMENT`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代理商号',
  `SETTLE_CCY` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'CNH' COMMENT '结算币种（USD/CNH）默认CNH',
  `AGREEMENT` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '协议，DFS地址',
  `AGREEMENT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `AGREEMENT_URL` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '协议文件下载地址',
  `IS_SHARE` tinyint(2) NOT NULL COMMENT '是否参与收付款分润: 1-是；2-否',
  `IS_VCC_SHARE` tinyint(2) NOT NULL COMMENT '是否参与VCC分润: 1-是；2-否',
  `IS_RECENT_RULE` tinyint(2) NOT NULL COMMENT '规则是否最新: 1-是；2-否',
  `IS_REPORT_AGREEMENT` tinyint(2) NOT NULL COMMENT '报表组装是否带协议: 1-是；2-否',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_AGENT`(`AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 170152 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商协议信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_AGENT_CHANNEL_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_CHANNEL_CONFIG`;
CREATE TABLE `T_AGENT_CHANNEL_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代理商号',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `SELL_CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '卖出渠道编号',
  `CLOSING_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '交割模式',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `BIZ_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '业务类型：1-兑换服务（汇率），2-结汇下发,3-电商收款，4-B2B收款，5-虚拟信用卡',
  `CCY_PAIR` varchar(31) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '货币对',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_TYPE`(`AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商汇率渠道配置' ROW_FORMAT = Dynamic;

