-- ----------------------------
-- Table structure for T_AGENT_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_INFO`;
CREATE TABLE `T_AGENT_INFO`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商号',
  `AGENT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商名称',
  `AGENT_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '代理商类型: 1-个人 2-企业 3-销售',
  `ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '代理商证件类型：1-身份证 2-护照 3-驾照',
  `ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号',
  `LEGAL_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '法人名称',
  `SETTLE_STATE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '代理商结算状态：0-未结算，1-已结算',
  `COUNTRY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家',
  `TEL` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电话',
  `POST_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮编',
  `ADDRESS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '公司地址',
  `PHONE_NUMBER` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `EMAIL` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `CONTRACT_ENTITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '签约主体',
  `CONTRACT_DATE` timestamp NULL DEFAULT NULL COMMENT '签约日期',
  `QR_CODE` bigint(19) NULL DEFAULT NULL COMMENT '二维码',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CONTRACT_TERM` timestamp NULL DEFAULT NULL COMMENT '合同有效期',
  `SALE_AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商号(销售)',
  `AGENT_STATE` tinyint(2) NULL DEFAULT 0 COMMENT '代理商状态：0：正常，1：暂停，2：关闭',
  `WAIT_RETURN_VISIT_MAX` int(2) NULL DEFAULT NULL COMMENT '待回访限额',
  `SEND_ADDRESS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '多个地址时使用;分割',
  `CLIENT_PHONE_HIDE` tinyint(2) NULL DEFAULT 1 COMMENT '客户端手机号隐藏标识 1: 展示 2: 隐藏',
  `SIGNING_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '签约状态：1：生效，2：失效，3：待续约',
  `NOTICE_STATUS` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'Y' COMMENT '是否通知：Y-通知开启，N-通知关闭',
  `PRODUCT_TAG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品标签',
  `TEAM_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '销售小组，DIC_SALE_GROUP（编号-销售小组-销售组长名称）',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_AGENT_NO`(`AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2265 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商信息表' ROW_FORMAT = Dynamic;

