  INDEX `IDX_AGENT_NO`(`AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 121 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商推广链接表' ROW_FORMAT = Dynamic;

-- ----------------------------
