-- ----------------------------
-- Table structure for T_AGENT_SALES_KPI_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_SALES_KPI_INFO`;
CREATE TABLE `T_AGENT_SALES_KPI_INFO`  (
  `id` int(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '销售编号',
  `DIMENSION_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '统计维度：（1-按BU，2-按客群，3-按小组，4-按个人）',
  `DIMENSION_VALUE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '统计维度值，BU/KEQUN/SALE_GROUP ',
  `METRIC_CATEGORY` tinyint(2) NULL DEFAULT NULL COMMENT '统计指标大类，DIC_KPI_TYPE（1-毛利（单位：万人民币））',
  `METRIC_SUBCATEGORY` tinyint(2) NULL DEFAULT NULL COMMENT '统计指标细类，DIC_PROFIT_TYPE（1-常规业务，2-OZ+AE+WB+JOOM）',
  `GROUP_ID` int(20) NULL DEFAULT NULL COMMENT '销售分组ID，对应T_AGENT_SALES_GROUP表ID字段',
  `STAT_YEAR` int(11) NOT NULL COMMENT 'KPI年份（yyyy）',
  `TARGET_YEAR` decimal(20, 4) NOT NULL COMMENT '年目标值（1-12月份总值）',
  `TARGET_JAN` decimal(20, 4) NULL DEFAULT NULL COMMENT '1月目标值',
  `TARGET_FEB` decimal(20, 4) NULL DEFAULT NULL COMMENT '2月目标值',
  `TARGET_MAR` decimal(20, 4) NULL DEFAULT NULL COMMENT '3月目标值',
  `TARGET_APR` decimal(20, 4) NULL DEFAULT NULL COMMENT '4月目标值',
  `TARGET_MAY` decimal(20, 4) NULL DEFAULT NULL COMMENT '5月目标值',
  `TARGET_JUN` decimal(20, 4) NULL DEFAULT NULL COMMENT '6月目标值',
  `TARGET_JUL` decimal(20, 4) NULL DEFAULT NULL COMMENT '7月目标值',
  `TARGET_AUG` decimal(20, 4) NULL DEFAULT NULL COMMENT '8月目标值',
  `TARGET_SEP` decimal(20, 4) NULL DEFAULT NULL COMMENT '9月目标值',
  `TARGET_OCT` decimal(20, 4) NULL DEFAULT NULL COMMENT '10月目标值',
  `TARGET_NOV` decimal(20, 4) NULL DEFAULT NULL COMMENT '11月目标值',
  `TARGET_DEC` decimal(20, 4) NULL DEFAULT NULL COMMENT '12月目标值',
  `IMPORT_TIME` timestamp NULL DEFAULT NULL COMMENT '导入时间',
  `REMARKS` varchar(254) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `DELETE_FLAG` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '删除标识，Y-删除，N-正常',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `IDX_YEAR`(`STAT_YEAR`) USING BTREE,
  INDEX `IDX_SALE`(`AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '销售KPI指标信息表' ROW_FORMAT = Dynamic;

