  `SETTLE_STATE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '分润结算状态：0-未结算，1-已结算',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现明细编号',
  `WITHDRAW_AMT` decimal(19, 2) NOT NULL COMMENT '提现目标(人民币)金额',
  `WITHDRAW_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现目标币种',
  `WITHDRAW_AT` timestamp NULL DEFAULT NULL COMMENT '提现完成时间',
  `SHARE_PROFIT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '分润币种',
  `SHARE_PROFIT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '分润金额(代理商)',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RECEIPT_NO` bigint(20) NULL DEFAULT NULL COMMENT '凭证编号',
  `WITHDRAW_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现汇率',
  `WITHDRAW_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '提现手续费',
  `SHARE_PROFIT_PERCENT` decimal(19, 3) NULL DEFAULT NULL COMMENT '分润百分比',
  `WITHDRAW_SOURCE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '提现金额',
  `WITHDRAW_SOURCE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现币种',
  `SALE_SHARE_TRADE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '销售交易量提成',
  `SALE_SHARE_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '销售手续费提成',
  `SALE_SHARE_DESERVED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '销售分润金额（销售应得提成）',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商分润明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_AGENT_SHARE_RULE
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_SHARE_RULE`;
CREATE TABLE `T_AGENT_SHARE_RULE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键编号',
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商号',
  `SHARE_PROFIT_PERCENT` decimal(19, 3) NULL DEFAULT NULL COMMENT '分润百分比，(商户手续费率 - 费率成本) * 分润百分比为代理商所得到的分润金额',
  `STATUS` int(2) NOT NULL COMMENT '分润比设置状态：1-已设置，2-未设置',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `RATE_COST` decimal(19, 3) NULL DEFAULT NULL COMMENT '费率成本，给商户的最低成本',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4408 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商分润百分比设置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_AGENT_SHARE_SUMMARY
-- ----------------------------
DROP TABLE IF EXISTS `T_AGENT_SHARE_SUMMARY`;
CREATE TABLE `T_AGENT_SHARE_SUMMARY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
