  `TRANSFER_DATE` timestamp NOT NULL COMMENT '付款成功时间',
  `ACCOUNT_TAIL` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款尾号',
  `TRANSFER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `TRANSFER_AMT` decimal(19, 3) NOT NULL COMMENT '付款金额',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `STORE_NO` bigint(20) NOT NULL COMMENT '店铺编号',
  `STORE_PLATFORM` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '店铺平台',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `FINANCIAL_EVENT_GROUP_ID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '亚马逊付款编号',
  `CHECK_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '对账状态：0-初始，1-对账成功',
  `DETAIL_ID` bigint(20) NULL DEFAULT NULL COMMENT '收支明细编号，对应T_PAYMENT_DETAIL中DETAIL_ID,只有对账成功时有值',
  `ORIGINAL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原币种',
  `ORIGINAL_AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '原始金额',
  `RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '汇率',
  `FINANCIAL_EVENT_GROUP_START` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单开始时间',
  `FINANCIAL_EVENT_GROUP_END` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单结束时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

