  `CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡号',
  `PHONE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户在银行办理银行卡预留的手机号码',
  `BANK_CARD_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '银行卡类型 1-借记卡 2-银行账户 3-存折',
  `BANK_CARD_VALIDDATE` date NULL DEFAULT NULL COMMENT '银行卡有效期',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `AUTH_REQ_NO` bigint(20) NULL DEFAULT NULL COMMENT '认证请求流水号',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1842 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '银行账户信息库表' ROW_FORMAT = Dynamic;

