-- ----------------------------
-- Table structure for T_B2B_EXTERNAL_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_B2B_EXTERNAL_ORDER`;
CREATE TABLE `T_B2B_EXTERNAL_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `MASTER_ORDER_ID` bigint(20) NOT NULL DEFAULT 0 COMMENT '主订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖家编号',
  `USER_TRANS_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单号(商户订单号)',
  `TRADE_AT` timestamp NOT NULL COMMENT '交易时间',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种，一般是外币',
  `BUY_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '买家姓名',
  `BUY_ACC_NO` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买家帐号',
  `STATE` tinyint(2) NULL DEFAULT NULL COMMENT '-1：不可用  0-未使用 1-已使用 2-使用中，3-部分使用，4-已关联,5-未关联，6-部分关联 9-已作废',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `RELATED_PAYEE_ORDER_ID` bigint(20) NULL DEFAULT NULL COMMENT '关联入账交易订单号',
  `ORIGINAL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原币种',
  `ORIGINAL_AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '原始金额',
  `PLATFORM_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '平台类型：1-亚马逊 2-eBay 3-乐天，6-GEP兑换上传订单',
  `ID_CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国别代码',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '文件批次号',
  `WITHDRAW_ID` bigint(19) NULL DEFAULT 0 COMMENT '提现单号',
  `AVAILABLE_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '可使用订单金额',
  `SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇申请金额',
  `SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结汇申请币种',
  `SETTLE_FCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇的外币金额',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人帐号',
  `ORDER_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '订单类型：1-电商平台获取，2-电商平台人工上传，3-结汇明细订单 4-B2B收款结汇明细',
  `STORE_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺链接',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `PARENT_ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '父类订单号',
  `INDUSTRY_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型：01：货物贸易，06：物流，07：软件服务，08：广告，09：B2B货物贸易',
  `ORI_USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户订单号',
  `ORI_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '原用户号',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `WORDS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '敏感词',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `PICK_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '拆单和凑单时外币金额',
  `SETTLE_DIFF_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇差额',
  `SETTLE_FLAG` tinyint(2) NULL DEFAULT 1 COMMENT '结汇类型：0-无需结汇 1-普通结汇 2-报关结汇',
  `SWITCH_AUDIT_STATUS` tinyint(2) NULL DEFAULT -1 COMMENT '结汇切换审核状态：-1 初始（未切换） 0-结汇切换待审核 1-结汇切换审核驳回 2-结汇切换审核成功 3-结汇切换审核拒绝',
  `USER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  `QUOTA_CHANGE_TYPE` tinyint(4) NOT NULL DEFAULT 1 COMMENT '额度变更类型：1-关联额度 2-结汇额度',
  `ORDER_SRC_TYPE` tinyint(1) NULL DEFAULT 2 COMMENT '订单来源：2-商户提交 3-运营人员提交',
  `RELATED_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账关联金额',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RELATED_USER_TRANS_ID`(`USER_NO`, `RELATED_PAYEE_ORDER_ID`, `USER_TRANS_ID`) USING BTREE,
  INDEX `IDX_WITHDRAW_ID`(`WITHDRAW_ID`) USING BTREE,
  INDEX `IDX_EX_ORDER_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_EX_ORDER_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_TRADE_AT`(`TRADE_AT`) USING BTREE,
  INDEX `IDX_ORI_USER_TRANS_ID`(`ORI_USER_TRANS_ID`) USING BTREE,
  INDEX `IDX_USER_TRANS_ID`(`USER_TRANS_ID`) USING BTREE,
  INDEX `IDX_RELATED_PAYEE_ORDER_ID`(`RELATED_PAYEE_ORDER_ID`) USING BTREE,
  INDEX `IDX_PARENT_ORDER_ID`(`PARENT_ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12181 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'B2B外部订单明细表' ROW_FORMAT = Dynamic;

