-- Table structure for T_B2B_EXTERNAL_ORDER_MASTER
-- ----------------------------
DROP TABLE IF EXISTS `T_B2B_EXTERNAL_ORDER_MASTER`;
CREATE TABLE `T_B2B_EXTERNAL_ORDER_MASTER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
