  INDEX `IDX_ORI_USER_TRANS_ID`(`ORI_USER_TRANS_ID`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3473 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'B2B外部订单明细主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_B2B_REISSUE_AUDIT_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_B2B_REISSUE_AUDIT_ORDER`;
CREATE TABLE `T_B2B_REISSUE_AUDIT_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '原付款订单表中的付款订单号',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '重新出款的请求流水号',
  `PAYEE_ID_TYPE` tinyint(255) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人名称',
  `CARD_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人账号',
  `BANK_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行名称',
  `BANK_BRANCH_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支行名称',
  `CLEARING_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行代码',
  `CITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '市',
  `PROVINCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省',
  `AUDIT_STATUS` tinyint(2) NOT NULL COMMENT '审核状态：1-待审核，2-审核成功，3-审核失败 4-系统自动审核通过 5-系统自动审核失败',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `TO_MEMBER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客反馈',
  `ACCOUNT_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '银行账户记录编号',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `PARTNER_MATERIAL_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人合作文件名称',
  `PARTNER_MATERIAL` bigint(19) NULL DEFAULT NULL COMMENT '收款人合作材料文件id',
  `PARTNER_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '合作方类型:1-个人 2-企业 3-香港企业 4-香港个人 5-第三方个人 6-第三方企业',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '风控检查时间',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RECORD_ID`(`RECORD_ID`) USING BTREE COMMENT '重新出款流水号唯一索引',
  INDEX `IDX_CREATE_AT_USER`(`CREATE_AT`, `USER_NO`) USING BTREE COMMENT '创建时间+用户号普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 435 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'B2B重新出款审核订单表' ROW_FORMAT = Dynamic;

