-- ----------------------------
-- Table structure for T_B2B_TRADE_RISK
-- ----------------------------
DROP TABLE IF EXISTS `T_B2B_TRADE_RISK`;
CREATE TABLE `T_B2B_TRADE_RISK`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAIL_ID` bigint(19) NOT NULL COMMENT '过风控业务订单编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `TRADE_TYPE` tinyint(2) NOT NULL COMMENT '业务或交易类型：1-入账材料',
  `RISK_TYPE` tinyint(2) NOT NULL COMMENT '风控类型：1-买家名称-黑名单 2-禁止国家 3-风险国家 4-买家名称-反洗钱名单 5-买家名称-疑似支付机构 6-买家名称-敏感词 7-商品名称-敏感词 8-订单金额限额 9-预计发货时间 10-历史材料审核情况 11-本订单历史驳回情况',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控验证状态:0-初始化 1-通过 2-不通过 3-处理中 4-异常待验证',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过风控时间',
  `RISK_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `REMARKS` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `BIZ_ID` bigint(19) NULL DEFAULT NULL COMMENT '关联的业务ID',
  `CONTENT` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '过风控内容',
  `DELETE_FLAG` tinyint(2) NULL DEFAULT 1 COMMENT '状态:0 删除 1正常',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_DETAIL_ID_TRADE_TYPE_FLAG`(`DETAIL_ID`, `USER_NO`, `TRADE_TYPE`, `RISK_TYPE`, `DELETE_FLAG`) USING BTREE COMMENT 'B2B风控规则组合索引'
) ENGINE = InnoDB AUTO_INCREMENT = 46810 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'B2B业务交易风控信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
