  `TRADE_DIRECTION` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易方向：BUY=买入, SELL=卖出',
  `CLOSING_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交割期限',
