  `END_TIME` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '23:59' COMMENT '结束时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CUR_CHANNEL`(`CURRENCY_PAIR`, `CHANNEL_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '余额策略配置表' ROW_FORMAT = Dynamic;

