  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CHANNEL_GROUP`(`CHANNEL_GROUP`) USING BTREE,
  INDEX `IDX_CHANNEL_ID`(`CHANNEL_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道最大开户数配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_BAL_CHANGE
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_BAL_CHANGE`;
CREATE TABLE `T_CHANNEL_BAL_CHANGE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
