  `TRADE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易金额',
  `TRADE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种',
  `TRADE_DATE` datetime NOT NULL COMMENT '余额变动时间',
