  `TRADE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '手续费金额',
  `TRADE_FEE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费币种',
  `BANK_TRADE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行交易编号',
  `TRADE_REF` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易附言',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `BANK_ACC_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手账户名',
  `BANK_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手帐号',
  `BANK_SWIFT_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手银行编号',
  `BANK_COUNTRY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手国家',
  `TRADE_TYPE` tinyint(3) NOT NULL COMMENT '交易类型：1-收入，2-支出',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_CHANNEL_TRADE_ID`(`BANK_TRADE_ID`, `CHANNEL_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 68 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道余额变动记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_DISPATCH_COST
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_DISPATCH_COST`;
CREATE TABLE `T_CHANNEL_DISPATCH_COST`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道id',
  `ARRIVE_COUNTRY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '到账国家/地区',
  `ARRIVE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '到账币种',
  `SOURCE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '源币种',
  `SINGLE_LIMIT` decimal(18, 2) NOT NULL COMMENT '单笔限额',
  `DAY_LIMIT` decimal(18, 2) NOT NULL COMMENT '当日限额',
  `FEE_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用类型，ALL、SWIFT、LOCAL',
  `FEE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用币种',
  `BILLING_WAY` tinyint(2) NOT NULL COMMENT '计费方式，1：单笔，2：费率',
  `SINGLE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '单笔费用',
  `RATE` decimal(19, 2) NULL DEFAULT NULL COMMENT '费率',
  `LOWEST_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '最低费用',
  `HIGHEST_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '最高费用',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态，1：启用，0：禁用',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uidx_channel_country_ccy`(`ARRIVE_COUNTRY`, `ARRIVE_CURRENCY`, `CHANNEL_ID`, `STATUS`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道分发成本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_EXCHANGE_CURRENCY
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_EXCHANGE_CURRENCY`;
CREATE TABLE `T_CHANNEL_EXCHANGE_CURRENCY`  (
