  `TARGET_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '兑换目标币种',
  `STATUS` tinyint(2) NULL DEFAULT 1 COMMENT '状态，1：启用',
