  `CREATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uidx_channel_ccy`(`SOURCE_CURRENCY`, `CHANNEL_ID`, `TARGET_CURRENCY`, `STATUS`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道支持的货币对字典表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_INCOME_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_INCOME_APPLY`;
CREATE TABLE `T_CHANNEL_INCOME_APPLY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
