  `SOURCE_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '转出账户号',
  `DEST_ACC_NO` varchar(129) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标账户号',
  `STATE` tinyint(2) NOT NULL COMMENT '状态，-1-入账失败，0-待入账，1-入账成功',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `CHANNEL_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道成本',
