  `TERMINAL` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '终端编号',
  `PRIVATE_KEY_TEXT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '私钥证书',
  `PUBLIC_KEY_TEXT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '公钥路径',
