) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '大商户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_PAYEE_NOTIFY
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_PAYEE_NOTIFY`;
CREATE TABLE `T_CHANNEL_PAYEE_NOTIFY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `INCOME_NO` bigint(19) NOT NULL COMMENT '入账收汇单号',
