  INDEX `IDX_INCOME_NO`(`INCOME_NO`) USING BTREE,
  INDEX `IDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 439 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道收汇通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_PAYEE_OPERATION
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_PAYEE_OPERATION`;
CREATE TABLE `T_CHANNEL_PAYEE_OPERATION`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAILS_ID` bigint(19) NOT NULL COMMENT '收款明细编号',
  `BANK_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行流水号',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `PAYEE_ACCOUNT_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款银行帐号',
  `PAYEE_ACCOUNT_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款银行账户名称',
  `PAYEE_AMOUNT` decimal(19, 3) NOT NULL COMMENT '收款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款币种',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `REMIT_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '汇款金额',
  `REMIT_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇款币种',
  `REMIT_PAYER_ADDRESS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇款人地址',
  `PAYER_COUNTRY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人国家',
  `PAYER_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人名称',
  `PAYER_ACCOUNT_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人帐号',
  `PAYER_BANK_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款银行名称',
  `PAYER_SWIFT_CODE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款行SWIFT_CODE',
  `BANK_PAYEE_FEE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行入账费用币种',
  `BANK_PAYEE_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行入账费用金额',
  `REFERENCE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易附言',
  `CHANNEL_INCOME_AT` timestamp NULL DEFAULT NULL COMMENT '渠道入账时间',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户编号',
  `BANK_PAYEE_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行入账编号',
  `STATUS` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理状态：PENDING-待处理，PROCESSED-已处理',
  `OPERATION_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理方式：INCOME-入账，REFUND-退款',
  `REFUND_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款方式：原路退回，付款退回',
  `REFUND_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '退款金额',
  `REFUND_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款金额',
  `REFUND_INFO` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退款信息',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `FILE_IDS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件id，多个用英文逗号分隔',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `RESERVE_FIELD` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留字段',
  `DIFF_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '差异类型：LONG-长款，SHORT-短款',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_DETAILS_ID`(`DETAILS_ID`) USING BTREE,
  INDEX `UDX_USER_BANK_CREATE`(`USER_NO`, `BANK_NO`, `CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 106 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '渠道收款运营操作表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_REAL_RATE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_REAL_RATE_CONFIG`;
CREATE TABLE `T_CHANNEL_REAL_RATE_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `CHANNEL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道Id',
  `CURRENCY_PAIR` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '货币对',
  `SORT_ORDER` tinyint(2) NULL DEFAULT NULL COMMENT '排序顺序（值越小越靠前）',
  `STATUS` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'NORMAL' COMMENT '状态（NORMAL-正常，DELETED-删除）',
  `FLOAT_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '浮动类型',
  `FLOAT_VALUE` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '浮动值',
