  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_status_channel_currency`(`STATUS`, `CHANNEL_ID`, `CURRENCY_PAIR`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道实时汇率' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CHANNEL_RECHARGE_TRANSFER
-- ----------------------------
DROP TABLE IF EXISTS `T_CHANNEL_RECHARGE_TRANSFER`;
CREATE TABLE `T_CHANNEL_RECHARGE_TRANSFER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `BATCH_NO` bigint(19) NOT NULL COMMENT '批次号',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '调拨币种',
  `ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '调拨金额',
  `ORDER_TYPE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单类型：2-Payoneer',
  `INCOME_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账金额',
  `ORDER_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '划拨手续费',
  `ORDER_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '调拨状态：0-待处理，1-处理中，2-处理成功，3-处理失败',
  `ORDER_SUCCESS_DATE` datetime NULL DEFAULT NULL COMMENT '划拨完成时间',
  `CHANNEL_PAYER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道调拨交易ID，由清算人员手工输入',
  `VA_PAYER_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT 'VA明细清算出款状态：0-无需出款，1-待出款 2-出款成功 ，3-出款处理中',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_BATCH_NO`(`BATCH_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '清算其他第三方模式充值资金划拨表' ROW_FORMAT = Dynamic;

