-- ----------------------------
-- Table structure for T_CLOSE_USER_PAYEE_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_CLOSE_USER_PAYEE_ACCOUNT`;
CREATE TABLE `T_CLOSE_USER_PAYEE_ACCOUNT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_NO` bigint(20) NOT NULL COMMENT '订单号',
  `ACCOUNT_NO` bigint(20) NOT NULL,
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户编号，提供给商户使用的银行账户',
  `BANK_ACC_CCY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种信息',
  `BANK_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BANK_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行所在国家代码',
  `STATUS` tinyint(2) NOT NULL COMMENT '账户状态：0-注销中，1：注销成功（渠道也已经注销） 2：注销失败 3：禁用（GEP禁用，渠道可用）4:重新启用',
  `ERROR_MSG` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注销失败原因/重启原因',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `SOURCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'SYSTEM' COMMENT '请求来源',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_NO`(`ORDER_NO`) USING BTREE,
  INDEX `IDX_BANK_ACC_NO`(`BANK_ACC_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130787 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收款账户注销信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_CONF_PRIZE
