  `PRIZE_LEVEL_DESC` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '奖品级别描述',
  `PRIZE_PROBABILITY` decimal(3, 0) NOT NULL COMMENT '奖品概率，按照百分比保存，最大100%',
