  `REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退款币种',
  `REFUND_FEE` decimal(18, 2) NULL DEFAULT NULL COMMENT '退款手续费',
  `REFUND_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款手续费币种',
  `STATE` tinyint(3) NOT NULL COMMENT '0#初始化待退款 1#退款中 2#退款成功 3#退款失败 4#用户确认中 6#线下退款中 7#退款待复核 8#无需退款 9#待扣手续费 10#待初审  11#待风控审核 12#退款被退回',
  `AUDIT_STATE` tinyint(3) NOT NULL COMMENT '审核状态: 0#初始待审核 1#清算初审完成；2#清算复审完成；3#清算审核失败；4#风控审核失败',
  `CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退款渠道',
  `CHANNEL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道币种',
  `CHANNEL_ACCT_NO` varchar(80) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道账号',
  `ORIGINAL_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '原渠道编号',
  `CHANNEL_REFUND_STATE` tinyint(3) NULL DEFAULT NULL COMMENT '渠道退款状态：1-初始，2-退款中，3-成功，4-失败，5-异常',
  `REFUND_COST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款成本币种',
  `REFUND_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '退款成本',
  `REFUND_REASON` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款原因',
  `REFUND_BANK_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道流水号',
  `RISK_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核人',
  `RISK_AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '风控审核时间',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核对客备注',
  `AUDIT_INIT_AT` timestamp NULL DEFAULT NULL COMMENT '清算初审时间',
  `AUDIT_INIT_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算初审人',
  `AUDIT_INIT_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审备注',
  `AUDIT_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '清算终审时间',
  `AUDIT_FINAL_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算终审人',
  `AUDIT_FINAL_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '复审备注',
  `REFUND_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '退款完成时间',
  `REFUND_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款时间',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CHANNEL_REFUND_AMT` decimal(18, 2) NULL DEFAULT NULL COMMENT '渠道退款金额',
  `CHANNEL_REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款币种',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_REFUND_ORDER_ID`(`REFUND_ORDER_ID`) USING BTREE,
  INDEX `IDX_ORI_ORDER_ID`(`ORIGINAL_ORDER_ID`) USING BTREE,
  INDEX `IDX_REFUND_FINAL_AT`(`REFUND_FINAL_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '异常入账退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_ORDER_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_ORDER_APPLY`;
CREATE TABLE `T_EXCHANGE_ORDER_APPLY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `EXCHANGE_ID` bigint(19) NOT NULL COMMENT '汇兑订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '代理商户号',
  `AGENT_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户号',
  `CERTIFICATE_ID` bigint(19) NULL DEFAULT NULL COMMENT '证书编号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商户唯一单号',
  `BUY_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '买入币种',
  `SELL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖出币种',
  `TRADE_DIRECTION` tinyint(2) NOT NULL COMMENT '交易方向：1-买入，2-卖出',
  `BUY_AMOUNT` decimal(19, 2) NOT NULL COMMENT '买入金额',
  `SELL_AMOUNT` decimal(19, 2) NOT NULL COMMENT '卖出金额',
  `TRADE_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '交割模式：1-实时兑换，2-预约兑换, 3-挂单换汇',
  `EXCHANGE_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '换汇类型: BALANCE-余额兑换 QUOTA-额度兑换',
  `CLOSING_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易模式：TOD,TOM,SPOT',
  `CLOSING_DATE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交割日期，格式YYYY-MM-DD',
  `DELIVERY_TYPE` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'AUTO' COMMENT '交割方式：AUTO-自动交割 MANUAL-手动交割',
  `TRADE_RATE` decimal(19, 6) NOT NULL COMMENT '交易汇率',
  `TRADE_SOURCE` tinyint(2) NOT NULL COMMENT '交易来源：1-用户前端，2-API请求',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇率编号',
  `ORDER_STATE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '订单状态：0-待确认，1-已确认，2-已取消，3-已过期',
  `AMOUNT_DIRECTION` tinyint(2) NULL DEFAULT NULL COMMENT '固定交易金额方向：1-买入，2-卖出',
  `TRADE_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '交易类型：1-GEP换汇，2-B2B换汇',
  `CURRENCY_PAIR` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '货币对',
  `CALLBACK_URL` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '通知地址',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_EXCHANGE_ID`(`EXCHANGE_ID`) USING BTREE,
  UNIQUE INDEX `UDX_REQ_USER_NO`(`USER_REQ_NO`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 83352 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'API汇兑交易申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_PAYMENT
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_PAYMENT`;
CREATE TABLE `T_EXCHANGE_PAYMENT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '汇款订单号',
  `SOURCE_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户号',
  `SOURCE_AMT` decimal(19, 2) NOT NULL COMMENT '金额',
  `SOURCE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `DEST_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账户号',
  `DEST_ACC_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标账户名称',
  `DEST_AMT` decimal(19, 2) NOT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `REMITTANCE_TYPE` tinyint(2) NOT NULL COMMENT '汇款类型：1-GEP付款，2-渠道付款',
  `REMITTANCE_STATE` tinyint(2) NOT NULL COMMENT '汇款状态：-1-汇款失败，0-待结算 1-待兑换，2-待出款初审，3-待出款复核，4-待出款，5-汇款成功',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '订单完成时间',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `CHANNEL_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道成本',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审人(业务确认)',
  `EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '复核人(清算确认)',
  `REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '复核时间',
  `FEE_BEAR_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '手续费承担方式：1-SHARE，2-OUR',
  `FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户手续费币种',
  `MEMBER_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '商户手续费',
  `BUSINESS_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '业务类型：1-跨境人民币，2-跨境外汇, 3-海外换汇',
  `EXCHANGE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '汇率，单位：100',
  `REQUEST_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '请求流水号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_REQUEST_NO`(`REQUEST_NO`, `USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 87 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '海外换汇付款信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_QUOTA_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_QUOTA_RECORD`;
CREATE TABLE `T_EXCHANGE_QUOTA_RECORD`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `EXCHANGE_ID` bigint(19) NOT NULL COMMENT '汇兑订单号',
  `TRADE_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易类型 TOD TOM SPOT FORWARD',
  `BUSINESS_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '业务类型 GEP-GEP汇兑 B2B-E贸汇',
  `INCOMING_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收支类型 OUT释放 IN占用',
  `QUOTA_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '额度类型 USING-预约使用额度  FREE-免费额度',
  `QUOTA_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '额度币种',
  `BEFORE_QUOTA` decimal(19, 2) NOT NULL COMMENT '变动前额度',
  `QUOTA` decimal(19, 2) NOT NULL COMMENT '变动额度',
  `AFTER_QUOTA` decimal(19, 2) NOT NULL COMMENT '变动后额度',
  `TRADE_DATE` timestamp NOT NULL COMMENT '交易时间',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_EXRECORD_UNIQUE`(`EXCHANGE_ID`, `INCOMING_TYPE`, `QUOTA_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25586 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '换汇额度记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_RATE
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_RATE`;
CREATE TABLE `T_EXCHANGE_RATE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `CHANNEL_ID` int(20) NOT NULL COMMENT '渠道编号',
  `CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `BID_RATE_OF_CCY` decimal(19, 6) NULL DEFAULT NULL COMMENT '现汇买入价',
  `OFR_RATE_OF_CCY` decimal(19, 6) NULL DEFAULT NULL COMMENT '现汇卖出价',
  `BID_RATE_OF_CASH` decimal(19, 6) NULL DEFAULT NULL COMMENT '现钞买入价',
  `OFR_RATE_OF_CASH` decimal(19, 6) NULL DEFAULT NULL COMMENT '现钞卖出价',
  `status` int(1) NOT NULL COMMENT '状态,0:失效,1:生效',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2861 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '汇率表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_SHARE_CCY_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_SHARE_CCY_CONFIG`;
CREATE TABLE `T_EXCHANGE_SHARE_CCY_CONFIG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `AGENT_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '代理商号',
  `EXCHANGE_TYPE` tinyint(2) NOT NULL COMMENT '汇兑类型',
  `CCY_PAIR` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '货币对',
  `TRADE_DIRECTION` tinyint(2) NOT NULL COMMENT '交易方向：1-买入，2-卖出',
  `RATE_SHARE_BP` int(10) NULL DEFAULT NULL COMMENT '代理商分润bp',
  `BEGIN_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '起始值',
  `END_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结束值',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态:1-启用，0-禁用',
  `FEE_STEP` tinyint(2) NOT NULL DEFAULT 0 COMMENT '是否阶梯计费，0-否，1-是',
  `STEP_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '计费阶梯类型，0-按月入账交易量，1-按月结汇交易量',
  `FIXED_FEE_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '固定费返佣类型，0-固定值，1-差价',
  `BEGIN_TIME` date NULL DEFAULT '2000-01-01' COMMENT '有效期开始时间',
  `END_TIME` date NULL DEFAULT '2099-12-31' COMMENT '有效期结束时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_EXCHANGE_TYPE_CCY`(`AGENT_NO`, `EXCHANGE_TYPE`, `CCY_PAIR`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '汇兑分润货币对配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXCHANGE_SHARE_LADDER_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_EXCHANGE_SHARE_LADDER_CONFIG`;
CREATE TABLE `T_EXCHANGE_SHARE_LADDER_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RULE_ID` bigint(19) NOT NULL COMMENT '代理商费率规则编号',
  `BEGIN_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '阶梯起始值，美元金额',
  `END_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '阶梯结束值，美元金额',
  `SHARE_RATE` decimal(19, 4) NOT NULL DEFAULT 100.0000 COMMENT '分润比例，默认100%',
  `RATE_BP` decimal(10, 2) NULL DEFAULT NULL COMMENT '汇率分润bp',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：-1-已删除 1-禁用 2-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_RULE_ID`(`RULE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商汇兑分润规则阶梯明细配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXHIBITION
-- ----------------------------
DROP TABLE IF EXISTS `T_EXHIBITION`;
CREATE TABLE `T_EXHIBITION`  (
  `id` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `exhibition_id` bigint(11) NOT NULL COMMENT '展会id',
  `exhibition_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '展会名称',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `begin_time` timestamp NULL DEFAULT NULL COMMENT '展会开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '展会截至时间',
  `state` tinyint(2) NULL DEFAULT NULL COMMENT '展会状态：-1-禁用 1-正常，',
  `exhibition_no` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '展位号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_id`(`exhibition_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1086 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '展会表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXHIBITION_DATA
-- ----------------------------
DROP TABLE IF EXISTS `T_EXHIBITION_DATA`;
CREATE TABLE `T_EXHIBITION_DATA`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `EXHIBITION_ID` bigint(11) NOT NULL COMMENT '展会编号',
  `TOURIST_NO` bigint(20) NOT NULL COMMENT '游客编号',
  `USER_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户姓名',
  `USER_PHONE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户手机编号',
  `ORG_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '企业名称',
  `USER_IDENTITY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户身份，多个身份用/分隔',
  `TRADE_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型:出口或进口',
  `TRADE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易平台',
  `TRADE_QUOTA` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '销售额',
  `ENROLL_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '登记类型',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `INDUSTRY_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 72 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXTERNAL_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_EXTERNAL_ACCOUNT`;
CREATE TABLE `T_EXTERNAL_ACCOUNT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(19) NULL DEFAULT NULL COMMENT '记录编号',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BRANCH_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分行代码',
  `ACCOUNT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号名',
  `BANK_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行代码/路由编号',
  `DK_IBAN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'DK_IBAN',
  `CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `ACCOUNT_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '账户状态 -1 失效 0-未分配 1-已分配',
  `CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '渠道编号',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `APPLY_ID` bigint(20) NULL DEFAULT NULL COMMENT '申请编号',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2057 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外部渠道账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXTERNAL_ACCOUNT_BILL
-- ----------------------------
DROP TABLE IF EXISTS `T_EXTERNAL_ACCOUNT_BILL`;
CREATE TABLE `T_EXTERNAL_ACCOUNT_BILL`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAIL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账明细唯一流水号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `BUSINESS_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务订单号，后续扩展使用',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BRANCH_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分行代码',
  `BANK_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行四位码',
  `ACCOUNT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号名',
  `BILL_TIME` timestamp NOT NULL COMMENT '入账时间',
  `TIME_ZONE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账国家时区',
  `AMT` decimal(19, 3) NOT NULL COMMENT '入账金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '入账币种',
  `STATUS` tinyint(2) NULL DEFAULT 0 COMMENT '订单状态：0-待入账 1-已结转至待入账 2-已结转至账户余额',
  `CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '渠道编号',
  `SOURCE` tinyint(2) NULL DEFAULT NULL COMMENT '交易来源 0-外部渠道 1-宝付补充',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 222 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外部渠道入账明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXTERNAL_ERROR_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_EXTERNAL_ERROR_ORDER`;
CREATE TABLE `T_EXTERNAL_ERROR_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PLAT_USER_NO` bigint(20) NOT NULL COMMENT '平台商户号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖家编号',
  `USER_TRANS_ID` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单号(商户订单号)',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '文件批次号',
  `ROW_NUM` int(11) NULL DEFAULT NULL COMMENT '错误记录行号',
  `ORI_ORDER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始宝付订单号',
  `ORI_FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '原始文件批次号',
  `ORI_USER_TRANS_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户订单号',
  `FAIL_REASON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `EXT1` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 3) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` timestamp NULL DEFAULT NULL COMMENT '扩展字段8',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_TRANS_ID`(`USER_TRANS_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外部错误订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_EXTERNAL_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_EXTERNAL_ORDER`;
CREATE TABLE `T_EXTERNAL_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖家编号',
  `USER_TRANS_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单号(商户订单号)',
  `TRADE_AT` timestamp NOT NULL COMMENT '交易时间',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种，一般是外币',
  `BUY_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '买家姓名',
  `BUY_ACC_NO` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买家帐号',
  `STATE` tinyint(2) NOT NULL COMMENT '-1：已删除  0-未使用 1-已使用 2-使用中，3-部分使用，4-已关联,5-未关联，6-部分关联',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺编号',
  `ORIGINAL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原币种',
  `ORIGINAL_AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '原始金额',
  `PLATFORM_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '平台类型：1-亚马逊 2-eBay 3-乐天，6-GEP兑换上传订单',
  `ID_CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国别代码',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '文件批次号',
  `WITHDRAW_ID` bigint(19) NULL DEFAULT 0 COMMENT '提现单号',
  `AVAILABLE_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '可使用订单金额',
  `SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇申请金额',
  `SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结汇申请币种',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人帐号',
  `ORDER_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '订单类型：1-电商平台获取，2-电商平台人工上传，3-结汇明细订单 4-B2B收款结汇明细',
  `STORE_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺链接',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `PARENT_ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '父类订单号',
  `INDUSTRY_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型：01：货物贸易，06：物流，07：软件服务，08：广告，09：B2B货物贸易',
  `ORI_USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户订单号',
  `ORI_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '原用户号',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `WORDS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '敏感词',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `PICK_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '拆单和凑单时外币金额',
  `SETTLE_DIFF_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇差额',
  `STORE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台站点',
  `EXT1` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_STORE_TRANS_NO`(`USER_NO`, `STORE_NO`, `USER_TRANS_ID`) USING BTREE,
  INDEX `IDX_WITHDRAW_ID`(`WITHDRAW_ID`) USING BTREE,
  INDEX `IDX_EX_ORDER_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_EX_ORDER_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE,
  INDEX `IDX_ORI_TRANS_ID`(`ORI_USER_TRANS_ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_TRADE_AT`(`TRADE_AT`) USING BTREE,
  INDEX `IDX_USER_TRANS_ID`(`USER_TRANS_ID`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9822930 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外部订单明细表' ROW_FORMAT = Dynamic;

