-- ----------------------------
DROP TABLE IF EXISTS `T_EXTERNAL_ORDER_LOGISTICS`;
CREATE TABLE `T_EXTERNAL_ORDER_LOGISTICS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ORDER_ID` bigint(20) NOT NULL DEFAULT 0 COMMENT '跨境订单号',
  `LOGISTICS_COMPANY_NUMBER` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '快递公司编号（物流公司编号）',
  `LOGISTICS_NUMBER` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物流单号（运单号）',
  `CONSIGNEE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收货人姓名',
