  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录编号',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `SOURCE_CHANNEL_ID` bigint(19) NOT NULL COMMENT '源报价渠道编号',
  `DATE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '时间类型：1-工作日，2-节假日',
  `START_TIME` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '00:00' COMMENT '开始时间',
  `END_TIME` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '23:59' COMMENT '结束时间',
  `SOURCE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原始币种',
  `DEST_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '目标币种',
  `RATE_FLOAT_TYPE` tinyint(4) NOT NULL DEFAULT 1 COMMENT '汇率浮动方式：1-BP，2-百分比',
  `ASK_FLOAT` decimal(19, 2) NOT NULL COMMENT 'ASK汇率浮动值',
  `BID_FLOAT` decimal(19, 2) NOT NULL COMMENT 'BID汇率浮动值',
  `CLOSING_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交割期限：1D,1W,2W,3W,1M',
  `STATE` tinyint(2) NOT NULL COMMENT '状态：1-启用，2-禁用',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CHANNEL_CCY`(`CHANNEL_ID`, `SOURCE_CCY`, `DEST_CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Forward渠道汇率加点表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_FUND_CENTER_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_FUND_CENTER_ORDER`;
CREATE TABLE `T_FUND_CENTER_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '交易订单号',
  `TRADE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '交易类型 1-收入提取 2-货币兑换 4-资金调拨-分发 5-资金调拨-划拨 6-资金调拨-VCC 7-余额清退',
  `PAY_CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '付款渠道编号',
  `SOURCE_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方账号',
  `SOURCE_ACC_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方名称',
  `SOURCE_AMT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `SOURCE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `SOURCE_RECORD_NO` bigint(20) NOT NULL COMMENT '付款账户记录编号',
  `RECEIVED_CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '收款渠道编号',
  `DEST_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款方账号',
  `DEST_ACC_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款方名称',
  `DEST_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '收款金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款币种',
  `DEST_RECORD_NO` bigint(20) NOT NULL COMMENT '收款账户记录编号',
  `FEE_BEAR_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '手续费承担方式:SHA,OUR',
  `PAYMENT_REMARK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易附言',
  `PAYMENT_MODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款清算方式：SWIFT、LOCAL等',
  `ARRIVED_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实际出款金额币种',
  `ARRIVED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '实际出款金额',
  `CAL_DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实际计算收款兑换币种',
  `CAL_DEST_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '实际计算兑换收款金额',
  `CAL_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '实际计算收款兑换汇率',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '汇款状态:1-待审核，2-待出款，3-出款中，4-已出款，5-已入账 6-已取消',
  `API_FLAG` tinyint(1) NULL DEFAULT NULL COMMENT '是否走api 0-否,1-是',
  `EXCHANGE_TRADE_PARTY` tinyint(1) NULL DEFAULT NULL COMMENT '汇兑发生方 1-收款 2-付款',
  `POBO_PAY` tinyint(1) NULL DEFAULT 0 COMMENT '是否POBO付款，0-否，1-是',
  `CURRENCY_PAIR` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '货币对 格式为USD/CNH ',
  `PAY_TRADE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '出款汇率',
  `RECEIVED_TRADE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '收款汇率',
  `REMITTANCE_AT` timestamp NULL DEFAULT NULL COMMENT '汇款时间',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '订单完成时间',
  `COLLECTION_CHANNEL_SERIAL_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款渠道流水号',
  `PAYMENT_CHANNEL_SERIAL_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款渠道流水号',
  `USER_REQ_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户请求订单号',
  `PAYER_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'pobo付款人姓名',
  `PAYER_ID_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'pobo付款人证件号',
  `PAYER_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'pobo付款人地址',
  `PAYER_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'pobo付款人国别',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `TRADE_SOURCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易来源',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `VIRTUAL_USD_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '虚拟美金币种',
  `VIRTUAL_USD_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '虚拟美金金额',
  `DEST_COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款行国家',
  `OLD_ORDER_ID` bigint(20) NULL DEFAULT NULL COMMENT '原交易订单号',
  `ACTUAL_PAY_AT` timestamp NULL DEFAULT NULL COMMENT '实际出款时间',
  `CANCEL_REASON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '撤销原因',
  `CANCEL_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '撤销操作人',
  `CANCEL_AT` timestamp NULL DEFAULT NULL COMMENT '撤销操作时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_USER_REQ_NO`(`USER_REQ_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 626 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '资金中心交易订单表' ROW_FORMAT = Dynamic;

