  `COLLECTION_CHANNEL_SERIAL_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款渠道流水号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '资金调拨交易订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_FX_PROFIT_SHARE_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_FX_PROFIT_SHARE_DETAIL`;
CREATE TABLE `T_FX_PROFIT_SHARE_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `RECORD_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配置ID',
  `MONTH_DATE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账单月份',
  `CHANNEL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '渠道编码',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '币种',
  `TOTAL_PROFIT` decimal(19, 2) NOT NULL COMMENT '总损益',
  `MON_PROFIT` decimal(19, 2) NOT NULL COMMENT '月总损益',
  `SALE_MON_PROFIT` decimal(19, 2) NOT NULL COMMENT '销售当月损益',
  `TRADE_MON_PROFIT` decimal(19, 2) NOT NULL COMMENT '交易员当月损益',
  `STATUS` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'S' COMMENT '是否有效 S有效 F无效',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_DATE_MONTH`(`MONTH_DATE`, `CURRENCY`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 262 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小币种损益分摊表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_FX_SALE_PROFIT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_FX_SALE_PROFIT_DETAIL`;
CREATE TABLE `T_FX_SALE_PROFIT_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `RECORD_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '配置ID',
  `MONTH_DATE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账单月份',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `USER_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '币种',
  `SALE_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '销售编码',
  `SALE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '销售名称',
  `SALE_PROFIT` decimal(19, 2) NOT NULL COMMENT '销售损益',
  `SELL_AMT` decimal(19, 2) NOT NULL COMMENT '卖出金额',
  `SELL_PROFIT` decimal(19, 2) NOT NULL COMMENT '销售当月损益',
  `BUY_AMT` decimal(19, 2) NOT NULL COMMENT '买入金额',
  `BUY_PROFIT` decimal(19, 2) NOT NULL COMMENT '买入损益',
  `STATUS` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'S' COMMENT '是否有效 S有效 F无效',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_YEAR_MONTH`(`MONTH_DATE`, `USER_NO`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 225 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小币种销售损益表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_ADVANCE_CHANNEL_RUT
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_ADVANCE_CHANNEL_RUT`;
CREATE TABLE `T_GEP_ADVANCE_CHANNEL_RUT`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ROUTE_ID` bigint(19) NOT NULL COMMENT '路由策略编号',
  `ROUTE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '路由类型：1-标准、2-备用（在特定错误码下重新获取路由）',
  `PRODUCT_ID` bigint(19) NOT NULL COMMENT '产品编号',
  `INDUSTRY_TYPE` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '行业类型：01-货物贸易、06-物流、07-软件服务、08-广告、09-B2B货物贸易、10-职工报酬、11-赡家款、12-佣金',
  `PAYEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人类型：1-对公，2-对私',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `PRIORITY` tinyint(3) NOT NULL DEFAULT 1 COMMENT '路由优先级：1-100',
  `WEIGHT` tinyint(3) NOT NULL DEFAULT 100 COMMENT '路由权重：0-100',
  `STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '状态：0-可用，1-禁用',
  `BEGIN_TIME` timestamp NULL DEFAULT NULL COMMENT '路由启用时间点',
  `END_TIME` timestamp NULL DEFAULT NULL COMMENT '路由停用时间点',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ROUTE_ID`(`ROUTE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP结汇垫资渠道路由表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_ADVANCE_CHANNEL_RUT_KEY
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_ADVANCE_CHANNEL_RUT_KEY`;
CREATE TABLE `T_GEP_ADVANCE_CHANNEL_RUT_KEY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ROUTE_ID` bigint(19) NOT NULL COMMENT '路由策略编号',
  `KEY_TYPE` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '路由策略对象类型：01-用户号（会员号）、02-会员分组、03-时间区间、04-时间分组、05-垫资额度、06-交易金额',
  `SCOPE_RULE` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '策略对象作用范围规则：01-等于、02-不等于、03-大于、04-大于等于、05-小于、06-小于等于、07-包含、08-不包含',
  `KEY_VALUE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '路由策略对象值',
  `KEY_DESC` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '路由策略对象值描述',
  `STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '状态：-1-删除 0-可用，1-禁用',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ROUTE_ID`(`ROUTE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP结汇垫资渠道路由策略要素明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_ADVANCE_QUOTA_CHANNEL
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_ADVANCE_QUOTA_CHANNEL`;
CREATE TABLE `T_GEP_ADVANCE_QUOTA_CHANNEL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `QUOTA_ID` bigint(19) NOT NULL COMMENT '垫资额度记录编号',
  `CHANNEL_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道名称',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_CHANNEL_ID`(`CHANNEL_ID`) USING BTREE,
  INDEX `IDX_QUOTA_ID`(`QUOTA_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP结汇垫资额度关联渠道表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_CHANNEL_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_CHANNEL_INFO`;
CREATE TABLE `T_GEP_CHANNEL_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CHANNEL_NO` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道号',
  `INTERFACE_STATUS` enum('CONNECTED','NOT_CONNECTED') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对接状态',
  `CHANNEL_NAME_INTERNAL` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道产品名内部用',
  `CHANNEL_NAME_EXTERNAL` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道外部名',
  `BANK_NAME` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BUSINESS_TYPE` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务类型',
  `SUPPORTED_INDUSTRY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持行业',
  `ACCOUNT_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '账户类型: 1-全球收款账户 2-本地收款账户',
  `ACCOUNT_OPENING_SITE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户地',
  `CURRENCY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持入账币种',
  `INCOMING_REGION` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来款地区',
  `ACCOUNT_EXPIRY_TERM` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号有效期',
  `OPENING_PROCESS_DURATION` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户时效',
  `CREDIT_PROCESSING_DURATION` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账时效',
  `SUPPORTED_GATEWAYS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持的收单网关',
  `HOLDER_REGION_LIMIT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户主体地区限制',
  `HOLDER_TYPE_LIMIT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户主体类型限制',
  `TOTAL_ACCOUNT_LIMIT` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '总账户数限制',
  `PER_MERCHANT_ACCOUNT_LIMIT` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单二级商户可申请账户数',
  `SINGLE_CREDIT_MIN` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单笔入账下限',
  `SINGLE_CREDIT_MAX` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单笔入账上限',
  `OPENING_REPORTING` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户报备',
  `ACCOUNT_REPORTING` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账报备',
  `CREDIT_PROOF_REQUIREMENTS` tinyint(1) NULL DEFAULT NULL COMMENT '入账凭证要求',
  `CUSTOM_HOLDER_ALLOWED` tinyint(1) NULL DEFAULT 0 COMMENT '支持自定义账户持有人',
  `MICRO_VERIFICATION_ENABLED` tinyint(1) NULL DEFAULT 0 COMMENT '支持小额、账户验证',
  `BILL_PROOF_PROVIDED` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提供账单证明信',
  `RISK_RULES` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '风控规则/调单规则',
  `REFUND_MODE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款模式',
  `EXTERNAL_REMARKS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '对外备注',
  `INTERNAL_REMARKS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '对内备注',
  `CHANNEL_COST_STRUCTURE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道成本结构化',
  `BLACKLIST_CHECK` tinyint(1) NULL DEFAULT 0 COMMENT '过渠道黑名单检查',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `DELETE_FLAG` tinyint(1) NULL DEFAULT NULL COMMENT '删除标记',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_CHANNEL_NO`(`CHANNEL_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '产品渠道表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_EXTERNAL_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_EXTERNAL_ORDER`;
CREATE TABLE `T_GEP_EXTERNAL_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卖家编号',
  `USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单号(商户订单号)',
  `TRADE_AT` timestamp NOT NULL COMMENT '交易时间',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种，一般是外币',
  `BUY_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买家姓名',
  `BUY_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '买家帐号',
  `STATE` tinyint(2) NOT NULL COMMENT '-1：已删除  0-未使用 1-已使用 2-使用中，3-部分使用，4-已关联,5-未关联，6-部分关联',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺编号',
  `ORIGINAL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原币种',
  `ORIGINAL_AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '原始金额',
  `PLATFORM_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '平台类型：1-亚马逊 2-eBay 3-乐天，6-GEP兑换上传订单',
  `ID_CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国别代码',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '文件批次号',
  `WITHDRAW_ID` bigint(19) NULL DEFAULT 0 COMMENT '提现单号',
  `AVAILABLE_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '可使用订单金额',
  `SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇申请金额',
  `SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结汇申请币种',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人帐号',
  `ORDER_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '订单类型：1-电商平台获取，2-电商平台人工上传，3-结汇明细订单 4-B2B收款结汇明细',
  `STORE_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺链接',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `PARENT_ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '父类订单号',
  `INDUSTRY_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型：01：货物贸易，06：物流，07：软件服务，08：广告，09：B2B货物贸易',
  `ORI_USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户订单号',
  `ORI_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '原用户号',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `WORDS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '敏感词',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `PICK_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '拆单和凑单时外币金额',
  `SETTLE_DIFF_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇差额',
  `EXT1` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 3) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` timestamp NULL DEFAULT NULL COMMENT '扩展字段8',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_TRANS_NO`(`USER_TRANS_ID`, `USER_NO`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_WITHDRAW_ID`(`WITHDRAW_ID`) USING BTREE,
  INDEX `IDX_EX_ORDER_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE,
  INDEX `IDX_EX_ORDER_CREATE_AT`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_ORI_TRANS_ID`(`ORI_USER_TRANS_ID`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9759784 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外部订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_EXTERNAL_ORDER_NEW
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_EXTERNAL_ORDER_NEW`;
CREATE TABLE `T_GEP_EXTERNAL_ORDER_NEW`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT 'GEP订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商户订单号',
  `TRADE_AT` timestamp NOT NULL COMMENT '交易时间',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种 一般是外币',
  `STATE` tinyint(2) NOT NULL COMMENT '-1-已删除 0-未使用 1-已使用 2-使用中 3-部分使用',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `ORIGINAL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原币种',
  `ORIGINAL_AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '原始金额',
  `PLATFORM_NAME` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台名称',
  `ID_CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国别代码',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '文件批次号',
  `WITHDRAW_ID` bigint(19) NULL DEFAULT 0 COMMENT '提现单号',
  `AVAILABLE_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '可使用订单金额',
  `SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇申请金额',
  `SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结汇申请币种',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型:1-身份证,2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ACC_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人账号',
  `ORDER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '订单类型:5-GEP结汇付款文件',
  `PARENT_ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '父类订单号',
  `INDUSTRY_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型:01-货物贸易,06-物流,07-软件服务等',
  `ORI_USER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户订单号',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词:1-是 0-否',
  `WORDS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '敏感词',
  `PICK_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '拆单和凑单时外币金额',
  `SETTLE_DIFF_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结汇差额',
  `AUDIT_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '拆单时的标识用',
  `EXT1` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '扩展字段1',
  `EXT2` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_TRANS_NO`(`USER_TRANS_ID`, `USER_NO`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_WITHDRAW_ID`(`WITHDRAW_ID`) USING BTREE,
  INDEX `IDX_EX_ORDER_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE,
  INDEX `IDX_EX_ORDER_CREATE_AT`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_ORI_TRANS_ID`(`ORI_USER_TRANS_ID`, `USER_NO`) USING BTREE,
  INDEX `IDX_USER_TRADE_AT`(`USER_NO`, `TRADE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4801 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '新版结汇付款外部订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_PRODUCT_CHANNEL_ROUTE
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_PRODUCT_CHANNEL_ROUTE`;
CREATE TABLE `T_GEP_PRODUCT_CHANNEL_ROUTE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PRODUCT_NO` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品号',
  `CHANNEL_NO` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道号',
  `PRIORITY` int(11) NULL DEFAULT NULL COMMENT '优先级',
  `VERIFICATION_STATUS` enum('VERIFIED','NOT_VERIFIED') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品渠道验证现状',
  `INTERNAL_REMARKS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '对内备注',
  `ROUTING_STRATEGY` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '路由策略',
  `STATUS` tinyint(1) NOT NULL COMMENT '状态：1-启用，0-禁用',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_GEP_CHANNEL_RELATION`(`PRODUCT_NO`, `CHANNEL_NO`) USING BTREE,
  INDEX `IDX_CHANNEL_NO`(`CHANNEL_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 172 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP产品和渠道的关系路由表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_PRODUCT_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_PRODUCT_INFO`;
CREATE TABLE `T_GEP_PRODUCT_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PRODUCT_NO` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品号',
  `EXTERNAL_STATUS` enum('OPEN','CLOSE') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对外状态',
  `IS_KEY_PRODUCT` tinyint(1) NULL DEFAULT 0 COMMENT '是否重点产品',
  `PRODUCT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'GEP产品名',
  `PRIMARY_CATEGORY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品一级分类',
  `SECONDARY_CATEGORY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品二级分类',
  `PLATFORM_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台名称',
  `SITE` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '站点',
  `SUPPORTED_INDUSTRY` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持行业',
  `ACCOUNT_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '账户类型: 1-全球收款账户 2-本地收款账户',
  `ACCOUNT_OPENING_SITE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户地（隐藏属性）',
  `CURRENCY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持入账币种',
  `INCOMING_REGION` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来款地区',
  `AUTH_SUPPORTED` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持授权',
  `ACCOUNT_EXPIRY_TERM` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号有效期',
  `OPENING_PROCESS_DURATION` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户时效',
  `CREDIT_PROCESSING_DURATION` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账时效',
  `SUPPORTED_GATEWAYS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持的收单网关',
  `DEFAULT_ACCOUNT_LIMIT` int(11) NULL DEFAULT NULL COMMENT '默认可申请账户数(已有地方配置)',
  `SINGLE_CREDIT_MIN` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单笔入账下限',
  `SINGLE_CREDIT_MAX` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单笔入账上限',
  `CREDIT_PROOF_REQUIREMENTS` tinyint(1) NULL DEFAULT NULL COMMENT '入账凭证要求（我司风控要求）',
  `CUSTOM_HOLDER_ALLOWED` tinyint(1) NULL DEFAULT 0 COMMENT '支持自定义账户持有人',
  `MICRO_VERIFICATION_ENABLED` tinyint(1) NULL DEFAULT 0 COMMENT '支持小额、账户验证',
  `EXTERNAL_REMARKS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '对外备注（对客展示）',
  `INTERNAL_REMARKS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '对内备注',
  `CUSTOMER_QUOTATION` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '客户报价',
  `AGENT_QUOTATION` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '代理商报价',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `DELETE_FLAG` tinyint(1) NULL DEFAULT NULL COMMENT '删除标记',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_PRODUCT_NO`(`PRODUCT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '产品信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_SETTLE_QUOTA_HISTORY
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_SETTLE_QUOTA_HISTORY`;
CREATE TABLE `T_GEP_SETTLE_QUOTA_HISTORY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `POOL_ID` bigint(20) NOT NULL COMMENT '额度池ID',
  `BIZ_ID` bigint(20) NOT NULL COMMENT '业务ID',
  `DIRECTION` tinyint(1) NOT NULL COMMENT '变动方向：1-增加，2-减少',
  `CHANGE_QUOTA` decimal(20, 2) NOT NULL COMMENT '变动额度',
  `QUOTA_BEFORE` decimal(20, 2) NOT NULL COMMENT '变动前额度',
  `QUOTA_AFTER` decimal(20, 2) NOT NULL COMMENT '变动后额度',
  `CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '币种',
  `TRADE_RATE_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇率ID',
  `REASON` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '变更原因或备注',
  `CREATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNQ_USER_POOL_ORDER_TYPE`(`USER_NO`, `POOL_ID`, `BIZ_ID`, `DIRECTION`) USING BTREE,
  INDEX `IDX_USER_POOL`(`USER_NO`, `POOL_ID`) USING BTREE,
  INDEX `IDX_USER_BIZ`(`USER_NO`, `BIZ_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 657 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'GEP结汇付款额度历史记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GEP_SETTLE_QUOTA_POOL
-- ----------------------------
DROP TABLE IF EXISTS `T_GEP_SETTLE_QUOTA_POOL`;
CREATE TABLE `T_GEP_SETTLE_QUOTA_POOL`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `TRADE_DATE` char(7) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '追加日期',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人名称',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人证件号码',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型:1-身份证 2-组织机构代码',
  `INDUSTRY_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '行业类型:01-货物贸易 06-物流 07-软件服务 08-广告 09-B2B货物贸易 10-职工报酬 11.赡家款 12-佣金 14-MCN',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种',
  `TOTAL_QUOTA` decimal(20, 2) NOT NULL COMMENT '总金额',
  `AVAILABLE_QUOTA` decimal(20, 2) NOT NULL COMMENT '可用额度',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `INDEX_ID`(`USER_NO`, `PAYEE_ID_NO`, `INDUSTRY_TYPE`, `PAYEE_NAME`, `TRADE_DATE`, `ORDER_CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 296 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP结汇付款额度池' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_GOODSTYPE_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_GOODSTYPE_INFO`;
CREATE TABLE `T_GOODSTYPE_INFO`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `TYPE_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '编码',
  `TYPE_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `PARENT_TYPE_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '父级编码',
  `TYPE_LEVEL` tinyint(4) NOT NULL COMMENT '等级',
  `TYPE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '状态 -1 无效 1有效',
  `REMARKS` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_CODE_NAME`(`TYPE_CODE`, `TYPE_NAME`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 171 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_HSCODE
-- ----------------------------
DROP TABLE IF EXISTS `T_HSCODE`;
CREATE TABLE `T_HSCODE`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `COMMODITY_NAME` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `COMMODITY_NAME_MD5` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `HSCODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'HSCODE',
  `STATUS` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Y' COMMENT 'Y-可用，N-不可用',
  `NEED_UPDATE_FLAG` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N' COMMENT 'Y-需要更新数据，N-无需更新数据',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `COMMODITY_NAME_MD5`(`COMMODITY_NAME_MD5`) USING BTREE,
  INDEX `IDX_COMMODITY_NAME`(`COMMODITY_NAME`(191)) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1978 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'HSCODE信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_IBC_SETTLE_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_IBC_SETTLE_DETAIL`;
CREATE TABLE `T_IBC_SETTLE_DETAIL`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT,
  `REPORT_ID` bigint(20) NULL DEFAULT NULL COMMENT '汇总流水号',
  `DETAIL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账明细唯一流水号',
  `INCOME_FROM` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账来源',
