  `AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '入账金额',
  `INCOME_AMT_COUNTS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账金额，多次入账用；隔开',
  `SUB_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '子账户号',
  `SUB_ACC_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '子账户名',
  `SETTLE_BANK_SWIFT` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结算银行swiftcode',
  `SETTLE_BANK_CODE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结算银行码',
  `SETTLE_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'GEP清算账号',
  `SETTLE_BANK_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结算银行名称',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'IBC结算订单明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_IBC_SETTLE_SUM
-- ----------------------------
DROP TABLE IF EXISTS `T_IBC_SETTLE_SUM`;
CREATE TABLE `T_IBC_SETTLE_SUM`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `REPORT_ID` bigint(20) NOT NULL COMMENT '汇总流水号',
  `COUNT` int(11) NOT NULL COMMENT '汇总总笔数',
  `TOTAL_AMT` decimal(19, 3) NOT NULL COMMENT '总金额',
  `CCY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` datetime NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'IBC结算订单汇总' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_INFORMATION
-- ----------------------------
DROP TABLE IF EXISTS `T_INFORMATION`;
CREATE TABLE `T_INFORMATION`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `THEME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '资讯主题 ',
  `CONTENT` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '资讯内容',
  `KEY_WORD` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关键词',
  `INFO_DESCRIBE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
  `SOURCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源',
  `AUTHOR` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '作者',
  `STATE` tinyint(2) NOT NULL COMMENT '状态：-1-删除 0-禁用 1-启用',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RECORD_ID` bigint(20) NOT NULL COMMENT '资讯编号',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '资讯信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_IP_LIST_LIMIT
-- ----------------------------
DROP TABLE IF EXISTS `T_IP_LIST_LIMIT`;
CREATE TABLE `T_IP_LIST_LIMIT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
