  `NAME_LIST_TYPE` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名单类型: blacklist-黑名单 whitelist-白名单 refusalList-拒绝名单',
  `STATUS` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'normal' COMMENT '状态: delete-已删除 normal-正常 disable-禁用',
  `REMARKS` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `REQ_URL` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求url',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_IP`(`IP`) USING BTREE,
  INDEX `IDX_NAME_LIST_TYPE`(`NAME_LIST_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'IP名单限制' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_IP_LIST_LIMIT_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_IP_LIST_LIMIT_RECORD`;
CREATE TABLE `T_IP_LIST_LIMIT_RECORD`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
