  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_IP`(`REQ_IP`) USING BTREE,
  INDEX `IDX_NAME_LIST_TYPE`(`BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1803 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'IP名单限制记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_JOB_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_JOB_CONFIG`;
CREATE TABLE `T_JOB_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `JOB_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '定时任务名称',
  `JOB_GROUP` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定时任务组',
  `JOB_CLASS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '定时任务调度类',
  `TRADE_DATE` date NULL DEFAULT NULL COMMENT '交易时间',
  `STATUS` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '状态：NONE:删除,NORMAL:正常,PAUSED:暂停,COMPLETE:运行中,ERROR:错误,BLOCKED:线程阻塞',
  `JOB_CRON_EXPRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定时任务正则表达式',
  `JOB_CRON_EXPRESS_DESC` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '表达式描述',
  `JOB_EXEC_COUNT` bigint(20) NOT NULL COMMENT '允许最大执行次数',
  `RETRY_TIMES` int(11) NOT NULL COMMENT '允许尝试次数',
  `JOB_DESC` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定时任务描述',
  `CREATED_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATED_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATED_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATED_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `LAST_EXEC_TIME` timestamp NULL DEFAULT NULL COMMENT '上次运行时间',
  `NEXT_EXEC_TIME` timestamp NULL DEFAULT NULL COMMENT '下次执行时间',
  `JOB_USED_TIME` int(11) NULL DEFAULT NULL COMMENT '耗时',
  `RESERVE` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段',
  `JOB_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '任务类型：1-业务任务，2-预警任务',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 550 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_JOB_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_JOB_LOG`;
CREATE TABLE `T_JOB_LOG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `JOB_ID` bigint(20) NOT NULL COMMENT 'Job任务的Id',
  `JOB_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务名称',
  `JOB_GROUP` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '任务组',
  `MACHINE_IP` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '机器IP地址',
  `EXEC_DATE` date NULL DEFAULT NULL COMMENT '执行日期',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '任务执行状态',
  `ERROR_MSG` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '任务异常描述',
  `START_TIME` timestamp NULL DEFAULT NULL COMMENT '任务开始执行时间',
  `EXEC_TIMES` int(11) NULL DEFAULT NULL COMMENT '任务执行次数',
  `CREATED_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATED_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATED_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATED_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2272327 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_JOB_PROCESS_ID_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_JOB_PROCESS_ID_RECORD`;
CREATE TABLE `T_JOB_PROCESS_ID_RECORD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `LAST_ID` bigint(20) NOT NULL COMMENT '最近一次处理的ID',
  `BIZ_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
