DROP TABLE IF EXISTS `T_MAINSTREAM_CCY_PROFIT`;
CREATE TABLE `T_MAINSTREAM_CCY_PROFIT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
