  `RECORD_DATE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录日期',
  `CCY_PAIR` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '货币对',
  `SELL_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖出货币',
  `BUY_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '买入货币',
  `SELL_AMT` decimal(20, 8) NOT NULL COMMENT '卖出金额',
  `BUY_AMT` decimal(20, 8) NOT NULL COMMENT '买入金额',
