  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 190 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '营销订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_MARKETING_QUOTA_CARD_ACTIVITIES
-- ----------------------------
DROP TABLE IF EXISTS `T_MARKETING_QUOTA_CARD_ACTIVITIES`;
CREATE TABLE `T_MARKETING_QUOTA_CARD_ACTIVITIES`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `ACTIVITY_NO` bigint(19) NOT NULL COMMENT '活动记录号',
  `ACTIVITY_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '活动名称',
  `ACTIVITY_START_TIME` timestamp NOT NULL COMMENT '活动开始时间',
  `ACTIVITY_END_TIME` timestamp NOT NULL COMMENT '活动结束时间',
  `ACTIVITY_AMT` decimal(19, 2) NOT NULL COMMENT '活动金额',
  `UNLIMITED_AMOUNT` tinyint(2) NOT NULL DEFAULT 0 COMMENT '无限额- 0-否，1-是，',
  `CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台',
  `EFFECTIVE_START_DATE` date NOT NULL COMMENT '有效开始日期',
  `EFFECTIVE_END_DATE` date NOT NULL COMMENT '有效结束日期',
  `NOTIFICATION_MODE` tinyint(2) NOT NULL COMMENT '通知方式- 1-短信，2-邮件，3-短信和邮件',
  `MESSAGE_CONTENT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '短信内容',
  `LABEL_NO` bigint(20) NULL DEFAULT NULL COMMENT '签名编号',
  `TITLE` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标题',
  `MAIL_CONTENT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '邮件内容',
  `USER_NO_STATE` tinyint(4) NULL DEFAULT NULL COMMENT '活动对象状态 \'\'-对象值，1-全部，2-新用户',
  `NOTIFICATION_STATE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '通知状态- 0-未通知，1-已通知，2-通知失败',
  `STATE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '活动状态- 0-未审核，1-正常，2-暂停，',
  `EXAMINE_STATE` tinyint(2) NOT NULL COMMENT '审核状态- 0-未审核，1-审核通过，2-审核未通过',
  `EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '额度卡活动表' ROW_FORMAT = Dynamic;

-- ----------------------------
