  INDEX `IDX_BIZ_ID`(`BIZ_ID`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17247 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商户通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_MERCHANT_CCY_QUOTA
-- ----------------------------
DROP TABLE IF EXISTS `T_MERCHANT_CCY_QUOTA`;
CREATE TABLE `T_MERCHANT_CCY_QUOTA`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `BUSINESS_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '业务类型',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易币种',
  `QUOTA_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '额度币种',
