  `USED_QUOTA` decimal(20, 2) NOT NULL COMMENT '已用额度',
  `REMAINING_QUOTA` decimal(20, 2) NOT NULL COMMENT '剩余额度',
  `VALID_DATE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '当前额度生效日期',
  `QUOTA_VALID_START` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '额度有效期开始',
  `QUOTA_VALID_END` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '额度有效期结束',
  `SUPPORT_HOLIDAY` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'NO' COMMENT '是否支持节假日 YES NO',
  `STATUS` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态OPEN/CLOSE',
  `VERSION` int(11) NOT NULL COMMENT '版本',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_user_no`(`USER_NO`, `BUSINESS_TYPE`, `CURRENCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商户结算额度管理表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_MERCHANT_CCY_QUOTA_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_MERCHANT_CCY_QUOTA_RECORD`;
CREATE TABLE `T_MERCHANT_CCY_QUOTA_RECORD`  (
