  `TRADE_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易类型',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易币种',
  `TRADE_AMOUNT` decimal(20, 2) NOT NULL COMMENT '交易金额',
