-- ----------------------------
-- Table structure for T_NOMAL_CCY_PROFIT_SPLIT
-- ----------------------------
DROP TABLE IF EXISTS `T_NOMAL_CCY_PROFIT_SPLIT`;
CREATE TABLE `T_NOMAL_CCY_PROFIT_SPLIT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `RECORD_MONTH` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录月份',
  `RECEIPT_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '凭证单号',
  `REQUEST_NO` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '原订单号',
  `TRADE_TYPE` tinyint(2) NOT NULL COMMENT '交易类型，1：付款，2：提现，3：货币兑换',
  `SOURCE_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '源币种',
  `TARGET_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
