  `BUY_AMOUNT` decimal(19, 2) NOT NULL COMMENT '买入金额',
  `SALES_PROFIT_AMT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '销售损益金额',
  `TRADES_PROFIT_AMT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '交易员损益金额',
  `PROFIT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '损益币种',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '1-正常，2-已删除',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_REQUEST_NO_TYPE`(`RECORD_MONTH`, `TRADE_TYPE`, `STATUS`) USING BTREE,
  INDEX `IDX_REQUEST_NO`(`REQUEST_NO`, `TRADE_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '指定币种损益拆分订单明细记录表' ROW_FORMAT = Dynamic;

