  `EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `EXAMINE_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审备注',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_BIZ_ID`(`BIZ_ID`) USING BTREE,
  INDEX `IDX_EXAMINE_AT`(`EXAMINE_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5594 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单审核表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_CHANNEL_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_CHANNEL_DETAIL`;
CREATE TABLE `T_ORDER_CHANNEL_DETAIL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ORDER_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单号',
  `BATCH_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `CHANNEL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付渠道ID',
  `TRANS_TYPE` tinyint(2) NOT NULL COMMENT '交易类型：1-入账，2-出款',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `AMOUNT` decimal(20, 2) NOT NULL COMMENT '金额',
  `TRANS_TIME` datetime NOT NULL COMMENT '交易时间',
  `TRANS_STATUS` tinyint(2) NOT NULL DEFAULT 2 COMMENT '交易状态：0-待处理，1-处理中，2-成功，3-失败',
  `EMAIL_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '邮件状态：0-初始，1-已通知渠道',
  `EMAIL_SENT_TIME` datetime NULL DEFAULT NULL COMMENT '发送邮件时间',
  `REMARK` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`ORDER_NO`) USING BTREE,
  INDEX `idx_transaction_status`(`TRANS_STATUS`) USING BTREE,
  INDEX `idx_email_status`(`EMAIL_STATUS`) USING BTREE,
  INDEX `idx_channel_id`(`CHANNEL_ID`) USING BTREE,
  INDEX `idx_business_type`(`TRANS_TYPE`) USING BTREE,
  INDEX `idx_created_at`(`CREATED_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '交易订单渠道明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_CHANNEL_NOTIF
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_CHANNEL_NOTIF`;
CREATE TABLE `T_ORDER_CHANNEL_NOTIF`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `BATCH_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `CHANNEL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付渠道ID',
  `EMAIL_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '邮件状态：0-初始，1-已通知渠道',
  `EMAIL_RECIPIENTS` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮件收件人列表',
  `EMAIL_CONTENT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '邮件内容',
  `EMAIL_SENT_TIME` datetime NULL DEFAULT NULL COMMENT '发送邮件时间',
  `REMARK` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uk_batch_no`(`BATCH_NO`) USING BTREE,
  INDEX `idx_email_status`(`EMAIL_STATUS`) USING BTREE,
  INDEX `idx_channel_id`(`CHANNEL_ID`) USING BTREE,
  INDEX `idx_created_at`(`CREATED_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '交易订单渠道邮件通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_ENTERPRISE
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_ENTERPRISE`;
CREATE TABLE `T_ORDER_ENTERPRISE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单编号',
  `ENTERPRISE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '企业名称',
  `ENTERPRISE_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '企业编号，统一社会信用代码',
  `LEGAL_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '企业法人名称',
  `LEGAL_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '企业法人证件号码',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4574 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '结汇订单企业信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_LOGISTICS_DETAILS
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_LOGISTICS_DETAILS`;
CREATE TABLE `T_ORDER_LOGISTICS_DETAILS`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '内部ID编号',
  `LOGISTICS_NUMBER` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '物流单号',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-暂无物流信息，2-运输中，3-签收成功',
  `STATUS_DESC` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '状态描述',
  `FORM_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '起始地址',
  `TO_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标地址',
  `FORM_DATE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物流最初时间',
  `TO_DATE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物流签收时间',
  `LOGISTICS_DESC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
  `DATA_SOURCE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据来源',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `LOGISTICS_NUMBER`(`LOGISTICS_NUMBER`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 207101 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for T_ORDER_OBTAIN
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_OBTAIN`;
CREATE TABLE `T_ORDER_OBTAIN`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `OBTAIN_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户id',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺id',
  `NEXT_TOKEN` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '下一页页码',
  `STATUS` tinyint(2) NOT NULL COMMENT '执行状态：0-未执行，1-执行中，2-执行成功，3-执行失败,4-命令执行结束',
  `QUERY_DATE` timestamp NOT NULL COMMENT '获取最後时间',
  `NEXT_DATE` timestamp NOT NULL COMMENT '下次執行时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `BIZ_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务类型，ORDER-亚马逊主订单，ORDER_ITEM-亚马逊商品信息',
  `STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺所在平台',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4488 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_PAYMENT_TRADE_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_PAYMENT_TRADE_RECORD`;
CREATE TABLE `T_ORDER_PAYMENT_TRADE_RECORD`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `pay_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '支付流水号',
  `order_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '订单id',
  `pay_amt` decimal(20, 2) NULL DEFAULT NULL COMMENT '支付金额',
  `pay_state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '状态',
  `acc_bal_pay_amt` decimal(20, 2) NULL DEFAULT NULL COMMENT '账户余额支付金额',
  `transfer_pay_amt` decimal(20, 2) NULL DEFAULT NULL COMMENT '线下转账金额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `audit_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '复核人',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '复核时间',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '复核备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_PRIORITIZE_CHANGE
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_PRIORITIZE_CHANGE`;
CREATE TABLE `T_ORDER_PRIORITIZE_CHANGE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID主键编号',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ORDER_NO` bigint(19) NOT NULL COMMENT '订单编号',
  `BIZ_TYPE` int(2) NOT NULL COMMENT '业务类型：1-B2B账户开通 2-B2B收款材料 3-B2B入账，4-B2B付款，5-B2B收款人',
  `WORKSHEET_TYPE` int(2) NOT NULL COMMENT '工单类型：1-KA 2-加急 3-普通',
  `STATUS` int(2) NOT NULL COMMENT '状态：0-删除，1-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_ORDER_NO`(`ORDER_NO`) USING BTREE,
  INDEX `idx_worksheet_type`(`WORKSHEET_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 102 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单优先处理变动表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_ORDER_STUDY_ABROAD
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_STUDY_ABROAD`;
CREATE TABLE `T_ORDER_STUDY_ABROAD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `DETAILS_ID` bigint(20) NULL DEFAULT NULL COMMENT 'Gep入账订单号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '宝付订单号',
  `MEMBER_ID` bigint(19) NULL DEFAULT NULL COMMENT '宝付商户号',
  `MEMBER_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '宝付商户名',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单金额,默认为人民币',
  `ORDER_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '订单金额对应宝付的实际跨境金额',
  `SCHOOL_COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '学校所在国家',
  `SCHOOL_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '学校名称',
  `STUDENT_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '学生姓名',
  `STUDENT_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '学生学号',
  `SCHOOL_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '学校地址',
  `STUDENT_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '证件类型：1-身份证，3-护照',
  `STUDENT_ID_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '证件号码，加密存储',
  `ID_EXPIRATION_START` date NULL DEFAULT NULL COMMENT '证件签发日期',
  `ID_EXPIRATION_END` date NULL DEFAULT NULL COMMENT '证件有效截止日期',
  `STUDENT_NAME_EN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生英文名',
  `STUDENT_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生地址',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `FIRST_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生英文名的firstName',
  `LAST_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生英文名的lastName',
  `PROVINCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生所在省/州',
  `CITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生所在城市',
  `PHONE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生手机号',
  `ZONE_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生手机号区号',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '跨境订单留学信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for T_ORDER_TAGS
-- ----------------------------
DROP TABLE IF EXISTS `T_ORDER_TAGS`;
CREATE TABLE `T_ORDER_TAGS`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单号',
  `TAGS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易标签',
  `TRADE_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '交易类型：1-入账，2-出款，3-划拨，4-转账',
  `TRADE_SUBTYPE` tinyint(3) NULL DEFAULT NULL COMMENT '交易子类型',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态: -1-删除 1-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_STATUS`(`ORDER_ID`, `STATUS`) USING BTREE COMMENT '订单号+状态普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 10847 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单标签' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYEE_CHANNEL_USED_AMOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYEE_CHANNEL_USED_AMOUNT`;
CREATE TABLE `T_PAYEE_CHANNEL_USED_AMOUNT`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道编号',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_USED_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '收款人已用金额',
  `PAYEE_AMOUNT_HANDLING` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '收款人处理中金额',
  `YEAR` int(4) NULL DEFAULT NULL COMMENT '统计年份:YYMM',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX1_PAYEE_ID_NO`(`PAYEE_ID_NO`, `CHANNEL_ID`, `YEAR`) USING BTREE COMMENT '收款人渠道按年普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '结汇收款人按年统计渠道已用金额表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYEE_REFUND_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYEE_REFUND_ORDER`;
CREATE TABLE `T_PAYEE_REFUND_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户号',
  `REFUND_ORDER_ID` bigint(19) NOT NULL COMMENT '退款订单号',
  `REFUND_TYPE` int(11) NOT NULL COMMENT '退款类型：同入账PAYEE_TYPE',
  `REFUND_MODEL` tinyint(3) NULL DEFAULT NULL COMMENT '退款模式：1-原路退回(普通退款)，2-付款退回(极速退款)',
  `ORIGINAL_ORDER_ID` bigint(19) NOT NULL COMMENT '原订单号',
  `ORIGINAL_ORDER_AMT` decimal(18, 2) NOT NULL COMMENT '原订单金额',
  `ORIGINAL_ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '原订单币种',
  `ORIGINAL_CHANNEL_BANK_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原渠道流水号',
  `REFUND_AMT` decimal(18, 2) NOT NULL COMMENT '退款金额',
  `REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退款币种',
  `REFUND_FEE` decimal(18, 2) NULL DEFAULT NULL COMMENT '退款手续费',
  `REFUND_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款手续费币种',
  `RE_REFUND_FEE` decimal(18, 2) NULL DEFAULT NULL COMMENT '实际收取用户退款手续费',
  `FEE_STATUS` tinyint(2) NULL DEFAULT 0 COMMENT '手续费扣款及退回状态 0#未扣 1#全额扣款  3#全额退回',
  `FEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费扣款类型：1-内扣，2-外扣',
  `STATE` int(11) NOT NULL COMMENT '0#初始化待退款 1#退款中 2#退款成功 3#退款失败 4#用户确认中 6#线下退款中 7#退款待复核 8#无需退款 9#待扣手续费 10#待初审  11#待风控审核 12#退款被退回',
  `AUDIT_STATE` int(11) NOT NULL COMMENT '审核状态: 0#初始待审核 1#清算初审完成；2#清算复审完成；3#清算审核失败；4#风控审核失败',
  `CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退款渠道',
  `ORIGINAL_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '原渠道编号',
  `CHANNEL_ACCT_NO` varchar(80) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道账号',
  `CHANNEL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道币种',
  `CHANNEL_REFUND_STATE` tinyint(3) NULL DEFAULT NULL COMMENT '渠道退款状态：1-初始，2-退款中，3-成功，4-失败，5-异常',
  `REFUND_COST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款成本币种',
  `REFUND_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '退款成本',
  `REFUND_REASON` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款原因',
  `PAYMENT_FEE_REFUND_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '付款手续费退回金额',
  `PAYMENT_FEE_REFUND_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款手续费退回金额币种',
  `REFUND_BANK_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道流水号',
  `RISK_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核人',
  `RISK_AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '风控审核时间',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核对客备注',
  `AUDIT_INIT_AT` timestamp NULL DEFAULT NULL COMMENT '清算初审时间',
  `AUDIT_INIT_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算初审人',
  `AUDIT_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '清算终审时间',
  `AUDIT_FINAL_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算终审人',
  `REFUND_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '退款完成时间',
  `REFUND_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款时间',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `REMARK1` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '一审核备注',
  `TOW_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '二审备注',
  `MERCHANT_REFUND_AMT` decimal(18, 2) NULL DEFAULT NULL COMMENT '实际商户退款金额',
  `MERCHANT_REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户退款币种',
  `CHANNEL_REFUND_AMT` decimal(18, 2) NULL DEFAULT NULL COMMENT '渠道退款金额',
  `CHANNEL_REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款币种',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `PAYEE_BLOCK_FLAG` tinyint(3) NULL DEFAULT NULL COMMENT '入账是是否被屏蔽：1-被屏蔽，0-未被屏蔽',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_REFUND_ID`(`REFUND_ORDER_ID`) USING BTREE,
  INDEX `IDX_ORI_ORDER_ID`(`ORIGINAL_ORDER_ID`) USING BTREE,
  INDEX `IDX_REFUND_FINAL_AT`(`REFUND_FINAL_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1662 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '入账退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYEE_REFUND_RETURN_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYEE_REFUND_RETURN_ORDER`;
CREATE TABLE `T_PAYEE_REFUND_RETURN_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户号',
  `REFUND_ORDER_ID` bigint(19) NOT NULL COMMENT '退款订单号',
  `REFUND_CHANNEL_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道流水号',
  `REFUND_CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退款渠道',
  `REFUND_AMT` decimal(18, 2) NOT NULL COMMENT '退款金额',
  `REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退款币种',
  `RETURN_ORDER_ID` bigint(19) NOT NULL COMMENT '退回订单号',
  `RETURN_CHANNEL_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退回渠道流水号',
  `RETURN_CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退回渠道',
  `RETURN_AMT` decimal(18, 2) NOT NULL COMMENT '退回金额',
  `RETURN_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退回币种',
  `RETURN_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '退回成本',
  `RETURN_COST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退回成本币种',
  `RETURN_PAY_FEE_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '出款费用成本退回',
  `RETURN_PAY_FEE_COST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '出款费用成本退回币种',
  `RETURN_REASON` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退回原因',
  `RETURN_REMARK` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退回备注',
  `RETURN_AT` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退回时间',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `PAYEE_DETAIL_ID` bigint(20) NULL DEFAULT NULL COMMENT '入账流水号',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `RETURN_ORI_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '退回原订单类型1正常入账 2异常入账',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RETURN_ORDER_ID`(`RETURN_ORDER_ID`) USING BTREE,
  INDEX `IDX_REFUND_ORDER_ID`(`REFUND_ORDER_ID`) USING BTREE,
  INDEX `IDX_RETURN_AT`(`RETURN_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '入账退款退回表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYER_ACCOUNT_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYER_ACCOUNT_INFO`;
CREATE TABLE `T_PAYER_ACCOUNT_INFO`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `BANK_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `ACCOUNT_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户名称',
  `ACCOUNT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户号-账务系统',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `ACC_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '1：付款人账户信息 2：收款人账户信息',
  `SWIFT_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'SWIFT CODE',
  `ADDRESS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行地址',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  INDEX `IDX_CHANNEL_ID`(`CHANNEL_ID`, `CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '付款账户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYMENT_BALANCE_INSUFFICIENT_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYMENT_BALANCE_INSUFFICIENT_RECORD`;
CREATE TABLE `T_PAYMENT_BALANCE_INSUFFICIENT_RECORD`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `BIZ_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '业务类型：1-B2B结汇垫资，2-GEP结汇垫资,3-电商平台提现垫资,4-电商平台CNH垫资提现',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '路由渠道编号',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE COMMENT '创建时间普通索引',
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE COMMENT '用户号普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 108 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '交易订单余额不足记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYMENT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYMENT_DETAIL`;
CREATE TABLE `T_PAYMENT_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAIL_ID` bigint(20) NOT NULL COMMENT '明细编号',
  `USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '用户号',
  `ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '账户编号',
  `WALLET_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道方虚拟账户',
  `BANK_RESP_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道返回流水号',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `BUSINESS_TYPE` tinyint(2) NOT NULL COMMENT '业务类型：1-海外收款',
  `BALANCE_DIRECTION` tinyint(2) NULL DEFAULT NULL COMMENT '余额方向:1-收入；2-支出',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `MARKETPLACE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '‘亚马逊站点编号’',
  `STATE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态；0-删除 1-正常',
  `CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道编号',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户编号',
  `FEE` decimal(19, 3) NULL DEFAULT 0.000 COMMENT '商户入账手续费',
  `SETTLE_STATUS` tinyint(2) NULL DEFAULT 0 COMMENT '结算状态，0：待结算 1：已结算',
  `SETTLE_BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '结算批次号',
  `REMIT_REMARKS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款附言',
  `INCOME_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '是否可以入账 0：待入账 1：入账成功 2：入账失败',
  `INCOME_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账备注 入账失败原因',
  `INCOME_AUDIT_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '入账风控审核状态 0：待审核 1：审核成功 2：审核失败 ',
  `INCOME_AUDIT_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账风控审核备注',
  `INCOME_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `INCOME_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_DETAIL_ID`(`DETAIL_ID`) USING BTREE,
  INDEX `IDX_MEMB_RESP_ID`(`BANK_RESP_ID`, `USER_NO`) USING BTREE,
  INDEX `IDX_MEM_CREATE`(`CREATE_AT`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5338 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '收款账户收支明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYMENT_ORDER_API
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYMENT_ORDER_API`;
CREATE TABLE `T_PAYMENT_ORDER_API`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `MEMBER_ID` bigint(19) NULL DEFAULT NULL COMMENT '商户号',
  `TERMINAL_ID` bigint(19) NULL DEFAULT NULL,
  `ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '订单号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户请求单号',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款到账币种',
  `PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '收款到账金额',
  `PAYMENT_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款手续费币种',
  `CARD_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `ACCOUNT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账户名称',
  `PAYMENT_PURPOSE` tinyint(2) NOT NULL COMMENT '付款用途：1-往来结算款、2-货款、3-差旅费、4-生活费、5-投资款项、6-办公费用、7-工程款、8-劳务费/薪酬、9-学费、10-其他',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `PAYMENT_MATERIAL` bigint(19) NULL DEFAULT NULL COMMENT '付款材料文件ID，付款类型为2时必传',
  `FIXED_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '固定模式：1-固定付款金额，2-固定收款金额',
  `CALL_BACK_URL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '异步通知地址',
  `REQUSET_IP` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '请求ip地址',
  `CERTIFICATE_ID` bigint(19) NOT NULL COMMENT '证书编号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户API付款订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAYOUT_CHANNEL_DISABLE_STRATEGY
-- ----------------------------
DROP TABLE IF EXISTS `T_PAYOUT_CHANNEL_DISABLE_STRATEGY`;
CREATE TABLE `T_PAYOUT_CHANNEL_DISABLE_STRATEGY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RULE_ID` bigint(19) NOT NULL COMMENT '规则ID',
  `RULE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则名称',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '禁用渠道',
  `CHANNEL_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '禁用渠道名称',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态0禁用，1启用',
  `STRATEGY_ENGINE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '实现规则',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `RULE_ID_UN_IDX`(`RULE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '出款渠道禁用规则配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PAY_STANDING_MONITOR_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_PAY_STANDING_MONITOR_APPLY`;
CREATE TABLE `T_PAY_STANDING_MONITOR_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `STANDING_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '挂单单号',
  `ORDER_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CCY_PAIR` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '货币对',
  `TRADE_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易类型',
  `BUSINESS_TYPE` tinyint(4) NOT NULL COMMENT '业务类型',
  `TRADE_DIRECTION` tinyint(4) NULL DEFAULT NULL COMMENT '交易方向 1买入 2卖出',
  `SELL_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '卖出币种',
  `BUY_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '买入币种',
  `STANDING_RATE` decimal(18, 8) NOT NULL COMMENT '挂单汇率',
  `DEAL_RATE` decimal(18, 8) NULL DEFAULT NULL COMMENT '成交汇率',
  `RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成交汇率ID',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态PROCESS、FAIL、SUCC',
  `NOTICE_MARK` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'N' COMMENT 'Y-已通知 N-未通知',
  `REASON` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '原因',
  `COMPLETE_DATE` datetime NULL DEFAULT NULL COMMENT '成交时间',
  `REMARK` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '备注',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `UDX_ORDER_NO`(`ORDER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 149 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '交易挂单订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PLATFORM_BASE_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_PLATFORM_BASE_INFO`;
CREATE TABLE `T_PLATFORM_BASE_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台编码',
  `PLATFORM_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台名称',
  `PLATFORM_EN_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台英文名称',
  `PLATFORM_CODE` int(11) NOT NULL COMMENT '平台code',
  `SUB_PLATFORM_DISPLAY` tinyint(3) NOT NULL COMMENT '子平台在前端展示内容：1，站点（sub_platform）2,国家或地区（country）3，币种（ccy）4，不展示',
  `PLATFORM_TYPE` tinyint(3) NOT NULL COMMENT '平台类型:1.电商平台，2.独立站 3.其他',
  `APPLY_ACC_LOGO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申请收款页面logo',
  `BIND_RESULT_LOGO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '绑定结果页面logo',
  `STATUS` tinyint(3) NULL DEFAULT 1 COMMENT '状态：0.下线 1.上线 2.白名单灰度',
  `WHITELIST_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '白名单灰度KEY,命名规则 PLATFORM+\"_WHITELIST\"',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_PLATFORM`(`PLATFORM`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '平台基本信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PLATFORM_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_PLATFORM_CONFIG`;
CREATE TABLE `T_PLATFORM_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
