  `PLATFORM_HOT` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'N' COMMENT '热门平台 Y-是 N-否',
  `PRIORITY_LEVEL` int(11) NULL DEFAULT NULL COMMENT '优先级 1-11',
  `PLATFORM_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台类型 跨境 CROSS 本土 LOCAL 半托管 HALF-MANAGE',
