  `MEMBER_GROUP` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户分组,多个支持逗号隔开',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'POBO付款方式必填项配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_POSITION_EXPOSURE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_POSITION_EXPOSURE_CONFIG`;
CREATE TABLE `T_POSITION_EXPOSURE_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `CURRENCY_PAIR` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '货币对',
  `POSITION_EXPOSURE` decimal(20, 4) NULL DEFAULT 0.0000 COMMENT '持仓敞口',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `IS_DELETE` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'N' COMMENT '逻辑删除标识：N=正常, Y=已删除',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CCY`(`CURRENCY_PAIR`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '持仓敞口配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_PRIZE_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_PRIZE_RECORD`;
CREATE TABLE `T_PRIZE_RECORD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `PRIZE_NO` bigint(20) NOT NULL COMMENT '中奖人编号',
  `USER_PHONE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户手机号码',
  `USER_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户姓名',
  `EXHIBITION_ID` bigint(11) NOT NULL COMMENT '展会编号',
  `PRIZE_LEVEL` int(4) NOT NULL COMMENT '奖品级别,0代表特等奖，9999代表未中奖',
  `PRIZE_LEVEL_DESC` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '奖品级别描述',
  `PRIZE_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '奖品名称',
  `PRIZE_STATE` tinyint(2) NOT NULL COMMENT '奖品状态：0-未领奖，1-未中奖，2-已领奖',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `ID`(`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 77 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '奖品中奖记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_QBC_REPORT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_QBC_REPORT_DETAIL`;
CREATE TABLE `T_QBC_REPORT_DETAIL`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `REPORT_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇总流水号',
  `DETAIL_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账明细唯一流水号',
  `BUSINESS_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务订单号，后续扩展使用',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BRANCH_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分行代码',
  `BANK_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行四位码',
  `ACCOUNT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号名',
  `BILL_TIME` timestamp NOT NULL COMMENT '入账时间',
  `TIME_ZONE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账国家时区',
  `AMT` decimal(19, 3) NOT NULL COMMENT '入账金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '入账币种',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 210 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'QBC日报明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_QBC_REPORT_SUM
-- ----------------------------
DROP TABLE IF EXISTS `T_QBC_REPORT_SUM`;
CREATE TABLE `T_QBC_REPORT_SUM`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `REPORT_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇总流水号',
  `BEGIN_TIME` timestamp NOT NULL COMMENT '汇总开始时间',
  `END_TIME` timestamp NOT NULL COMMENT '汇总结束时间',
  `COUNT` int(11) NOT NULL COMMENT '汇总记录数',
  `TOTAL_AMT` decimal(19, 3) NOT NULL COMMENT '汇总金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '汇总币种',
  `BALANCE` decimal(19, 3) NOT NULL COMMENT '大账户余额',
  `REPORT_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '对账状态：0-待对账 1-对账成功 2-对账失败 3-已打款',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 116 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'QBC日报汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RATE_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_RATE_RECORD`;
CREATE TABLE `T_RATE_RECORD`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RATE_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '汇率日志ID',
  `MEMBER_ID` bigint(19) NOT NULL COMMENT '商户编号',
  `CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '币种，需要换算的币种',
  `EXCHANGE_RATE` decimal(19, 6) NOT NULL COMMENT '购汇汇率',
  `SETTLE_RATE` decimal(19, 6) NOT NULL COMMENT '结汇汇率',
  `EXCHANGE_BP` int(10) NOT NULL COMMENT '购汇汇率BP',
  `SETTLE_BP` int(10) NOT NULL COMMENT '结汇汇率BP',
  `ORIGINAL_EXCHANGE_RATE` decimal(19, 6) NOT NULL COMMENT '原始购汇汇率',
  `ORIGINAL_SETTLE_RATE` decimal(19, 6) NOT NULL COMMENT '原始结汇汇率',
  `QUERY_DATE` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '查询汇率时间',
  `RATE_EXPIRE_DATE` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT '汇率过期时间',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RATE_ID`(`RATE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '汇率记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_READY_CLOSE_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_READY_CLOSE_ACCOUNT`;
CREATE TABLE `T_READY_CLOSE_ACCOUNT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '账户编号，内部唯一编号',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户编号，提供给商户使用的银行账户',
  `BANK_ACCOUNT_CCY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `BANK_ACCOUNT_TYPE` tinyint(3) NOT NULL COMMENT '银行帐号类型：0-电商，1-平台收款，2-外部其他收款 3-b2b收款',
  `CLOSING_STATUS` tinyint(2) NOT NULL COMMENT '账户状态：0-待销户，1-注销种 2-已经注销',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `READY_CLOSE_AT` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预期销户时间',
  `CLOSE_AT` timestamp NULL DEFAULT NULL COMMENT '销户时间',
  `TRADE_DATE` timestamp NULL DEFAULT NULL COMMENT '最后交易时间',
  `STOCK_DATA` tinyint(2) NOT NULL DEFAULT 0 COMMENT '0-不是存量数据，1：是存量数据',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '记录状态:1-生效中，2-已失效',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_user_no`(`USER_NO`, `BANK_ACC_NO`, `BANK_ACCOUNT_CCY`) USING BTREE,
  INDEX `IDX_ACCOUNT_NO`(`ACCOUNT_NO`) USING BTREE COMMENT '内部账户号索引',
  INDEX `IDX_READY_CLOSE_AT`(`READY_CLOSE_AT`) USING BTREE COMMENT '预期销户时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 105537 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '待销户账户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER`;
CREATE TABLE `T_RECALL_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `CHECK_ORDER_NO` bigint(20) NOT NULL COMMENT '召回订单号（调单转召回 同调单订单号一致）',
  `FILE_BATCH_NO` bigint(20) NULL DEFAULT NULL COMMENT '文件批次号',
  `PAYEE_DETAIL_ID` bigint(20) NOT NULL COMMENT '入账明细流水号',
  `PAYEE_CHANNEL_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入账渠道流水号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORI_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始用户入账订单金额',
  `CHECK_ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '调单金额(召回金额)',
  `CHECK_ORDER_CCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '调单金额币种',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道id',
  `CHECK_DATE` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调单日期',
  `CHECK_TYPE` tinyint(2) NOT NULL COMMENT '召回类型 1#普通调单 2#风险召回 3#入账退款手续费收取',
  `ORDER_BIZ_TYPE` tinyint(2) NOT NULL COMMENT '订单业务类型1#电商 2#GEP 3#B2B 4#服贸',
  `FROZEN_FLAG` tinyint(2) NOT NULL COMMENT '冻结标志 1#是',
  `BAL_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总的余额冻结金额',
  `RESERVE_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总的预约冻结金额（锁表更新）',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '1#待确认 2#解除风险 3#确认召回',
  `CONFIRM_CHECK_DATE` timestamp NULL DEFAULT NULL COMMENT '确认召回时间 确认召回时回填',
  `FROZEN_STATUS` tinyint(2) NULL DEFAULT 0 COMMENT '冻结解冻及扣款状态 0#未冻结 1#全额冻结 2#部分冻结 3#全额扣款 4#部分扣款 5#全额解冻 6#部分解冻',
  `UN_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已解冻金额',
  `CONFIRM_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已确认金额',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '确认时间',
  `AUDIT_REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认备注',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_NO`(`CHECK_ORDER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1056 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '召回订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER_ACCOUNT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER_ACCOUNT_DETAIL`;
CREATE TABLE `T_RECALL_ORDER_ACCOUNT_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `ACCOUNT_NO` bigint(20) NOT NULL COMMENT '账户号',
  `ORDER_TYPE` int(2) NOT NULL COMMENT '订单类型：1-冻结 2-解冻',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种',
  `ACCOUNT_BAL` decimal(19, 3) NOT NULL COMMENT '账户余额',
  `ACCOUNT_END_BAL` decimal(19, 3) NOT NULL COMMENT '交易后余额',
  `BAL_DIRECTION` int(2) NULL DEFAULT NULL COMMENT '余额方向:1-收入；2-支出',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ACCOUNT_NATURE` tinyint(2) NULL DEFAULT NULL COMMENT '账务账户类型 5#电商 7#B2B',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ACCOUNT_TYPE`(`ORDER_ID`, `ACCOUNT_NO`, `ORDER_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`, `CREATE_AT`) USING BTREE,
  INDEX `IDX_ACCOUNT_NO`(`ACCOUNT_NO`, `CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1624 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '业务子账户余额操作明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER_BATCH
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER_BATCH`;
CREATE TABLE `T_RECALL_ORDER_BATCH`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `FILE_BATCH_NO` bigint(20) NOT NULL COMMENT '文件批次号',
  `FILE_COUNT` int(11) NULL DEFAULT NULL COMMENT '文件笔数',
  `CHECK_DATE` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '调单日期',
  `FILE_DFS_ID` bigint(19) NOT NULL COMMENT '上传文件id',
  `FILE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名称',
  `FILE_BIZ_TYPE` tinyint(2) NOT NULL COMMENT '文件业务类型 1-调单 2-召回',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '审核状态 1-待审核，2-审核成功，3-审核失败',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `HANDLE_FAIL_FILE_ID` bigint(19) NULL DEFAULT NULL COMMENT '处理失败文件id',
  `HANDLE_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '处理状态 1-待处理，2-处理成功，3-处理失败',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '召回订单批次表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER_BATCH_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER_BATCH_DETAIL`;
CREATE TABLE `T_RECALL_ORDER_BATCH_DETAIL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `CHECK_ORDER_NO` bigint(20) NOT NULL COMMENT '调单订单号',
  `FILE_BATCH_NO` bigint(20) NOT NULL COMMENT '文件批次号',
  `PAYEE_DETAIL_ID` bigint(20) NOT NULL COMMENT '入账明细流水号',
  `PAYEE_CHANNEL_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入账渠道流水号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CHECK_ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '调单金额',
  `CHECK_ORDER_CCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '调单金额对应币种',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '入账渠道',
  `ORDER_BIZ_TYPE` tinyint(2) NOT NULL COMMENT '订单业务类型：1-电商 2-GEP 3-B2B 4-服贸',
  `CHECK_REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调单备注',
  `CHECK_FILE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '调单处理状态 1-解析成功 2-解析失败',
  `CHECK_FILE_REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调单处理备注',
  `CHECK_DATE` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调单日期',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `FROZEN_FLAG` tinyint(4) NULL DEFAULT NULL COMMENT '冻结标识 1-是，2-否',
  `CHECK_TYPE` tinyint(4) NULL DEFAULT NULL COMMENT '调单类型  1-普通调单 2-风险调单',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1202 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '召回订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER_FROZEN_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER_FROZEN_DETAIL`;
CREATE TABLE `T_RECALL_ORDER_FROZEN_DETAIL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `FZ_DETAIL_ID` bigint(20) NOT NULL COMMENT '冻结明细id',
  `CHECK_ORDER_NO` bigint(20) NOT NULL COMMENT '调单（召回）订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORDER_BIZ_TYPE` tinyint(2) NOT NULL COMMENT '订单业务类型1#电商 2#GEP 3#B2B 4#服贸',
  `FROZEN_TYPE` tinyint(2) NOT NULL COMMENT '1#余额冻结 2#预约冻结 3#欠费扣款 4#解冻',
  `FROZEN_AMT` decimal(19, 2) NOT NULL COMMENT '冻结金额',
  `FROZEN_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '冻结币种',
  `TRADE_RATE` decimal(19, 6) NOT NULL COMMENT '汇率',
  `DEST_AMT` decimal(19, 2) NOT NULL COMMENT '换算金额',
  `DEST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '换算币种',
  `STATUS` tinyint(2) NOT NULL COMMENT '冻结解冻及扣款状态状态 1#已冻结 2#已扣款 3#已解冻',
  `DETAIL_FLAG` tinyint(2) NOT NULL COMMENT '明细方向1#正向 2#反向',
  `CCY_GROUP` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实际货币对 如USD/EUR',
  `TRADE_DIRECTION` tinyint(2) NULL DEFAULT NULL COMMENT '实际交易方向（对客），以货币对为基准的交易方向',
  `VOUCHER_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '凭证申请状态 1#申请或撤销凭证根据明细方向来 2#申请或撤销凭证操作失败 0未申请 3#确认推进凭证',
  `BACS_NO` bigint(20) NULL DEFAULT NULL COMMENT '账务解冻或确认的记账流水号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ACCOUNT_NATURE` tinyint(2) NULL DEFAULT NULL COMMENT '账务账户类型 1#GEP 5#电商 7#B2B',
  `CHECK_TYPE` tinyint(2) NOT NULL COMMENT '召回类型 1#普通调单 2#风险召回 3#入账退款手续费收取',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_DETAIL_ID`(`FZ_DETAIL_ID`, `DETAIL_FLAG`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2026 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '调单（召回）订单冻结解冻扣款明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RECALL_ORDER_TEMP
-- ----------------------------
DROP TABLE IF EXISTS `T_RECALL_ORDER_TEMP`;
CREATE TABLE `T_RECALL_ORDER_TEMP`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `CHECK_ORDER_NO` bigint(20) NOT NULL COMMENT '召回订单号（调单转召回 同调单订单号一致）',
  `FILE_BATCH_NO` bigint(20) NULL DEFAULT NULL COMMENT '文件批次号',
  `PAYEE_DETAIL_ID` bigint(20) NOT NULL COMMENT '入账明细流水号',
  `PAYEE_CHANNEL_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入账渠道流水号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORI_ORDER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始用户入账订单金额',
  `CHECK_ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '调单金额(召回金额)',
  `CHECK_ORDER_CCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '调单金额币种',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道id',
  `CHECK_DATE` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调单日期',
  `CHECK_TYPE` tinyint(2) NOT NULL COMMENT '召回类型 2#风险召回',
  `ORDER_BIZ_TYPE` tinyint(2) NOT NULL COMMENT '订单业务类型1#电商 2#GEP 3#B2B 4#服贸',
  `FROZEN_FLAG` tinyint(2) NOT NULL COMMENT '冻结标志 1#是',
  `BAL_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总的余额冻结金额',
  `RESERVE_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总的预约冻结金额（锁表更新）',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '1#待确认 2#解除风险 3#确认召回',
  `CONFIRM_CHECK_DATE` timestamp NULL DEFAULT NULL COMMENT '确认召回时间 确认召回时回填',
  `FROZEN_STATUS` tinyint(2) NULL DEFAULT 0 COMMENT '冻结解冻及扣款状态 0#未冻结 1#全额冻结 2#部分冻结 3#全额扣款 4#部分扣款 5#全额解冻 6#部分解冻',
  `UN_FROZEN_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已解冻金额',
  `CONFIRM_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已确认金额',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '确认时间',
  `AUDIT_REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认备注',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_NO`(`CHECK_ORDER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1036 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '召回订单表' ROW_FORMAT = Dynamic;

