-- ----------------------------
-- Table structure for T_REDEEM_INCOME_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_REDEEM_INCOME_ORDER`;
CREATE TABLE `T_REDEEM_INCOME_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAILS_ID` bigint(19) NOT NULL COMMENT '收款明细编号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户编号',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '收款渠道编号',
  `PAYEE_AMOUNT` decimal(19, 3) NOT NULL COMMENT '收款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款币种',
  `PAYEE_ACCOUNT_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款银行帐号',
  `PAYEE_ACCOUNT_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款银行账户名称',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `PAYEE_DATE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款时间',
  `PAYER_ACCOUNT_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人帐号',
  `PAYER_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人名称',
  `PAYER_SWIFT_CODE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人SWIFT_CODE',
  `PAYER_COUNTRY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人国家',
  `PAYER_BANK_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款银行名称',
  `REMIT_PAYER_ADDRESS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人地址',
  `REMIT_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '付款金额',
  `REMIT_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款币种',
  `BANK_PAYEE_FEE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行入账费用币种',
  `BANK_PAYEE_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行入账费用金额',
  `BANK_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行流水号',
  `REFERENCE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易附言',
  `PAYEE_INCOME_STATUS` tinyint(2) NOT NULL DEFAULT 2 COMMENT '渠道入账状态：0-待确认 1-未入账，2-已入账,3-入账中，4-入账失败，5-交易可疑，6-交易异常,7-待补充材料，8-入账复核中',
  `PAYEE_TYPE` tinyint(2) NOT NULL DEFAULT 2 COMMENT '收款类型，1-平台收款，2-外部其他收款 3-B2B 4-服贸',
  `CHANNEL_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '渠道入账状态：1-已入账，2-未入账,3-入账失败',
  `FILE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '文件处理状态:1-待处理11C文件 2-11C文件已处理',
  `CHANNEL_INCOME_AT` timestamp NULL DEFAULT NULL COMMENT '渠道入账时间',
  `RECONCILIATION_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道流水号短号',
  `PAYMENT_RAIL` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款渠道',
  `MASTER_ACCOUNT_NO` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主账号',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `FS_BATCH_ID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'FS的批次号',
  `RESERVE_FIELD_ONE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留字段 1',
  `CHANNEL_DETAILS_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道侧的明细编号',
  `EXT1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用于存放11C的文件相关',
  `EXT2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_DTAILS_ID`(`DETAILS_ID`) USING BTREE,
  UNIQUE INDEX `UDX_BANK_NO_CHANNEL`(`BANK_NO`, `CHANNEL_ID`, `PAYEE_CCY`) USING BTREE,
  UNIQUE INDEX `UDX_BN_ID_CY`(`BANK_NO`, `PAYEE_CCY`) USING BTREE,
  INDEX `IDX_CREATE_AT_USER`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_CHANNEL_ID`(`CHANNEL_ID`) USING BTREE,
  INDEX `IDX_CID_RFO`(`CHANNEL_ID`, `RESERVE_FIELD_ONE`) USING BTREE,
  INDEX `IDX_CHANNEL_DETAILS_ID`(`CHANNEL_DETAILS_ID`) USING BTREE COMMENT '渠道侧的明细编号索引',
  INDEX `IDX_FS_BATCH_ID`(`FS_BATCH_ID`) USING BTREE COMMENT 'FS的批次号索引'
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基金赎回入账订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_REFUND_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_REFUND_ORDER`;
CREATE TABLE `T_REFUND_ORDER`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `REFUND_ORDER_ID` bigint(19) NOT NULL COMMENT '退款订单号',
  `REFUND_TYPE` int(11) NOT NULL COMMENT '退款类型：1=收款账户付款退汇；2=收款账户提现退汇；3=汇兑充值提现退汇；4=汇兑充值付款退汇；5=收款入账退款；6=汇兑充值退款；',
  `REFUND_TRADE_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款交易类型：PAYMNET:付款退款',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户号',
  `ORIGINAL_ORDER_ID` bigint(19) NOT NULL COMMENT '原订单号',
  `ORIGINAL_ORDER_AMT` decimal(18, 2) NOT NULL COMMENT '原订单金额',
  `ORIGINAL_ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '原订单币种',
  `ORIGINAL_CHANNEL_BANK_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原渠道流水号',
  `REFUND_AMT` decimal(18, 2) NOT NULL COMMENT '退款金额',
  `REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退款币种',
  `REFUND_FEE` decimal(18, 2) NULL DEFAULT NULL COMMENT '退款手续费',
  `STATE` int(11) NOT NULL COMMENT '0#初始化待退款 1#退款中 2#退款成功 3#退款失败 4#用户确认中 6#线下退款中 7#退款待复核 8#无需退款 9#待扣手续费 10#待初审  11#待风控审核 12#退款被退回',
  `AUDIT_STATE` int(11) NOT NULL COMMENT '审核状态: 待审核；待复核；审核成功；审核失败',
  `CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退款渠道',
  `ORIGINAL_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '原渠道编号',
  `CHANNEL_ACCT_NO` varchar(80) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道账号',
  `CHANNEL_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道币种',
  `REFUND_MODEL` tinyint(3) NULL DEFAULT NULL COMMENT '退款模式：1-原路退回，2-付款退回',
  `CHANNEL_REFUND_STATE` tinyint(3) NULL DEFAULT NULL COMMENT '渠道退款状态：1-初始，2-退款中，3-成功，4-失败，5-异常',
  `REFUND_COST_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款成本币种',
  `REFUND_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '退款成本',
  `REFUND_REASON` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款原因',
  `PAYMENT_FEE_REFUND_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '付款手续费退回金额',
  `PAYMENT_FEE_REFUND_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款手续费退回金额币种',
  `REFUND_BANK_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道流水号',
  `AUDIT_INIT_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `AUDIT_INIT_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审人',
  `AUDIT_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '终审时间',
  `AUDIT_FINAL_BY` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '终审人',
  `REFUND_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '退款完成时间',
  `REFUND_DATE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款时间',
  `REMARK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `REMARK1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '一审核备注',
  `TOW_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '二审备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `MERCHANT_REFUND_AMT` decimal(18, 2) NULL DEFAULT NULL COMMENT '商户退款金额',
  `MERCHANT_REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户退款币种',
  `CHANNEL_REFUND_AMT` decimal(18, 2) NULL DEFAULT NULL COMMENT '渠道退款金额',
  `CHANNEL_REFUND_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道退款币种',
  `CUSTOMER_ERROR_MESSAGE_CN` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客退款原因-中文',
  `CUSTOMER_ERROR_MESSAGE_EN` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客退款原因-英文',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_ori_order_id`(`ORIGINAL_ORDER_ID`) USING BTREE,
  INDEX `IDX_REFUND_FINAL_AT`(`REFUND_FINAL_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1693 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '付款订单的退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_REFUND_ORDER_PRO
-- ----------------------------
DROP TABLE IF EXISTS `T_REFUND_ORDER_PRO`;
CREATE TABLE `T_REFUND_ORDER_PRO`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `REFUND_ORDER_ID` bigint(19) NOT NULL COMMENT '退款订单号',
  `REFUND_TYPE` int(11) NOT NULL COMMENT '退款类型：1=收款账户付款退汇；2=收款账户提现退汇；3=汇兑充值提现退汇；4=汇兑充值付款退汇；',
  `REFUND_TRADE_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款交易类型：INCOME：入账退款，PAYMENT:付款退款',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户号',
  `ORIGINAL_ORDER_ID` bigint(19) NOT NULL COMMENT '原订单号',
  `ORIGINAL_ORDER_AMT` decimal(18, 2) NOT NULL COMMENT '原订单金额',
  `ORIGINAL_ORDER_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原订单币种',
  `ORIGINAL_CHANNEL_BANK_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原渠道流水号',
  `REFUND_AMT` decimal(18, 2) NOT NULL COMMENT '退款金额',
  `REFUND_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退款币种',
  `REFUND_FEE` decimal(18, 2) NULL DEFAULT NULL COMMENT '退款手续费',
  `STATE` int(11) NOT NULL COMMENT '退款状态:0=待退款 1=退款中 2=退款成功 3=退款失败',
  `AUDIT_STATE` int(11) NOT NULL COMMENT '审核状态: 0=待审核；1=待复核；2=审核成功；3=审核失败',
  `CHANNEL_ID` bigint(20) NULL DEFAULT 0 COMMENT '退款渠道',
  `ORIGINAL_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '原渠道编号',
  `CHANNEL_ACCT_NO` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款渠道账号',
  `CHANNEL_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款渠道币种',
  `REFUND_MODEL` tinyint(3) NULL DEFAULT NULL COMMENT '退款模式：1-原路退回，2-付款退回',
  `CHANNEL_REFUND_STATE` tinyint(3) NULL DEFAULT NULL COMMENT '渠道退款状态：1-初始，2-退款中，3-成功，4-失败，5-异常',
  `REFUND_COST_CCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款成本币种',
  `REFUND_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '退款成本',
  `REFUND_REASON` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款原因',
  `PAYMENT_FEE_REFUND_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '付款手续费退回金额',
  `PAYMENT_FEE_REFUND_CCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款手续费退回金额币种',
  `REFUND_BANK_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款渠道流水号',
  `SALE_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属销售',
  `AUDIT_INIT_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `AUDIT_INIT_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '初审人',
  `AUDIT_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '终审时间',
  `AUDIT_FINAL_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终审人',
  `REFUND_FINAL_AT` timestamp NULL DEFAULT NULL COMMENT '退款完成时间',
  `REFUND_DATE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款日期',
  `REMARK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `REMARK1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '一审核备注',
  `TOW_REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二审备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_REFUND_ORDER_ID`(`REFUND_ORDER_ID`) USING BTREE,
  INDEX `idx_ori_order_id`(`ORIGINAL_ORDER_ID`) USING BTREE,
  INDEX `idx_refund_date`(`REFUND_DATE`) USING BTREE,
  INDEX `IDX_REFUND_FINAL_AT`(`REFUND_FINAL_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1045 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退款订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_REISSUE_AUDIT_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_REISSUE_AUDIT_ORDER`;
CREATE TABLE `T_REISSUE_AUDIT_ORDER`  (
