  `CNTRCT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '合同号',
  `INVO_NO` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '发票号',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10571 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '汇款结算账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_REMITTANCE_SUMMARY
-- ----------------------------
DROP TABLE IF EXISTS `T_REMITTANCE_SUMMARY`;
CREATE TABLE `T_REMITTANCE_SUMMARY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `REMITTANCE_BATCH_ID` bigint(20) NOT NULL COMMENT '汇款批次号',
  `SOURCE_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户号',
  `SOURCE_AMT` decimal(19, 2) NOT NULL COMMENT '金额',
  `SOURCE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `DEST_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账户号',
  `DEST_AMT` decimal(19, 2) NOT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `REMITTANCE_TYPE` tinyint(2) NOT NULL COMMENT '汇款类型：1-GEP付款，2-渠道付款',
  `REMITTANCE_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '汇款状态：-1-汇款失败，0-待汇款 1-已汇款，2-汇款成功 3-待初审 4-待复核',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '订单完成时间',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `CHANNEL_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道成本',
  `MEMBER_ID` bigint(20) NOT NULL COMMENT '商户编号',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审人(业务确认)',
  `EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '复核人(清算确认)',
  `REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '复核时间',
  `BANK_VOUCHER_EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网银制单',
  `BANK_VOUCHER_EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '网银制单时间',
  `BANK_VOUCHER_REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网银复核',
  `BANK_VOUCHER_REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '网银复核时间',
  `PAYMENT_PURPOSE` tinyint(4) NULL DEFAULT NULL COMMENT '付款用途：1-往来结算款、2-货款、3-差旅费、4-生活费、5-投资款项、6-办公费用、7-工程款、8-劳务费/薪酬、9-学费、10-其他',
  `EXT_DATA` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展信息',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `FEE_BEAR_TYPE` int(1) NULL DEFAULT NULL COMMENT '手续费承担方式：1-SHARE，2-OUR',
  `SETTLE_MEMBER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '结汇商户类型：1-宝付换汇，2-境外换汇，3-结汇垫资,4-独立商户号结汇',
  `PAYMENT_MODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款模式：SWIFT:国际汇款  LOCAL：本地汇款',
  `FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FEE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费',
  `BUSINESS_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '业务类型：1-跨境人民币，2-跨境外汇',
  `BANK_REMIT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行实际出款金额',
  `BANK_REMIT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行实际出款币种',
  `BANK_REMIT_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '银行实际出款汇率',
  `PAYEE_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '收款渠道编号',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '01' COMMENT '行业类型 01=货物贸易 06=物流',
  `USER_RECEIPT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户到账币种',
  `USER_RECEIPT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '用户到账金额',
  `CHANNEL_SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道结汇币种',
  `CHANNEL_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道结汇金额',
  `CHANNEL_SETTLE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道结汇手续费',
  `CHANNEL_RESP_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行渠道流水号',
  `POBO_PAY` tinyint(2) NULL DEFAULT 0 COMMENT '是否POBO付款，0-否，1-是',
  `PAYMENT_SYSTEM` varchar(35) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '出款系统',
  `SETTLE_COMPLETE_AT` datetime NULL DEFAULT NULL COMMENT '结汇完成时间',
  `REMIT_METHOD` tinyint(2) NULL DEFAULT NULL COMMENT '出款方式 0-API 1-人工',
  `BATCH_ID` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `PAYER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款请求渠道流水号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE,
  INDEX `IDX_BATCH_ID`(`BATCH_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10568 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '付款批次汇总表' ROW_FORMAT = Dynamic;

