  `EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审人(业务确认)',
  `EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '初审时间',
  `REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '复核人(清算确认)',
  `REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '复核时间',
  `BANK_VOUCHER_EXAMINE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网银制单',
  `BANK_VOUCHER_EXAMINE_AT` timestamp NULL DEFAULT NULL COMMENT '网银制单时间',
  `BANK_VOUCHER_REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网银复核',
  `BANK_VOUCHER_REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '网银复核时间',
  `PAYMENT_PURPOSE` tinyint(4) NULL DEFAULT NULL COMMENT '付款用途：1-往来结算款、2-货款、3-差旅费、4-生活费、5-投资款项、6-办公费用、7-工程款、8-劳务费/薪酬、9-学费、10-其他',
  `EXT_DATA` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展信息',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `FEE_BEAR_TYPE` int(1) NULL DEFAULT NULL COMMENT '手续费承担方式：1-SHARE，2-OUR',
  `SETTLE_MEMBER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '结汇商户类型：1-宝付换汇，2-境外换汇，3-结汇垫资',
  `PAYMENT_MODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款模式：SWIFT:国际汇款  LOCAL：本地汇款',
  `FEE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费',
  `BUSINESS_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '业务类型：1-跨境人民币，2-跨境外汇',
  `FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费币种',
  `BANK_REMIT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行实际出款金额',
  `BANK_REMIT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行实际出款币种',
  `BANK_REMIT_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '银行实际出款汇率',
  `PAYEE_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '收款渠道编号',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '01' COMMENT '行业类型 01=货物贸易 06=物流',
  `USER_RECEIPT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户到账币种',
  `USER_RECEIPT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '用户到账金额',
  `CHANNEL_SETTLE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道结汇币种',
  `CHANNEL_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道结汇金额',
  `CHANNEL_SETTLE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道结汇手续费',
  `CHANNEL_RESP_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行渠道流水号',
  `POBO_PAY` tinyint(2) NULL DEFAULT 0 COMMENT '是否POBO付款，0-否，1-是',
  `PAYMENT_SYSTEM` varchar(35) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '出款系统',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29068 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RISK_CONTROL_RULES
-- ----------------------------
DROP TABLE IF EXISTS `T_RISK_CONTROL_RULES`;
CREATE TABLE `T_RISK_CONTROL_RULES`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RULE_CODE` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则代码',
  `RULE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则名称',
  `RULE_TYPE` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '规则类型:THRESHOLD 阈值/ VALIDATION验证/EXTERNAL 外部调用',
  `RULE_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态:0禁用,1启用',
  `CONDITION_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '条件类型GT,LT,EQ,NE,CONTAINS,IN',
  `THRESHOLD_VALUE` decimal(20, 2) NULL DEFAULT NULL COMMENT '阈值数值',
  `CURRENCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '货币类型',
  `COMPARISON_FIELD` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '比较字段 模板中的字段',
  `ERROR_MESSAGE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '错误提示信息',
  `EXTERNAL_SERVICE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '外部服务名称',
  `PRIORITY` tinyint(2) NULL DEFAULT 0 COMMENT '规则优先级',
  `BIZ_TYPE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务类型 01 货物 06物流 08广告',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RULE_CODE_BIZ`(`RULE_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '风控规则配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_RISK_LOGISTICS_STATUS_MAPPING
-- ----------------------------
DROP TABLE IF EXISTS `T_RISK_LOGISTICS_STATUS_MAPPING`;
CREATE TABLE `T_RISK_LOGISTICS_STATUS_MAPPING`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `STATUS_CODE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流状态代码',
  `STATUS_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物流状态名称',
  `RISK_STATUS` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '风控状态:通过 PASS/不通过 FAIL',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态:0禁用,1启用',
  `REMARKS` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_STATUS_CODE`(`STATUS_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物流状态映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SALE_COST_RATE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_SALE_COST_RATE_CONFIG`;
CREATE TABLE `T_SALE_COST_RATE_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `CURRENCY_PAIR` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币对',
  `TRADE_DIRECTION` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交易方向：BUY=买入, SELL=卖出',
  `SELL_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '卖出币种',
  `BUY_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '买入币种',
  `BUSINESS_LINE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务线, SHOP-电商、E_TRADE-E贸汇、GEP-GEP汇兑、SERVICE-服贸',
  `CHANNEL_CODE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道编码',
  `RATE_SOURCE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报价源',
  `FLOAT_TYPE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '浮动方式 BP / PCT-百分比 ',
  `FLOAT_VALUE` decimal(18, 8) NULL DEFAULT 0.00000000 COMMENT '浮动值',
  `STATUS` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ENABLE' COMMENT '状态：ENABLE=启用, DISABLE=停用',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `IS_DELETE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N' COMMENT '逻辑删除标识：N=正常, Y=已删除',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CUR_BUSUNESS`(`CURRENCY_PAIR`, `BUSINESS_LINE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售成本汇率管理配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SALE_QUOTA
-- ----------------------------
DROP TABLE IF EXISTS `T_SALE_QUOTA`;
CREATE TABLE `T_SALE_QUOTA`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '销售编号',
  `SALE_MONTH` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '销售月份',
  `TARGET_SALE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '目标销量',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `STATE` tinyint(2) NULL DEFAULT NULL COMMENT '状态：-1-删除 0-正常',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 560 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '销售交易量指标表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SALE_SHARE_SUMMARY
-- ----------------------------
DROP TABLE IF EXISTS `T_SALE_SHARE_SUMMARY`;
CREATE TABLE `T_SALE_SHARE_SUMMARY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '销售编号',
  `SUMMARY_MONTH` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '汇总月份',
  `TRADE_AMT` decimal(19, 2) NOT NULL COMMENT '交易量（等值人民币）',
  `DESERVED_AMT` decimal(19, 2) NOT NULL COMMENT '应得提成',
  `REAL_AMT` decimal(19, 2) NOT NULL COMMENT '实得提成',
  `SETTLE_STATE` tinyint(2) NOT NULL COMMENT '结算状态：-1失败 0-初始，1-完成',
  `SETTLE_COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '结算完成时间',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_AGENT_NO`(`SUMMARY_MONTH`, `AGENT_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 135 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '销售提成汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SENSITIVE_WORDS
-- ----------------------------
DROP TABLE IF EXISTS `T_SENSITIVE_WORDS`;
CREATE TABLE `T_SENSITIVE_WORDS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `WORD` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '关键词',
  `LEVEL` int(11) NOT NULL COMMENT '级别：1-包含 2-等于',
  `BIZ_TYPE` int(11) NOT NULL COMMENT '业务类型 1-结汇',
  `REMARKS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注说明',
  `STATUS` tinyint(4) NOT NULL COMMENT '状态 0-删除 1-有效',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 272 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '敏感词维护表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SETTLE_ADVANCE_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_SETTLE_ADVANCE_APPLY`;
CREATE TABLE `T_SETTLE_ADVANCE_APPLY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型：1-B2B结汇垫资，2-GEP结汇垫资',
  `FEE_RATE` decimal(19, 2) NULL DEFAULT NULL COMMENT '费率',
  `TOTAL_QUOTA` decimal(19, 2) NULL DEFAULT NULL COMMENT '额度',
  `PRO_NODE` tinyint(2) NULL DEFAULT 0 COMMENT '流程节点 -1:流程结束 0:待销售处理 1:销售主管审批 2:合规审核 3:事中审核',
  `STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '状态：0-处理中，1-处理成功，2-处理失败',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户结汇垫资申请开通流程' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SETTLE_CHANNEL
-- ----------------------------
DROP TABLE IF EXISTS `T_SETTLE_CHANNEL`;
CREATE TABLE `T_SETTLE_CHANNEL`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `CHANNEL_CLASS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道处理类',
  `PAYER_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款人名称',
  `PAYER_ACC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款人账号',
  `PAYER_COUNTRY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款人国家',
  `PAYER_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '收款渠道编号(结算渠道)',
  `NEX_START_DATE` datetime NULL DEFAULT NULL COMMENT '下次开始结算日期',
  `BANK_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行名称',
  `BANK_BRANCH_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支行名称',
  `CARD_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '银行卡类型',
  `BANK_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行编码',
  `SWIFT_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行代码SwiftCode',
  `CITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '市',
  `PROVINCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省',
  `PAYEE_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行地址',
  `MIDDLE_SWIFT_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中转行SWIFT_CODE',
  `MIDDLE_BANK_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中转行银行名称',
  `MIDDLE_BANK_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中转行国家',
  `CLEARING_CODE` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行代码',
  `ACCOUNT_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户币种',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道币种',
  `STATE` tinyint(2) NULL DEFAULT NULL COMMENT '渠道状态：-1-禁用 0-待审核 1-可用',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '渠道信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SETTLE_CHANNEL_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_SETTLE_CHANNEL_CONFIG`;
CREATE TABLE `T_SETTLE_CHANNEL_CONFIG`  (
