  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '垫资渠道配置信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SETTLE_ORDER_AD
-- ----------------------------
DROP TABLE IF EXISTS `T_SETTLE_ORDER_AD`;
CREATE TABLE `T_SETTLE_ORDER_AD`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ORDER_ID` bigint(20) NOT NULL DEFAULT 0 COMMENT '跨境订单号',
  `START_TIME` timestamp NOT NULL COMMENT '结算开始时间',
  `END_TIME` timestamp NOT NULL COMMENT '结算结束时间',
  `PLATFORM` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '广告平台',
  `INCOME_RATE` decimal(19, 3) NOT NULL COMMENT '收益转化率',
  `LINK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '广告链接',
  `PLACEMENT` varchar(80) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '广告投放商',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `PRICE` decimal(19, 3) NULL DEFAULT NULL COMMENT '价格',
  `TIMES` int(11) NULL DEFAULT NULL COMMENT '数量',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_order_id`(`ORDER_ID`) USING BTREE,
