-- ----------------------------
-- Table structure for T_SMALL_CCY_PROFIT
-- ----------------------------
DROP TABLE IF EXISTS `T_SMALL_CCY_PROFIT`;
CREATE TABLE `T_SMALL_CCY_PROFIT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `RECORD_MONTH` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录月份',
  `RECORD_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录币种',
  `CHANNEL_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '渠道编号',
  `ALL_USD_PROFIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总损益（美元）',
  `RECORD_USD_PROFIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '当月损益（美元）',
  `GEP_RECORD_CCY_EXPOSURE` decimal(19, 2) NULL DEFAULT NULL COMMENT 'GEP小币种敞口',
  `GEP_USD_EXPOSURE` decimal(19, 2) NULL DEFAULT NULL COMMENT 'GEP美元敞口',
  `CHANNEL_RECORD_CCY_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道当月结算金额（小币种）',
  `CHANNEL_USD_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道当月结算金额（美元）',
  `CUSTOMER_RECORD_SALE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月卖出金额（小币种）',
  `CUSTOMER_RECORD_BUY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月买入金额（美元）',
  `CUSTOMER_RECORD_BUY_REVERSED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月买入金额（小币种）',
  `CUSTOMER_RECORD_SALE_REVERSED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月卖出金额（美元）',
  `CUSTOMER_RECORD_SAME_CCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月同币种出款（小币种）',
  `CUSTOMER_RECORD_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户当月手续费（小币种）',
  `FIXED_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '报表汇率',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '1-正常，2-已删除',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `DISTRIBUTION_PROFIT_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '分发兑换损益(USD)',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `UDX_REQUEST_NO_TYPE`(`RECORD_MONTH`, `RECORD_CCY`, `STATUS`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 877 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小币种损益月份记录总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SMALL_CCY_USER_PROFIT
-- ----------------------------
DROP TABLE IF EXISTS `T_SMALL_CCY_USER_PROFIT`;
CREATE TABLE `T_SMALL_CCY_USER_PROFIT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `RECORD_MONTH` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录月份',
  `RECORD_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录币种',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
