  `FLOAT_USD_PROFIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '浮动损益（美元）',
  `AVG_USD_PROFIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '平均损益（美元）',
  `TRADE_PERCENTAGE` decimal(10, 6) NULL DEFAULT NULL COMMENT '交易占比',
  `FLOAT_PERCENTAGE` decimal(10, 6) NULL DEFAULT NULL COMMENT '浮动百分比',
  `USER_SELL_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '商户卖出金额（小币种）',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '1-正常，2-已删除',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_REQUEST_NO_TYPE`(`RECORD_MONTH`, `RECORD_CCY`, `USER_NO`, `STATUS`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1667 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小币种损益商户记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SMALL_CCY_USER_PROFIT_DETAIL
-- ----------------------------
