  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `RECORD_MONTH` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录月份',
  `RECORD_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '记录币种',
