  INDEX `IDX_REQUEST_NO`(`REQUEST_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6282 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小币种损益订单明细记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SMALL_EXCHANGE_RATE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_SMALL_EXCHANGE_RATE_CONFIG`;
CREATE TABLE `T_SMALL_EXCHANGE_RATE_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RECORD_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '唯一配置ID',
  `BUSINESS` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '业务线 SHOP:电商 SERVICE:服贸 E_TRADE:E-贸汇 GEP',
  `CURRENCY_PAIR` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '币种对',
  `TRADE_DIRECTION` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易方向1-买入 2-卖出',
  `RECEIVE_CHANNEL` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收款渠道',
  `RATE_RESOURCE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '汇率报价原',
  `RATE_BP` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '报价bp 单位%',
  `STATUS` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '状态 OPEN启用 CLOSE关闭 DEL删除',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE
