-- ----------------------------
-- Table structure for T_SPIDER_EXCHANGE_PRICE
-- ----------------------------
DROP TABLE IF EXISTS `T_SPIDER_EXCHANGE_PRICE`;
CREATE TABLE `T_SPIDER_EXCHANGE_PRICE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '自增长ID，主键',
  `FREQUENCY` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新频率',
  `SNAPSHOT_TIME` datetime NOT NULL COMMENT '快照时间',
  `CCY_GROUP` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '货币对',
  `SOURCE_CCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '源币种',
  `DEST_CCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `BUY_PRICE` decimal(10, 4) NULL DEFAULT NULL COMMENT '买入价',
  `SELL_PRICE` decimal(10, 4) NULL DEFAULT NULL COMMENT '卖出价',
  `SELL_CHANNEL` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源渠道',
  `SOURCE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据来源名称，例如\"中国外汇交易中心\"',
  `SOURCE_LINK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据来源链接',
  `DUPLICATE_KEY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '重复键，唯一索引，防止重复数据插入',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `DUPLICATE_KEY`(`DUPLICATE_KEY`) USING BTREE,
  INDEX `SNAPSHOT_TIME_INDEX`(`SNAPSHOT_TIME`) USING BTREE COMMENT '快照时间索引，用于快速查询'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '汇率爬虫表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STANDARD_COEFFICIENT
-- ----------------------------
DROP TABLE IF EXISTS `T_STANDARD_COEFFICIENT`;
CREATE TABLE `T_STANDARD_COEFFICIENT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PRODUCT_TYPE` tinyint(2) NOT NULL COMMENT '产品类型 1:收款账户-销售分成系数',
  `REGION_MAX_VAL` decimal(19, 3) NULL DEFAULT NULL COMMENT '区间最大值',
  `REGION_MIN_VAL` decimal(19, 3) NULL DEFAULT NULL COMMENT '区间最小值',
  `REGION_OPERATOR` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '区间运算符（ <、~、>、<=、>=）',
  `REGION_VAL` decimal(19, 3) NULL DEFAULT NULL COMMENT '区间系数值',
  `SORT` int(10) NULL DEFAULT NULL COMMENT '系数顺序',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_PRODUCT_TYPE`(`PRODUCT_TYPE`, `SORT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '达标系数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STOP_PROFIT_LOSS_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_STOP_PROFIT_LOSS_CONFIG`;
CREATE TABLE `T_STOP_PROFIT_LOSS_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `CURRENCY_PAIR` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币对',
  `MONITOR_PERIOD` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '监控时段：工作日-WORKDAY，节假日-HOLIDAY',
  `CLOSING_TYPE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交割期限：TOD,TOM,SPOT',
  `STOP_LOSS_STRATEGY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止损策略：预警-FORWARD,下单-ORDER',
  `STOP_LOSS_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止损类型：百分比-PCT,固定金额-AMT,固定汇率-RATE',
  `STOP_LOSS_VALUE` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '止损阈值',
  `STOP_LOSS_CHANNEL` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止损监控渠道',
  `STOP_LOSS_CLOSING` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止损交割期限：TOD,TOM,SPOT',
  `STOP_PROFIT_STRATEGY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止盈策略：预警-FORWARD,下单-ORDER',
  `STOP_PROFIT_TYPE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止盈类型：百分比-PCT,固定金额-AMT,固定汇率-RATE',
  `STOP_PROFIT_VALUE` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '止盈阈值',
  `STOP_PROFIT_CHANNEL` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止盈监控渠道',
  `STOP_PROFIT_CLOSING` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止盈交割期限：TOD,TOM,SPOT',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `IS_DELETE` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N' COMMENT '逻辑删除标识：N=正常, Y=已删除',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CCY`(`CURRENCY_PAIR`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '止盈止损配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STORE_ACCOUNT_CLOSE_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_STORE_ACCOUNT_CLOSE_APPLY`;
CREATE TABLE `T_STORE_ACCOUNT_CLOSE_APPLY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `APPLY_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申请编号',
  `BATCH_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申请批次号',
  `STORE_NO` bigint(20) NOT NULL COMMENT '店铺编号',
  `ACCOUNT_NO` bigint(20) NOT NULL COMMENT 'GEP账户编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CLOSE_REASON` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '注销原因',
  `STATUS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账户状态：PENDING-等待注销，CLOSING-注销中，SUCCESS：注销成功 FAILED：注销失败',
  `FAILED_MSG` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '注销失败原因',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_APPLY_ID`(`APPLY_ID`) USING BTREE,
  INDEX `IDX_ACCOUNT_NO`(`ACCOUNT_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 174 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户注销店铺VA账户申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STORE_BIND_KYC_CHECK_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_STORE_BIND_KYC_CHECK_LOG`;
CREATE TABLE `T_STORE_BIND_KYC_CHECK_LOG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '关联流水表记录编号',
  `PLAT_USER_NO` bigint(20) NOT NULL COMMENT '平台用户号(平台在GEP的用户号)',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台卖家编号',
  `SELLER_NAME` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台卖家名称',
  `SELLER_CERT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '在平台注册的卖家证件号码',
  `COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖家的归属国家',
  `QUALIFIED_NO` bigint(20) NULL DEFAULT NULL COMMENT '资质编号',
  `QUALIFIED_NAME` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'GEP侧主体名称',
  `QUALIFIED_CERT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'GEP侧证件号码',
  `QUALIFIED_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'GEP侧归属国家',
  `CHECK_RET` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '对比结果：Y-一致，N-不一致',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_SELLER_ID`(`SELLER_ID`) USING BTREE COMMENT '平台 卖家编号唯一',
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 75 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '直连平台绑店KYC校验日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STORE_ORDER_FILE
-- ----------------------------
DROP TABLE IF EXISTS `T_STORE_ORDER_FILE`;
CREATE TABLE `T_STORE_ORDER_FILE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `FILE_BATCH_NO` bigint(19) NOT NULL COMMENT '文件批次号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `STORE_NO` bigint(19) NULL DEFAULT NULL COMMENT '店铺编号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户请求单号',
  `STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺所在平台',
  `ORDER_COUNT` int(11) NULL DEFAULT NULL COMMENT '订单明细笔数',
  `ORDER_SUM_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '订单汇总金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单币种',
  `FILE_DFS_ID` bigint(19) NOT NULL COMMENT '文件DFS ID',
  `FILE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件名称',
  `HANDLE_FAIL_FILE_ID` bigint(19) NULL DEFAULT 0 COMMENT '文件处理失败文件ID',
  `BIZ_ID` bigint(19) NOT NULL DEFAULT 0 COMMENT '业务编号',
  `FILE_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '文件类型 0-收款账户店铺订单明细,1-结汇订单明细 2-B2B收款结汇',
  `STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '状态：0-无需审核，1-待审核，2-审核成功，3-审核失败，4-处理失败，5-审核处理中 6-审核驳回',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `HANDLE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '文件处理状态：0-待处理，1-文件处理中，2-处理成功，3-处理失败,4-文件交易中，5-文件校验失败，6-部分成功',
  `AUDIT_AT` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `VOUCHER_FILE_ID` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件附带的证明文件ID 多个英文逗号分割 123,456,789',
  `PAYEE_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人姓名',
  `WORDS_FLAG` tinyint(2) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '01' COMMENT '行业类型：01=货物贸易 06=物流 07=软件服务 08=广告收入',
  `FILE_SRC_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '订单文件来源：0-页面填写，1-文件提交',
  `SETTLE_FLAG` tinyint(2) NULL DEFAULT 1 COMMENT '是否允许用于结汇：0-否 1-是',
  `SWITCH_AUDIT_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '结汇切换审核状态：-1 初始(无) 0-待审核 1-审核驳回 2-审核成功 3-审核拒绝',
  `USER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  `LOGISTICS_STATUS` tinyint(2) NOT NULL DEFAULT -1 COMMENT '状态：-1 初始(无)， 10-待补传材料 11-已补充（已补传待审核 ）12-重新补传材料 13-审核通过',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE,
  INDEX `IDX_CREATE`(`CREATE_AT`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63014 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_STORE_PLATFORM_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_STORE_PLATFORM_CONFIG`;
CREATE TABLE `T_STORE_PLATFORM_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `TEMPLATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '模板ID',
  `PLATFORM_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台',
  `PLATFORM_SUB_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台站台',
  `PLATFORM_SUB_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台站台名称',
  `STATUS` char(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'ENABLE' COMMENT '状态 ENABLE-启用 DISABLE-禁用',
  `CAPTION_ONE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '说明1',
  `CAPTION_TWO` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '说明2',
  `SUPPORT_AUTH` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持授权 Y-是 N-否',
  `HANDBOOK_FILE_ID` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手册1',
  `CAPTION_THREE` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '说明3',
  `CAPTION_NUMBER` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户数量说明',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `BIND_TYPE` char(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '绑定类型 直连-API 普通-COMMON',
  `HANDBOOK_FILE_ID_TWO` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手册2',
  `HANDBOOK_FILE_ID_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手册1名称',
  `HANDBOOK_FILE_ID_TWO_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手册2名称',
  `PRIORITY_LEVEL` int(11) NULL DEFAULT NULL COMMENT '优先级',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_STORE_PLATFORM`(`PLATFORM_CODE`, `TEMPLATE_ID`, `PLATFORM_SUB_CODE`) USING BTREE,
  INDEX `IDX_PLATFORM_CODE`(`PLATFORM_CODE`) USING BTREE,
  INDEX `IDX_PLATFORM_SUB_CODE`(`PLATFORM_SUB_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 338 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '电商平台配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUB_ACCOUNT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_SUB_ACCOUNT_DETAIL`;
CREATE TABLE `T_SUB_ACCOUNT_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `ACCOUNT_NO` bigint(20) NOT NULL COMMENT '账户号',
  `ORDER_TYPE` int(2) NOT NULL COMMENT '订单类型：1-转账，2-提现付款，3-充值，4-提现付款退回',
  `ORDER_SUB_TYPE` int(3) NOT NULL COMMENT '订单细类',
  `TARGET_MEMBER_ID` bigint(20) NULL DEFAULT NULL COMMENT '转账目标商户号，转账订单时不能为空',
  `TARGET_ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '转账目标账户号，转账订单时不能为空',
  `ORDER_AMT` decimal(19, 3) NOT NULL COMMENT '订单金额',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ACCOUNT_BAL` decimal(19, 3) NOT NULL COMMENT '账户余额',
  `ACCOUNT_END_BAL` decimal(19, 3) NOT NULL COMMENT '账户交易后余额',
  `BAL_DIRECTION` int(2) NULL DEFAULT NULL COMMENT '余额方向:1-收入；2-支出',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ACCOUNT_TYPE`(`ORDER_ID`, `ACCOUNT_NO`, `ORDER_TYPE`, `ORDER_SUB_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`, `CREATE_AT`) USING BTREE,
  INDEX `IDX_ACCOUNT_NO`(`ACCOUNT_NO`, `CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 173093 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '子账户操作明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUB_PLATFORM_CAPABILITY
-- ----------------------------
DROP TABLE IF EXISTS `T_SUB_PLATFORM_CAPABILITY`;
CREATE TABLE `T_SUB_PLATFORM_CAPABILITY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `SUB_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '站点编码',
  `CAPABILITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '能力',
  `STATUS` tinyint(3) NULL DEFAULT 1 COMMENT '状态：0.下线 1.上线 2.白名单灰度',
  `WHITELIST_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '白名单灰度KEY,命名规则 SUB_PLATFORM+\"_\"+CAPABILITY',
  `remark` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_SUB_PLATFORM_CAPABILITY`(`SUB_PLATFORM`, `CAPABILITY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '平台站点能力表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUB_PLATFORM_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_SUB_PLATFORM_INFO`;
CREATE TABLE `T_SUB_PLATFORM_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `SUB_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '站点编码',
  `SUB_PLATFORM_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '站点名称',
  `SUB_PLATFORM_EN_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '站点英文名称',
  `PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台编码',
  `COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '国家',
  `CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `BIND_TYPE` tinyint(3) NOT NULL COMMENT '绑定类型：1.offline绑定，2.跳转授权绑定 3.API直连',
  `AUTH_TYPE` tinyint(3) NOT NULL COMMENT '授权类型：1.oauth2 授权,2.KEY授权2',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `STATUS` tinyint(3) NULL DEFAULT 1 COMMENT '状态：0.下线 1.上线 2.白名单灰度',
  `WHITELIST_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '白名单灰度KEY,命名规则 SUB_PLATFORM+\"_WHITELIST\"',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_SUB_PLATFORM`(`SUB_PLATFORM`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 95 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '平台站点信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_LOGIN_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_LOGIN_INFO`;
CREATE TABLE `T_SUPPLY_LOGIN_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `LOGIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录账户号 手机号或邮箱',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `LOGIN_TYPE` tinyint(2) NOT NULL COMMENT '登录账户类型：1-邮箱，2-手机号码',
  `LOGIN_STATE` tinyint(2) NOT NULL COMMENT '登录账户状态：1-正常',
  `LAST_LOGIN_AT` timestamp NOT NULL COMMENT '最后登录时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 265 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应链金融登录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_LOGIN_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_LOGIN_LOG`;
CREATE TABLE `T_SUPPLY_LOGIN_LOG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `LOGIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录账户号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `LOGIN_TYPE` tinyint(2) NOT NULL COMMENT '登录账户类型：1-邮箱，2-手机号码',
  `LOGIN_STATE` tinyint(2) NOT NULL COMMENT '登录账户状态：0-冻结，1-正常，2-锁定，3-注销',
  `STATE` tinyint(2) NOT NULL COMMENT '登录状态：0-登录失败，1-登录成功',
  `LOGIN_IP` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录IP',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注 登录失败时可把错误信息放入此字段',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 238 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户登录日志记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_NOTIFY_URL
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_NOTIFY_URL`;
CREATE TABLE `T_SUPPLY_NOTIFY_URL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `NOTIFY_URL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '通知地址',
  `STATE` tinyint(2) NOT NULL COMMENT '状态：0-正常1-失效',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_ORDER_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_ORDER_APPLY`;
CREATE TABLE `T_SUPPLY_ORDER_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `APPLY_ID` bigint(20) NOT NULL COMMENT '申请订单号',
  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户编号',
  `APPLY_TYPE` tinyint(2) NOT NULL COMMENT '申请类型 1-借款申请，2-线下还款申请',
  `APPLY_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '金额',
  `APPLY_STATE` tinyint(2) NOT NULL COMMENT '申请状态：-1-已失效 0-待确认 1-已确认 2-已拒绝',
  `DFS_FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT 'DFS文件编号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CONFIRM_AT` timestamp NULL DEFAULT NULL COMMENT '确认时间',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 196 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '借还款订单申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_ORDER_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_ORDER_DETAIL`;
CREATE TABLE `T_SUPPLY_ORDER_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `REPAYMENT_ID` bigint(20) NOT NULL COMMENT '还款明细订单号',
  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户编号',
  `REPAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '还款币种',
  `REPAYMENT_AMT` decimal(19, 2) NOT NULL COMMENT '还款金额',
  `REPAYMENT_TYPE` tinyint(2) NOT NULL COMMENT '还款类型： 1-自动扣款 2-已履行债务 3-履行债务',
  `ORDER_STATE` tinyint(2) NOT NULL COMMENT '订单状态：-1-还款失败 0-还款处理中 1-还款成功',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `REPAYMENT_AT` timestamp NULL DEFAULT NULL COMMENT '还款完成时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 95 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '交易还款明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_PARTNER_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_PARTNER_INFO`;
CREATE TABLE `T_SUPPLY_PARTNER_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `PARTNER_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '合作方名称',
  `EMAIL` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮箱地址',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户名称',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户号',
  `SWIFT` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'SWIFTCODE',
  `BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行地址',
  `SECRET_KEY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '秘钥',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  PRIMARY KEY (`ID`, `PARTNER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '合作方信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_PARTNER_RELATION
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_PARTNER_RELATION`;
CREATE TABLE `T_SUPPLY_PARTNER_RELATION`  (
