  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '商户编号',
  `DFS_FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT 'DFS文件编号',
  `BIND_STATE` tinyint(2) NOT NULL COMMENT '绑定状态：-1-已解绑，0-失效，1-已绑定,2-待绑定',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 414 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '合作方商户关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_REPAYMENT_RELATION
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_REPAYMENT_RELATION`;
CREATE TABLE `T_SUPPLY_REPAYMENT_RELATION`  (
