  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '供应链金融还款明细关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SUPPLY_WITHDRAW_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_SUPPLY_WITHDRAW_APPLY`;
CREATE TABLE `T_SUPPLY_WITHDRAW_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现明细编号',
  `PARTNER_ID` bigint(20) NOT NULL COMMENT '合作方编号',
  `ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '提现账户号(账务系统)',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户名称',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户号',
  `SWIFT` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'SWIFT CODE',
  `WITHDRAW_AMT` decimal(19, 2) NOT NULL COMMENT '提现金额',
  `WITHDRAW_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现币种',
  `WITHDRAW_FEE` decimal(19, 2) NOT NULL COMMENT '提现手续费',
  `DEST_AMT` decimal(19, 2) NOT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `TRANSFER_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现汇率',
  `WITHDRAW_FEE_RATE` decimal(19, 6) NOT NULL COMMENT '提现费率',
  `WITHDRAW_STATE` tinyint(2) NOT NULL COMMENT '提现状态，0-待提现；1-提现处理中，2-提现成功，3-提现失败',
  `WITHDRAW_AT` timestamp NULL DEFAULT NULL COMMENT '提现完成时间',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 205 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '合作方提现申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SYS_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_SYS_CONFIG`;
CREATE TABLE `T_SYS_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录唯一编号',
  `SYS_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '系统KEY标识',
  `SYS_VALUE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '系统属性值',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-启用，2-失效',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_SYS_KEY`(`SYS_KEY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SYS_FEE_STAGE
-- ----------------------------
DROP TABLE IF EXISTS `T_SYS_FEE_STAGE`;
CREATE TABLE `T_SYS_FEE_STAGE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `MIN_AMT` decimal(19, 2) NOT NULL COMMENT '最小金额',
  `MAX_AMT` decimal(19, 2) NOT NULL COMMENT '最大金额',
  `FEE_RATE` decimal(19, 2) NOT NULL COMMENT '费率',
  `FIXED_AMT` decimal(19, 2) NOT NULL COMMENT '固定金额',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统费率档位表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SYS_HOLIDAY
-- ----------------------------
DROP TABLE IF EXISTS `T_SYS_HOLIDAY`;
CREATE TABLE `T_SYS_HOLIDAY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '类型：1-货币兑换，2-GEP兑换平台，3-收款账户平台',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `HOLIDAY_DATE` date NOT NULL COMMENT '假期日期',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：-1：已删除 1-正常',
  `HOLIDAY_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '假期备注',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_HOLIDAY_DATE_CCY`(`HOLIDAY_DATE`, `CCY`) USING BTREE COMMENT '假期+币种普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统节假日表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SYS_NAME_LIST
-- ----------------------------
DROP TABLE IF EXISTS `T_SYS_NAME_LIST`;
CREATE TABLE `T_SYS_NAME_LIST`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `USER_TYPE` tinyint(2) NOT NULL DEFAULT 4 COMMENT '用户类型：3-海外换汇分发 4-宝付收款账户',
  `DATA_TYPE` tinyint(2) NOT NULL COMMENT '名单类型：1-可通过名单，2-不可通过名单',
  `TRADE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '交易类型：1-充值，2-付款',
  `DATA_LATITUDE` tinyint(2) NOT NULL COMMENT '名单纬度：1-证件号码，2-姓名，3-商户号，4-手机号码，5-客户端IP',
  `DATA_VALUE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '纬度值',
  `VOUCHER_FLAG` tinyint(2) NULL DEFAULT 0 COMMENT '交易凭证材料：0-未知，1-提供，2-不提供',
  `STATE` tinyint(2) NOT NULL COMMENT '状态：-1-删除，1-启用，2-失效',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `EXPIRE_AT` timestamp NULL DEFAULT NULL COMMENT '过期日期',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `UDX_USER_DATA`(`USER_NO`, `DATA_TYPE`, `DATA_LATITUDE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 156 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '名单记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_SYS_NOTICE
-- ----------------------------
DROP TABLE IF EXISTS `T_SYS_NOTICE`;
CREATE TABLE `T_SYS_NOTICE`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `NOTICE_ID` bigint(19) NOT NULL COMMENT '公告编号',
  `TITLE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '标题',
  `TITLE_EN` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标题（英文版）',
  `CONTENT` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '公告内容',
  `CONTENT_EN` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '公告内容（英文版）',
  `BEGIN_TIME` timestamp NOT NULL COMMENT '开始时间',
  `END_TIME` timestamp NOT NULL COMMENT '结束时间',
  `STATE` tinyint(2) NOT NULL COMMENT '状态：-1-删除 0-失效 1-启用',
  `SYSTEM_NOTICE_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '通知系统类型：0-全部，1-gep，2-E贸汇',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
