-- Table structure for T_USER_ACCOUNT_DAILY_SUMMARY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ACCOUNT_DAILY_SUMMARY`;
CREATE TABLE `T_USER_ACCOUNT_DAILY_SUMMARY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `TRANS_DATE` date NOT NULL COMMENT '交易日期',
  `TRANSACTION_TYPE` int(11) NOT NULL COMMENT '交易类型:见数据字典',
  `PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '产品大类',
  `SUB_PRODUCT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '资金渠道细类',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `AMT_DIRECTION` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收支方向 decre#支出 incre#收入',
  `REBACK_FLAG` tinyint(2) NOT NULL COMMENT '冲正标识：1-冲正 0-非冲正',
  `AMOUNT` decimal(19, 2) NOT NULL COMMENT '订单金额',
  `TRANS_COUNT` bigint(11) NOT NULL COMMENT '笔数',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_USER_FEE_DAILY_SUMMARY`(`USER_NO`, `TRANS_DATE`, `TRANSACTION_TYPE`, `PRODUCT_TYPE`, `SUB_PRODUCT_TYPE`, `CCY`, `AMT_DIRECTION`, `REBACK_FLAG`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_TRANS_DATE`(`TRANS_DATE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 77239 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收支明细日汇总' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_ACCOUNT_TRANSFER_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ACCOUNT_TRANSFER_CONFIG`;
CREATE TABLE `T_USER_ACCOUNT_TRANSFER_CONFIG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `PAYEE_USER_NO` bigint(19) NOT NULL COMMENT '收款用户号',
  `TRADE_AUDIT` tinyint(2) NOT NULL DEFAULT 1 COMMENT '交易是否审核 1-是 2-否',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态 1-启用 2-禁用',
  `TRADE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '交易类型 1-普通转账 2-定时转账，4-B2B转账（转给B2B账户）',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `TRANSFER_RELATION` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '转账详情描述',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_PAYEE_USER_NO_1`(`USER_NO`, `PAYEE_USER_NO`, `TRADE_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_PAYEE_USER_NO`(`PAYEE_USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 365 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户账户转账配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_ACCOUNT_TRANSFER_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ACCOUNT_TRANSFER_ORDER`;
CREATE TABLE `T_USER_ACCOUNT_TRANSFER_ORDER`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户请求单号',
  `PAYER_ACCOUNT` tinyint(2) NOT NULL COMMENT '付款账户 1-余额户(汇兑账户) 2-电商平台收款户(收款账户) 3-B2B收款户',
  `PAYER_ACCOUNT_NO` bigint(19) NULL DEFAULT NULL COMMENT '付款账户号',
  `PAYER_STORE_NO` bigint(19) NULL DEFAULT NULL COMMENT '付款店铺号',
  `PAYER_AMT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `PAYER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYER_FEE` decimal(19, 2) NOT NULL COMMENT '付款手续费',
  `PAYER_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款手续费币种',
  `PAYEE_USER_NO` bigint(19) NOT NULL COMMENT '收款用户号',
  `PAYEE_ACCOUNT` tinyint(2) NOT NULL COMMENT '收款账户 1-余额户(汇兑账户) 2-电商平台收款户(收款账户) 3-B2B收款户',
  `PAYEE_ACCOUNT_NO` bigint(19) NULL DEFAULT NULL COMMENT '收款账户号',
  `PAYEE_BANK_ACCOUNT_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行账户号',
  `PAYEE_AMT` decimal(19, 2) NOT NULL COMMENT '收款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款币种',
  `PAYER_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态 1-待处理 2-处理中 3-成功 4-失败',
  `TRADE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '交易类型 1-普通转账 2-定时转账,3-店铺余额资金归集',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '交易完成时间',
  `CALL_BACK_URL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '回调地址',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 3 COMMENT '审核状态: 0-待审核 1-审核通过 2-审核失败 3-无需审核',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `AUDIT_ACCESSORIES` bigint(19) NULL DEFAULT NULL COMMENT '审核附件',
  `TAGS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易标签',
  `REVIEW_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '复核状态',
  `PRODUCT_ID` bigint(19) NULL DEFAULT NULL COMMENT '产品ID',
  `FIXED_MODEL` int(2) NULL DEFAULT NULL COMMENT '固定方向 1付款 2到账',
  `TRADE_SOURCE` tinyint(2) NULL DEFAULT 1 COMMENT '交易来源：1-用户前端，2-API请求，3-系统自动生成，4-收款账户平台提现，5-商户批量付款，6-微信小程序',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_PAYEE_USER_NO`(`PAYEE_USER_NO`) USING BTREE,
  INDEX `IDX_USER_REQ_NO`(`USER_REQ_NO`) USING BTREE,
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT_USER_NO`(`CREATE_AT`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1031 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户账户转账订单' ROW_FORMAT = Dynamic;

-- ----------------------------
