-- ----------------------------
-- Table structure for T_USER_AGREEMENT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_AGREEMENT`;
CREATE TABLE `T_USER_AGREEMENT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `SIGN_NO` bigint(20) NOT NULL COMMENT '签署流水号',
  `USER_NO` bigint(20) NOT NULL COMMENT '签署用户编号',
