-- ----------------------------
-- Table structure for T_USER_ALL_SUM
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ALL_SUM`;
CREATE TABLE `T_USER_ALL_SUM`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
