-- ----------------------------
-- Table structure for T_USER_AUTOMATIC_PAYMENT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_AUTOMATIC_PAYMENT`;
CREATE TABLE `T_USER_AUTOMATIC_PAYMENT`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `PAYMENT_TYPE` tinyint(2) NOT NULL COMMENT '出款类型，1-提现；2-付款',
  `PAYEE_ACC_ID` bigint(19) NOT NULL COMMENT '收款账号编号，对应用户银行卡中的记录编号',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '出款币种',
  `MIN_PAYMENT_AMT` decimal(19, 2) NOT NULL COMMENT '最小付款金额',
  `RETAINED_RATIO` decimal(19, 2) NOT NULL COMMENT '留存比率，按照百分比单位保存',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-正常，2-禁用',
  `PARTNER_NO` bigint(19) NULL DEFAULT NULL COMMENT '合作方编码，付款时此字段不能为空',
  `PAYMENT_REMARKS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `PAYMENT_DATE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款日期',
  `AUTO_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '自动生成付款订单类型：1-根据余额自动生成，2-根据收款明细生成',
  `TO_EMAIL_ADDRESS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '发送邮件地址',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_PAYMENT_CCY`(`USER_NO`, `PAYMENT_CCY`, `PAYMENT_TYPE`) USING BTREE COMMENT '唯一索引',
  INDEX `IDX_USER_PAYMENT_CCY`(`USER_NO`, `PAYMENT_CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '收款账户用户自动提现付款规则表' ROW_FORMAT = COMPACT;

-- ----------------------------
