) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户余额默认折算币种配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
