  `PAYMENT_FEE_CCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手续费币种',
  `FILE_NAME` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名称',
  `FILE_TYPE` tinyint(2) NOT NULL COMMENT '文件类型 1-GEP付款明细 2-批量付款CNY',
  `PAYMENT_AMOUNT` decimal(19, 3) NOT NULL COMMENT '付款金额',
  `PAYMENT_FEE_AMOUNT` decimal(19, 3) NOT NULL COMMENT '付款费用',
