  `USER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '用户类型',
  `CHANNEL_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '渠道类型：1收款账户渠道；2货币兑换渠道；3跨境收款渠道；4：分发渠道；5：清结算渠道',
  `CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '渠道编号',
  `SELL_CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '卖出渠道编号',
