  `RATE_TYPE` tinyint(2) NOT NULL COMMENT '汇率类型：1-官网汇率，2-优惠汇率',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `BIZ_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '业务类型：0-全局 1-兑换服务（汇率），2-结汇下发,3-电商收款，4-B2B收款，5-虚拟信用卡',
  `CCY_PAIR` varchar(31) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '货币对',
  `BUY_RATE_STRATEGY_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '客买汇率策略:0-固定渠道，1-择差，2-择优',
  `ASK_CHANNEL_ID` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'ASK客买渠道id',
  `SELL_RATE_STRATEGY_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '客卖汇率策略:0-固定渠道，1-择差，2-择优',
  `BID_CHANNEL_ID` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'BID客卖渠道id',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `QUOTE_MODE` tinyint(2) NULL DEFAULT NULL COMMENT '报价模式：0-全局，1-代理商，2-用户',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_TYPE`(`USER_NO`, `USER_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 267 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户渠道配置' ROW_FORMAT = Dynamic;

