  `REMAINING_FEE` decimal(19, 2) NOT NULL COMMENT '未收手续费',
  `FEE_STATUS` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手续费收取状态 init未收取 process处理中 partial部分收取 complete已收取 refund已退回',
  `FREE_QUOTA_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '占用免收额度币种',
