  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_EXCHENG_ID`(`EXCHANGE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2714 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '换汇手续费详情' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_EXCHANGE_PRE_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_EXCHANGE_PRE_ORDER`;
CREATE TABLE `T_USER_EXCHANGE_PRE_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `EXCHANGE_PRE_NO` bigint(19) UNSIGNED NOT NULL COMMENT '挂单单号',
  `USER_PRE_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商户唯一单号',
  `EXCHANGE_NO` bigint(19) NULL DEFAULT NULL COMMENT '换汇单号',
  `TRADE_DIRECTION` tinyint(2) NOT NULL COMMENT '交易方向：1-买入，2-卖出',
  `EXCHANGE_TYPE` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '换汇模式 1:余额兑换 2:额度兑换',
  `CLOSING_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易模式：TOD,TOM,SPOT',
  `SELL_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '卖出币种',
  `BUY_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '买入币种',
  `USER_BUY_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '申请买入金额',
  `USER_SELL_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '申请卖出金额',
  `USER_RATE` decimal(19, 10) NULL DEFAULT NULL COMMENT '挂单用户交易汇率',
  `SELL_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '成交卖出金额',
  `BUY_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '成交买入金额',
  `SYSTEM_RATE` decimal(19, 10) NULL DEFAULT NULL COMMENT '挂单系统交易汇率',
  `CURRENCY_PAIR` varchar(7) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种对',
  `RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '汇率编号',
  `AMOUNT_DIRECTION` tinyint(2) NULL DEFAULT NULL COMMENT '固定交易金额方向：1-买入，2-卖出',
  `DEADLINE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '挂单截止日期  yyyy-MM-dd',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '挂单状态 ineffect生效中、conclude已成交、cancel已取消、expire已失效、refuse已拒绝、error异常',
  `EXPIRE_REASON` varchar(254) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '失败原因 自动过期，手动取消，下单失败',
  `REMARK` varchar(254) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `TRADE_SOURCE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易来源   API:对外接口 WEB网页',
  `COMPLETE_DATE` timestamp NULL DEFAULT NULL COMMENT '完成时间',
  `PLAT_SOURCE` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '平台 GEP:GEP兑换  B2B:E贸汇',
  `OPERATOR_ID` bigint(19) NULL DEFAULT NULL COMMENT '操作人id',
  `OPERATOR` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '操作人名称',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '修改人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_EXCHANGE_PRE_NO`(`EXCHANGE_PRE_NO`) USING BTREE,
  INDEX `IDX_CHANGE_NO`(`EXCHANGE_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4483 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户挂单订单表' ROW_FORMAT = Dynamic;

