  `CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `ACCOUNT_NO` bigint(19) NOT NULL COMMENT '账户号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_CCY`(`USER_NO`, `INDUSTRY_TYPE`, `CCY`) USING BTREE COMMENT '用户行业币种唯一索引',
  UNIQUE INDEX `UDX_ACCOUNT_NO`(`ACCOUNT_NO`) USING BTREE COMMENT '账户唯一索引'
) ENGINE = InnoDB AUTO_INCREMENT = 1159 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户行业币种账户关联关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_INFO_COLLECT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_INFO_COLLECT`;
CREATE TABLE `T_USER_INFO_COLLECT`  (
  `id` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_collect_id` bigint(11) NOT NULL COMMENT '留资客户id',
  `exhibition_id` bigint(11) NOT NULL COMMENT '展会id',
  `market_Id` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `user_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户名称',
  `phone_number` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '手机号',
  `company_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '公司名称',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建人',
  `CREATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_tel`(`phone_number`, `exhibition_id`) USING BTREE,
  UNIQUE INDEX `unique_user_collect_id`(`user_collect_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户信息收集表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_INNERTRANSFER_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_INNERTRANSFER_APPLY`;
CREATE TABLE `T_USER_INNERTRANSFER_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '唯一单号',
  `ORDER_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `ORDER_AMT_FEE` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '手续费',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种，一般是外币',
  `PAYEE_TYPE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人类型 0#收款账户 1#汇兑充值账户',
  `PAYER_TYPE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款人类型 0#收款账户 1#汇兑充值账户',
  `AUDIT_RISK_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '运营审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `AUDIT_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `UPLOAD_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '上传状态：0#未上传 2#已上传 ',
  `FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT '文件ID',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '运营审核备注',
  `RISK_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_RISK_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_RISK_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `UPLOAD_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件上传人',
  `UPLOAD_AT` timestamp NULL DEFAULT NULL COMMENT '文件上传时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间(入账完成时间)',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户内部转账申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_LOGIN_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_LOGIN_INFO`;
CREATE TABLE `T_USER_LOGIN_INFO`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `LOGIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录账户号 手机号或邮箱',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `LOGIN_TYPE` tinyint(2) NOT NULL COMMENT '登录账户类型：1-邮箱，2-手机号码',
  `LOGIN_STATE` tinyint(2) NOT NULL COMMENT '登录账户状态：1-正常',
  `LAST_LOGIN_AT` timestamp NOT NULL COMMENT '最后登录时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `USER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '用户类型: 1-个人 2-企业',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1584 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户登录信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_LOGIN_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_LOGIN_LOG`;
CREATE TABLE `T_USER_LOGIN_LOG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `LOGIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录账户号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `LOGIN_TYPE` tinyint(2) NOT NULL COMMENT '登录账户类型：1-邮箱，2-手机号码',
  `LOGIN_STATE` tinyint(2) NOT NULL COMMENT '登录账户状态：0-冻结，1-正常，2-锁定，3-注销',
  `LOGIN_IP` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录IP',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注 登录失败时可把错误信息放入此字段',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `STATE` tinyint(2) NULL DEFAULT NULL COMMENT '登录状态：0-登录失败，1-登录成功',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9132 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户登录日志记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_LOGISTICS_PLATFORM
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_LOGISTICS_PLATFORM`;
CREATE TABLE `T_USER_LOGISTICS_PLATFORM`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户编号',
  `LOGISTICS_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物流公司名称',
  `WEB_URL` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网址',
  `VOUCHER_FILE_ID` bigint(19) NULL DEFAULT NULL COMMENT '凭证文件ID',
  `STATUS` tinyint(3) NOT NULL COMMENT '状态，0-启用，1-禁用',
