  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '凭证审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '凭证审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RISK_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户物流平台记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_MANUAL_RATE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_MANUAL_RATE`;
CREATE TABLE `T_USER_MANUAL_RATE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `QUOTE_TARGET_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '报价对象类型：USER用户 GROUP用户组 AGENT代理商',
  `QUOTE_TARGET_VAL` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '报价对象值',
  `BUSINESS_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '业务类型',
  `CCY_PAIR` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种对',
  `SELL_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '客户卖出币种',
  `BUY_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '客户买入币种',
  `TRADE_SIDE` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易方向：BID ASK',
  `OFFICIAL_RATE` decimal(18, 8) NOT NULL COMMENT '官牌价/参考价',
  `MANUAL_BID_RATE` decimal(18, 8) NULL DEFAULT NULL COMMENT '人工买入BID报价',
  `MANUAL_ASK_RATE` decimal(18, 8) NULL DEFAULT NULL COMMENT '人工卖出ASK报价',
  `SETTLEMENT_TYPE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交割期限：TOD/TOM/SPOT',
  `VALID_FROM` varchar(24) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '有效期开始时间',
  `VALID_TO` varchar(24) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '有效期结束时间',
  `TRADE_QUOTA` decimal(18, 2) NOT NULL COMMENT '交易额度',
  `AVAIL_QUOTA` decimal(18, 2) NOT NULL COMMENT '可用额度',
  `QUOTA_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '额度币种 默认以卖出币种',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '状态：init待生效 effect生效中 cancel取消 expire过期',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CURRENCY`(`QUOTE_TARGET_VAL`, `SELL_CCY`, `BUY_CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外汇报价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_MINIMUM_FEE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_MINIMUM_FEE_CONFIG`;
CREATE TABLE `T_USER_MINIMUM_FEE_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(19) NULL DEFAULT NULL COMMENT '记录编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `PRODUCT_ID` bigint(19) NULL DEFAULT NULL COMMENT '产品编号',
  `PLATFORM_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电商平台编码',
  `COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家编码',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `FEE_MODEL` tinyint(2) NULL DEFAULT 1 COMMENT '计费模式：1-商户交易金额，2-渠道入账计算-只有在存款产品才会填此',
  `FEE_RATE` decimal(19, 4) NOT NULL COMMENT '费率',
  `FIXED_FEE` decimal(19, 2) NOT NULL COMMENT '固定费用',
  `MIN_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '最低费用',
  `MAX_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '最高费用',
  `BEGIN_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '起始值',
  `END_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '结束值',
  `FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费币种',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：-1-已删除 1-待审核 2-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_USER_PRODUCT_ID`(`USER_NO`, `PRODUCT_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户产品费率最低配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_NAVIGATION_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_NAVIGATION_CONFIG`;
CREATE TABLE `T_USER_NAVIGATION_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `SYSTEM` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '系统：GEP、B2B、ALL',
  `BIZ_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务类型',
  `BIZ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务编号',
  `SORT_NUMBER` int(3) NOT NULL COMMENT '排序编号',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '状态：NORMAL，INVALID',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户系统导航配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_NOTICE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_NOTICE`;
CREATE TABLE `T_USER_NOTICE`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
