  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `UDX_USER_NO_NOTICE_ID`(`USER_NO`, `NOTICE_ID`) USING BTREE COMMENT '用户编号公告编号联合唯一索引',
  INDEX `idx_user_NOTICE_ID`(`NOTICE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 686 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_NOTICE_MARK
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_NOTICE_MARK`;
CREATE TABLE `T_USER_NOTICE_MARK`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
