  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1628 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户公告标记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_OCCUPY_QUOTA
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_OCCUPY_QUOTA`;
CREATE TABLE `T_USER_OCCUPY_QUOTA`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
