-- ----------------------------
-- Table structure for T_USER_ONLN
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ONLN`;
CREATE TABLE `T_USER_ONLN`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `LOGIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录账户号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `SESN_ID` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'sessionid',
  `LOGIN_IP` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '登录IP',
  `LOGIN_SRVR_SDSC` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户所在服务器标识',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户在线表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_OPERATE_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_OPERATE_LOG`;
CREATE TABLE `T_USER_OPERATE_LOG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
