-- ----------------------------
-- Table structure for T_USER_ORDER_PICK
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ORDER_PICK`;
CREATE TABLE `T_USER_ORDER_PICK`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `BIZ_ID` bigint(19) NOT NULL COMMENT '订单号',
  `BIZ_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务类型',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `PICK_AMT` decimal(19, 2) NOT NULL COMMENT '匹配金额',
  `PICK_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '匹配币种',
  `PICK_STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '匹配状态：INIT/PASS/REJECT',
  `PICK_SUCCESS_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '凑单成功金额',
  `REFUND_STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退还状态：INIT/PASS/REJECT',
  `PICK_COMPLETE_AT` datetime NULL DEFAULT NULL COMMENT '匹配完成时间',
  `PICK_TIME` bigint(10) NULL DEFAULT NULL COMMENT '匹配耗时',
  `REFUND_COMPLETE_AT` datetime NULL DEFAULT NULL COMMENT '退还完成时间',
  `REFUND_TIME` bigint(10) NULL DEFAULT NULL COMMENT '退还耗时',
  `CREATE_AT` datetime NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` datetime NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_BIZ_ID_TYPE`(`BIZ_ID`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7999 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户订单凑单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_ORDER_QUOTA
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ORDER_QUOTA`;
CREATE TABLE `T_USER_ORDER_QUOTA`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
