-- ----------------------------
-- Table structure for T_USER_ORDER_QUOTA_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_ORDER_QUOTA_DETAIL`;
CREATE TABLE `T_USER_ORDER_QUOTA_DETAIL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '出入金订单编号',
