  `ORG_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '组织机构代码',
  `AREA_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '住所/经营场所代码',
  `INDUSTRY_ID` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '行业属性代码',
  `ECONOMY_ID` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '经济类型代码',
  `IS_TAXFREE` tinyint(1) NOT NULL COMMENT '是否特殊经济区内企业,0-是，1-否',
  `TAXFREE_CODE` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '特殊经济区内企业类型代码,如果为特殊经济区代码为必填',
  `ORG_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '企业地址',
  `POST_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '邮编',
  `LINKMAN` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '联系人',
  `LINKMAN_TEL` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '联系人电话',
  `BUSINESS_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '业务类型: 1-收款账户，2-GEP兑换服务',
  `STATUS` tinyint(4) NOT NULL COMMENT '状态: 0-待备案，1-成功，2-失败，3-备案中',
  `WEBSITE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '网址',
  `PLATFORM_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '平台类型：1-境内平台，2-境外平台',
  `PLATFORM_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台名称',
  `GOODS_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品类型',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `LICENSE` bigint(20) NULL DEFAULT NULL COMMENT '营业执照DFS编号',
  `LEGAL_ID_FRONT` bigint(20) NULL DEFAULT NULL COMMENT '法人身份证照片正面DFS编号',
  `LEGAL_ID_REVERSE` bigint(20) NULL DEFAULT NULL COMMENT '法人身份证照片反面DFS编号',
  `ORG_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '企业类型 1：A类企业，2：B类企业，3：C类企业, 4:非名录企业',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNX_MEMBER_CHANNEL_ORG_CODE`(`USER_NO`, `ORG_CODE`, `CHANNEL_ID`) USING BTREE,
  INDEX `IDX_USER_NO_ORG_CODE`(`USER_NO`, `ORG_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3124 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '企业备案信息表' ROW_FORMAT = Dynamic;

