-- ----------------------------
-- Table structure for T_USER_PAYEE_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYEE_ACCOUNT`;
CREATE TABLE `T_USER_PAYEE_ACCOUNT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '账户编号，内部唯一编号',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户编号，提供给商户使用的银行账户',
  `ROUTING_NUMBER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行路由编号，提供给商户使用的路由编号',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种信息',
  `WALLET_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'WYRE渠道方虚拟账户/QBC分行代码',
  `STATUS` tinyint(2) NOT NULL COMMENT '账户状态：0-冻结，1-正常，2-失效  3-注销',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `QUALIFIED_NO` bigint(20) NULL DEFAULT NULL COMMENT '资质编号',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `BANK_ACC_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户名称',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `ANOTHER_BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户编号，提供给商户使用的银行账户',
  `ANOTHER_ROUTING_NUMBER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行路由编号，提供给商户使用的路由编号',
  `ANOTHER_BANK_ACC_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户名称',
  `BANK_IBAN_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行IBAN NO',
  `BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BANK_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行所在国家代码',
  `BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行地址',
  `DK_IBAN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'DK IBAN',
  `TRADE_DATE` timestamp NULL DEFAULT NULL COMMENT '最后交易时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ACCOUNT_NO`(`ACCOUNT_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `idx_bank_acc_no`(`BANK_ACC_NO`) USING BTREE,
  INDEX `IDX_TRADE_DATE`(`TRADE_DATE`) USING BTREE COMMENT '交易时间索引',
  INDEX `IDX_CHANNEL_ID`(`CHANNEL_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6132 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收款账户信息表' ROW_FORMAT = Dynamic;

