DROP TABLE IF EXISTS `T_USER_PAYEE_ACCOUNT_APPLY`;
CREATE TABLE `T_USER_PAYEE_ACCOUNT_APPLY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `APPLY_ID` bigint(20) NOT NULL COMMENT '申请编号',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺编号',
  `QUALIFIED_NO` bigint(20) NOT NULL COMMENT '资质编号',
  `ACCOUNT_NO` bigint(20) NULL DEFAULT NULL COMMENT '账户编号，内部唯一编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `APPLY_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申请开户账号（用户邮箱或手机）',
  `APPLY_ACC_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申请账户名称',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种信息',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道编号',
  `BANK_ACCOUNT_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '账户类型：1-全球收款，2-本地收款',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：0-待处理，1-处理中，2-成功，3-失败，4-关闭 5-待审核 6-注销',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注 失败原因可写入到备注中',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ACCOUNT_ID` bigint(11) NULL DEFAULT NULL COMMENT '外部账户唯一流水号（线下）',
  `PLAT_COUNTRY` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '3位国家或地区编码',
  `CHANNEL_REQ_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道流水号',
  `BANK_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号',
  `CHANNEL_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '渠道账户唯一编号',
  `APPLY_ACC_TYPE` tinyint(3) NULL DEFAULT 1 COMMENT '申请账户类型，1-普通账户，2-归集账户',
  `INDUSTRY_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '01' COMMENT '行业类型',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_BANK_ACC_NO`(`BANK_ACC_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10171 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收款账户开户申请表' ROW_FORMAT = Dynamic;

