-- ----------------------------
-- Table structure for T_USER_PAYEE_ACCOUNT_FEE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYEE_ACCOUNT_FEE`;
CREATE TABLE `T_USER_PAYEE_ACCOUNT_FEE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT,
  `APPLY_ID` bigint(19) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `STORE_NO` bigint(19) NOT NULL COMMENT '店铺编号',
  `STORE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '店铺平台',
  `ORIGINAL_FEE_AMT` decimal(19, 2) NOT NULL COMMENT '原始手续费金额',
  `ORIGINAL_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '原始手续费币种',
  `REAL_FEE_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '实收手续费金额',
  `WAIT_FEE_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '待收取费用金额',
  `REAL_SUCCESS_AT` datetime NULL DEFAULT NULL COMMENT '收费成功时间',
  `BIZ_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '业务类型: 1-VA账户管理费 2-电商入账手续费',
  `STATUS` tinyint(2) NOT NULL COMMENT '收费结果：1-收取成功，2-收取失败，3-部分收取,4-正在处理中',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_APPLY_ID`(`APPLY_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`, `CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2774 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '收款账户VA账户管理费明细表' ROW_FORMAT = Dynamic;

