-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYEE_ACCOUNT_FEE_ATTR`;
CREATE TABLE `T_USER_PAYEE_ACCOUNT_FEE_ATTR`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `APPLY_ID` bigint(20) NOT NULL COMMENT 'VA申请表的申请ID',
  `FEE_APPLY_ID` bigint(20) NOT NULL COMMENT '唯一记录编号 用于T_USER_PAYEE_ACCOUNT_FEE的APPLY_ID',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型: 1-VA开户费 2-电商入账手续费 3-VA每月账户管理费',
  `BIZ_TYPE_VALUE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '根据 BIZ_TYPE来 YYYY-MM-DD （开户费-到日）或 YYYY-MM（管理费-到月）',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_VA_FEE`(`APPLY_ID`, `BIZ_TYPE`, `BIZ_TYPE_VALUE`) USING BTREE COMMENT '申请ID与业务与业务值唯一',
  UNIQUE INDEX `UDX_FEE_APPLY_ID`(`FEE_APPLY_ID`) USING BTREE COMMENT '计费单号'
) ENGINE = InnoDB AUTO_INCREMENT = 1733 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款账户VA管理费附属表' ROW_FORMAT = Dynamic;

