  `BANK_PAYEE_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行入账费用币种',
  `BANK_PAYEE_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行入账费用金额',
  `ENTRY_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '入账类型:0 同币种入账 1 错币种入账',
  `USER_PAYEE_FLOAT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户入账浮动前币种',
  `USER_PAYEE_FLOAT_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '商户入账浮动前金额',
  `USER_PAYEE_FLOAT_RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户入账浮动汇率ID',
  `USER_PAYEE_FLOAT_FLOAT_NUM` decimal(19, 3) NULL DEFAULT NULL COMMENT '商户入账浮动加点数-百分比',
  `USER_PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户入账币种',
  `USER_PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '用户入账金额',
  `PAYEE_SUCCESS_DATE` timestamp NULL DEFAULT NULL COMMENT '用户入账完成时间',
  `REMIT_ACC_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款人名称',
  `REMIT_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款人帐号',
  `REMIT_COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款人国家',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `STATUS` tinyint(2) NOT NULL COMMENT '入账状态：0-待确认 1-未入账，2-已入账,3-入账中，4-入账失败，5-交易可疑，6-交易异常,7-待补充材料，8-入账复核中  13-待补充店铺资料',
  `TRADE_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易日期，由渠道传入',
  `PAYEE_TRADE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款交易单号，此交易单号由渠道返回，加渠道编号唯一',
  `AUDITOR_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDITOR_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `AUDITOR_STATUS` tinyint(2) NOT NULL COMMENT '审核状态：0-无需审核，1-待审核，2-审核成功，3-审核失败 4-风控处理中 5-待补充店铺资料',
  `REMIT_REFERENCE` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款参考信息',
  `CHANNEL_DETAILS_ID` bigint(19) NOT NULL COMMENT '渠道明细编号',
  `FEE_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '计费模式：1-商户交易金额(按币种收费模式)，2-渠道入账计算-只有在存款产品才会填此,此种模式无法计费，需要业务端自己计算(银行实际入账模式)',
  `VOUCHER_FILE_ID` bigint(19) NULL DEFAULT NULL COMMENT '凭证文件编号',
  `VOUCHER_UPLOAD_DATE` datetime NULL DEFAULT NULL COMMENT '凭证文件上传时间',
  `STORE_NO` bigint(19) NOT NULL DEFAULT 0 COMMENT '店铺编号',
  `PAYEE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '收款类型，1-平台收款，2-外部其他收款,3-B2B收款 4-服贸',
  `PAYMENT_ORDER_ID` bigint(19) NULL DEFAULT 0 COMMENT '付款单号',
  `ACCOUNT_NO` bigint(19) NULL DEFAULT NULL COMMENT '内部账户号',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '风控检查时间',
  `RISK_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `RESERVE_FIELD_ONE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段 1',
  `ACCESSORIES_ID` bigint(19) NULL DEFAULT NULL COMMENT '审核上传附件',
  `RISK_AUDIT_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `FEE_ID` bigint(19) NULL DEFAULT NULL COMMENT '计费规则费用ID',
  `PRODUCT_ID` bigint(19) NULL DEFAULT NULL COMMENT '产品编号',
  `CHANNEL_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '渠道入账状态：1-已入账，2-未入账,3-入账失败',
  `CHANNEL_INCOME_AT` timestamp NULL DEFAULT NULL COMMENT '渠道入账时间',
  `REMITTANCE_ADDRESS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款地址',
  `TAGS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易标签',
  `REMIT_BANK_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款银行名称',
  `PAYEE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人名称',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `RECONCILIATION_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对账单号',
  `TRUSTEESHIP_RECEIVER_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '店铺集中管理接收方',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  `BLOCK_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '屏蔽标识 0：不屏蔽 1；屏蔽',
  `SUPPLEMENTARY_MATERIAL_FLAG` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'N' COMMENT '是否有补充材料 Y:是 N:否',
  `VA_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '入账时VA状态 1-正常，3-注销',
  `MASTER_ACCOUNT_NO` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账主账号',
  `PAYMENT_RAIL` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款渠道',
  `EXT3` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 3) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` timestamp NULL DEFAULT NULL COMMENT '扩展字段8',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_DETAILS_ID`(`DETAILS_ID`) USING BTREE,
  UNIQUE INDEX `UDX_PAYEE_TRADE_ID`(`PAYEE_TRADE_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT_USER_NO`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_CHANNEL_DETAILS_ID`(`CHANNEL_DETAILS_ID`) USING BTREE,
  INDEX `IDX_PAYEE_SUCCESS_DATE`(`PAYEE_SUCCESS_DATE`) USING BTREE,
  INDEX `IDX_CHANNEL_INCOME_AT`(`CHANNEL_INCOME_AT`) USING BTREE,
  INDEX `IDX_RECEIVER_USER_NO`(`TRUSTEESHIP_RECEIVER_USER_NO`) USING BTREE,
  INDEX `IDX_AUDITOR_AT_USER`(`AUDITOR_AT`, `USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14545136 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收款明细表' ROW_FORMAT = Dynamic;

