DROP TABLE IF EXISTS `T_USER_PAYEE_USED_COUPON`;
CREATE TABLE `T_USER_PAYEE_USED_COUPON`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `DETAILS_ID` bigint(19) NOT NULL COMMENT '入账流水号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `USER_PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户入账币种',
