  `COUPON_DETAIL_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '优惠券编号',
  `COUPON_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '优惠券类型。DISCOUNT 折扣券，FULL_REDUCTION 满减券',
  `SPEND_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '满减券的门槛',
  `SAVE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '满减券减多少',
  `COUPON_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '优惠券币种',
  `DISCOUNT_RATE` decimal(19, 2) NULL DEFAULT NULL COMMENT '折扣券的比例',
  `MAX_DISCOUNT_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '最大折扣金额',
  `CCY_EX` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '优惠券与退款手续费币种不一致，换算后的币种 同手续费币种',
  `SPEND_AMOUNT_EX` decimal(19, 2) NULL DEFAULT NULL COMMENT '优惠券与退款手续费币种不一致，换算后的满减券门槛',
  `SAVE_AMOUNT_EX` decimal(19, 2) NULL DEFAULT NULL COMMENT '优惠券与退款手续费币种不一致，换算后的满减金额或者折扣券的最终折扣金额',
  `MAX_DISCOUNT_AMOUNT_EX` decimal(19, 2) NULL DEFAULT NULL COMMENT '优惠券与退款手续费币种不一致，换算后最大折扣金额',
  `EX_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '优惠券与退款手续费币种不一致，换算汇率',
  `COUPON_STATUS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '优惠券状态 USED:已使用  REFUND:已退回',
  `USED_AT` timestamp NULL DEFAULT NULL COMMENT '优惠券使用时间',
  `REFUND_AT` timestamp NULL DEFAULT NULL COMMENT '优惠券退回时间',
  `PAYEE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '收款类型，1-平台收款，2-外部其他收款,3-B2B收款 4-服贸',
  `STORE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电商平台',
  `REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_COUPON_DETAIL_NO`(`DETAILS_ID`, `COUPON_DETAIL_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_DETAILS_ID`(`DETAILS_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '入账优惠券使用记录表' ROW_FORMAT = Dynamic;

