  `CLEARING_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行代码',
  `BUSINESS_NO` bigint(19) NULL DEFAULT NULL COMMENT '业务编号',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
