  `PHONE_NUM` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人联系电话',
  `BRANCH_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行分行代码',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_ACCOUNT_RECORD_NO`(`ACCOUNT_RECORD_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43080 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

