-- ----------------------------
-- Table structure for T_USER_PAYMENT_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_APPLY`;
CREATE TABLE `T_USER_PAYMENT_APPLY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '付款订单号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `PARTNER_NO` bigint(20) NOT NULL COMMENT '供应商编号',
  `ORDER_STATE` tinyint(2) NOT NULL COMMENT '订单状态：-1-失效，0-待处理，1-处理中，2-付款成功，-2-付款失败',
  `PAYMENT_TYPE` tinyint(2) NOT NULL COMMENT '付款类型：1-供应商付款',
  `STATE` tinyint(2) NOT NULL COMMENT '审核状态：0-待审核，1-审核成功，-1-审核失败，2-无需审核',
  `ORDER_AMT` decimal(19, 2) NOT NULL COMMENT '订单总金额',
  `PAYMENT_AMT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYMENT_FEE_AMT` decimal(19, 2) NOT NULL COMMENT '付款手续费',
  `DEST_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标币种',
  `TRADE_REAL_MATERIAL_FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT '贸易真实材料文件编号',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '订单完成时间',
  `REVIEW_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `REVIEW_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `REVIEW_REMARK` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `FEE_BEAR_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费承担方式：1-SHARE，2-OUR',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
