-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_CONFIG`;
CREATE TABLE `T_USER_PAYMENT_CONFIG`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '到账国家',
  `CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '到账币种',
  `PAYMENT_MODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款模式：SWIFT:国际汇款  LOCAL：本地汇款',
