  `SIGNLE_MAX_QUOTA` decimal(19, 2) NULL DEFAULT NULL COMMENT '单笔最大限额',
  `STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '状态：0-启用，1-禁用',
  `PAYER_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款人名称',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ACC_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '账户类型 1-对公，2-对私',
  `GLOBAL_FLAG` tinyint(2) NULL DEFAULT 0 COMMENT '是否是全局，0-否，1-是',
  `PAYMENT_DESC_CN` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方式中文描述',
  `PAYMENT_DESC_EN` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方式英文描述',
  `PAYMENT_DETAILS_DESC_CN` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方式详细中文说明',
  `PAYMENT_DETAILS_DESC_EN` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方式详细英文说明',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '付款信息配置表' ROW_FORMAT = Dynamic;

