-- ----------------------------
-- Table structure for T_USER_PAYMENT_DECLARE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_DECLARE`;
CREATE TABLE `T_USER_PAYMENT_DECLARE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '付款订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `PAYMENT_TRADE_DATE` datetime NOT NULL COMMENT '付款交易时间',
  `SETTLE_CHANNEL` bigint(19) NOT NULL COMMENT '结汇渠道',
  `DECLARE_CHANNEL` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申报渠道：NUCC：网联，CUP:银联',
  `DECLARE_CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '申报渠道编号',
  `DECLARE_DATE` datetime NULL DEFAULT NULL COMMENT '申报时间',
  `DECLARE_SUCCESS_DATE` datetime NULL DEFAULT NULL COMMENT '申报完成时间',
  `DECLARE_STATUS` tinyint(3) NOT NULL COMMENT '申报状态：0、初始 1、处理中 2、发送支付机构成功、3、发送支付机构失败、4-已收到银联网联申请、5-订单信息已匹配、6-申报处理中、7-申报成功、8-申报失败，99-系统异常',
  `DECLARE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '申报金额',
  `DECLARE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申报币种',
  `PAY_MEMBER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '境内支付机构商户编号',
  `PAY_MEMBER_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '境内支付机构商户名称',
  `DECLARE_ORDER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报编号，由境内支付机构生成返回',
  `DECLARE_ORIGINAL_FILE_ID` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报原始文件编号',
  `DECLARE_CHANNEL_FILE_ID` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报渠道文件编号',
  `ERROR_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '错误编码',
  `ERROR_MSG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '错误描述',
  `CHANNEL_RECORD_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道记录编号，重发多次时会变更',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 184 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

