  `COUNTERPARTY_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手方',
  `COUNTERPARTY_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易对手方名称',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '收支明细表(生产数据)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PAYMENT_ENTRUST_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_ENTRUST_ORDER`;
CREATE TABLE `T_USER_PAYMENT_ENTRUST_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '挂单订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `OPERATOR_ID` bigint(19) NOT NULL COMMENT '操作员ID',
  `AGENT_NO` bigint(19) NULL DEFAULT NULL COMMENT '代理商编号',
  `PAYER_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '出款用户号',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款到账币种',
  `PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '收款到账金额',
  `TRADE_RATE` decimal(19, 6) NOT NULL COMMENT '交易汇率，交易和到账币种不一致时需先汇兑',
  `VIEW_RATE` decimal(19, 10) NOT NULL COMMENT '用户展示汇率,可能与交易汇率方向相反',
  `TRADE_RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易汇率ID',
  `PAYMENT_FEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费扣款类型：1-内扣，2-外口',
  `PAYMENT_FEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易手续费金额',
  `PAYMENT_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款手续费币种',
  `PAYMENT_FEE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '手续费汇率',
  `PAYMENT_TYPE` tinyint(2) NOT NULL COMMENT '付款类型:1-提现，2-付款，3-GEP境内结汇，4-收款账户用户提现，5-收款账户用户付款，6-收款账户结汇，7-GEP境内垫资结汇，8-B2B付款，9-b2b结汇',
  `PAYMENT_OUT_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '出款类型',
  `QUERY_ACC_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '查询账户类型',
  `WITHDRAWAL_TYPE` tinyint(2) NOT NULL COMMENT '到账方式:1-普通到账 2-快速到账',
  `FIXED_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '固定模式：1-固定付款金额，2-固定收款金额',
  `PAYMENT_MODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款模式：SWIFT:国际汇款  LOCAL：本地汇款',
  `OUT_ACCT_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '出款类型 1-基本户 4-未结算户',
  `COUPON_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '优惠券编号',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `PAYMENT_PURPOSE` tinyint(2) NOT NULL COMMENT '付款用途：12-供货商 13-物流服务 14-分销推广 15-广告宣传 16-技术服务 17-留学 18-其他',
  `PURPOSE_OTHER_REMARK` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款用途为其他时备注信息',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '行业类型 01=货物贸易 06=物流',
  `COUNTRY_CODE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家',
  `EXPIRE_AT` timestamp NOT NULL COMMENT '挂单截止时间',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-生效中 2-已成交 3-已取消 4-已失效 5-已失败',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `USER_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户备注',
  `FAIL_REASON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `ACCOUNT_RECORD_NO` bigint(19) NULL DEFAULT NULL COMMENT '银行账户记录编号',
  `POBO_RECORD_NO` bigint(19) NULL DEFAULT NULL COMMENT 'pobo付款人记录编号',
  `EXEC_ORDER_ID` bigint(19) NULL DEFAULT NULL COMMENT '成交订单号',
  `EXEC_PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成交付款币种',
  `EXEC_PAYMENT_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '成交付款金额',
  `EXEC_PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成交到账币种',
  `EXEC_PAYEE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '成交到账金额',
  `EXEC_TRADE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '成交汇率',
  `EXEC_TRADE_RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成交汇率ID',
  `EXEC_AT` timestamp NULL DEFAULT NULL COMMENT '成交时间',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE COMMENT '订单号唯一索引',
  INDEX `IDX_EXEC_ORDER_ID`(`EXEC_ORDER_ID`) USING BTREE COMMENT '成交订单号索引',
  INDEX `IDX_STATUS_EXPIRE_AT`(`STATUS`, `EXPIRE_AT`) USING BTREE COMMENT '状态+截止时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 147 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户付款挂单订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PAYMENT_FEE_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_FEE_DETAIL`;
CREATE TABLE `T_USER_PAYMENT_FEE_DETAIL`  (
