  `ADVANCE_FIXED_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '垫资固定部分手续费',
  `ADVANCE_FIXED_FEE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '垫资固定部分手续费币种',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `FOREIGN_FEE_RATE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '提现到非CNY费率部分手续费',
  `FOREIGN_FEE_RATE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现到非CNY费率部分手续费币种',
  `FOREIGN_FIXED_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '提现到非CNY固定部分手续费',
  `FOREIGN_FIXED_FEE_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现到非CNY固定部分手续费币种',
  `INTL_DIST_FEE_RATE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '国际分发费率部分手续费',
