  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21799 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户出款订单费用明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PAYMENT_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PAYMENT_ORDER`;
CREATE TABLE `T_USER_PAYMENT_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单唯一编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户请求单号',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款到账币种',
  `PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '收款到账金额',
  `PAYMENT_FEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费扣款类型：1-内扣，2-外口',
  `PAYMENT_FEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易手续费金额',
  `PAYMENT_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款手续费币种',
  `PAYMENT_FEE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '手续费汇率',
  `TRADE_RATE` decimal(19, 6) NOT NULL COMMENT '交易汇率，交易和到账币种不一致时需先汇兑',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-交易待处理，2-交易处理中，3-交易成功，4-交易失败，5-交易异常，6-出款失败 7-已取消 8-待补充材料',
  `PAYMENT_PURPOSE` tinyint(2) NOT NULL COMMENT '付款用途：12-供货商 13-物流服务 14-分销推广 15-广告宣传 16-技术服务 17-留学 18-其他',
  `PURPOSE_OTHER_REMARK` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款用途为其他时备注信息',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款附言',
  `PAYMENT_SUCCESS_DATE` timestamp NULL DEFAULT NULL COMMENT '付款完成时间',
  `COST_BORNE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用承担方式：SHA-非全额到账、OUR-全额到账、BEN-收款人承担',
  `PAYMENT_TYPE` tinyint(2) NOT NULL COMMENT '付款类型：1-提现，2-付款，3-GEP境内结汇，4-收款账户用户提现，5-收款账户用户付款，6-收款账户结汇，7-GEP境内垫资结汇，8-B2B付款，9-b2b结汇',
  `PAYMENT_MATERIAL_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '凭证文件名称',
  `PAYMENT_MATERIAL` bigint(19) NULL DEFAULT NULL COMMENT '付款材料文件ID，付款类型为2时必传',
  `FILE_BATCH_NO` bigint(19) NULL DEFAULT 0 COMMENT '文件批次号',
  `AUDIT_STATUS` tinyint(2) NOT NULL COMMENT '审核状态:0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `FIXED_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '固定模式：1-固定付款金额，2-固定收款金额',
  `TRADE_RATE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易汇率ID',
  `TRADE_SOURCE` tinyint(2) NULL DEFAULT 1 COMMENT '交易来源：1-用户前台提交，2-API提交',
  `TRADE_REQ_IP` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易请求IP地址',
  `REMITTANCE_BATCH_ID` bigint(19) NULL DEFAULT 0 COMMENT '汇款批次号',
  `SETTLE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '结汇状态：1-待处理，2-结汇成功',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息(对客备注)',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '风控检查时间',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `PAYMENT_MODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款模式：SWIFT:国际汇款  LOCAL：本地汇款',
  `ACCESSORIES_ID` bigint(19) NULL DEFAULT NULL COMMENT '审核上传附件',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '01' COMMENT '行业类型 01=货物贸易 06=物流',
  `OUT_ACCT_TYPE` tinyint(4) NULL DEFAULT NULL COMMENT '出款类型 1-基本户 4-未结算户',
  `USER_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户备注',
  `PICK_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '凑单类型：1-按照用户纬度，2-按照用户店铺纬度',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `RISK_AUDIT_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `FEE_ID` bigint(19) NULL DEFAULT NULL COMMENT '计费规则费用ID',
  `PRODUCT_ID` bigint(19) NULL DEFAULT NULL COMMENT '产品编号',
  `PAYER_USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '出款商户号',
  `GEP_RATE_ID` bigint(19) NULL DEFAULT NULL COMMENT '官方汇率id',
  `GEP_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT 'GEP汇率',
  `TAGS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易标签',
  `POBO_PAY` tinyint(2) NULL DEFAULT 0 COMMENT '是否POBO付款，0-否，1-是',
  `AGENT_RATE_ID` bigint(19) NULL DEFAULT NULL COMMENT '代理商汇率id',
  `AGENT_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '代理商汇率',
  `BATCH_PAYMENT_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '批量付款类型 1-批量付款人民币 2-批量付款外币',
  `REFUND_STATUS` tinyint(4) NULL DEFAULT NULL COMMENT '退款状态:1退款中，2退款成功，3退款失败',
  `FAIL_REASON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `CANCEL_REASON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '取消原因',
  `CANCEL_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '取消操作人',
  `CANCEL_AT` timestamp NULL DEFAULT NULL COMMENT '取消操作时间',
  `CANCEL_PLATFORM` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '取消操作平台',
  `REVIEW_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '复核状态',
  `WITHDRAWAL_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '提现手续费',
  `OVERSEAS_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '国际付款下发金额',
  `OVERSEAS_FEE_ID` bigint(19) NULL DEFAULT NULL COMMENT '国际付款手续费ID',
  `TRADE_MODE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易模式B2B、B2C、C2C、C2B',
  `SUPPLEMENTARY_MATERIAL_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '是否补充材料 0-是',
  `MATERIAL_WHITELIST_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '免材料白名单: 0-否  1-是',
  `EXEC_MODE` tinyint(4) NULL DEFAULT 1 COMMENT '执行方式：1-实时，2-挂单',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE COMMENT '订单号唯一索引',
  UNIQUE INDEX `UDX_USER_REQ_NO`(`USER_REQ_NO`, `USER_NO`) USING BTREE COMMENT '用户订单号+用户号唯一索引',
  INDEX `IDX_CREATE_AT_USER`(`CREATE_AT`, `USER_NO`) USING BTREE COMMENT '创建时间+用户号普通索引',
  INDEX `IDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE COMMENT '汇款批次号索引',
  INDEX `IDX_PAYMENT_SUCCESS_DATE`(`PAYMENT_SUCCESS_DATE`) USING BTREE COMMENT '交易完成时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 43417 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户付款订单' ROW_FORMAT = Dynamic;

