  `LEGAL_ID_NO` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '法人证件号码',
  `MANAGEMENT_ID_NO` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '董事证件号码',
  `ESTABLISH_DATE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成立日期 YYYY-MM-DD',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1166 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单付款人信息' ROW_FORMAT = Dynamic;

