  `AUDITOR_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `AUDITOR_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '审核状态：0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `REMAKRS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
