-- ----------------------------
-- Table structure for T_USER_PLATFORM_PAYMENT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PLATFORM_PAYMENT`;
CREATE TABLE `T_USER_PLATFORM_PAYMENT`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `CERTIFICATE_ID` bigint(19) NOT NULL COMMENT '证书编号',
  `USER_TRANS_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户交易请求订单号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '卖家编号',
  `PAYEE_USER_NO` bigint(19) NOT NULL COMMENT '收款用户号',
  `PAYEE_STORE_NO` bigint(19) NOT NULL COMMENT '收款店铺编号',
  `PAYEE_BANK_ACCOUNT_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款银行帐号',
  `SOURCE_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '出款币种',
  `TARGET_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款币种',
  `SOURCE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '出款金额',
  `TARGET_AMOUNT` decimal(19, 2) NOT NULL COMMENT '收款金额',
  `RATE` decimal(19, 6) NOT NULL COMMENT '汇率',
  `RATE_ID` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇率ID',
  `STATUS` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态：Pending:处理中，Pass:交易成功,Rejected:交易失败',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '订单完成时间',
  `NOTIFY_INCOME` tinyint(2) NOT NULL COMMENT '通知入账状态：1-未通知，2-已通知',
  `ERROR_CODE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易失败的错误编码',
  `ERROR_MSG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易失败的错误信息',
  `NOTE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易备注',
  `SPLIT_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'GOODS' COMMENT '分账类型',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_TRANS_USER`(`USER_TRANS_ID`, `USER_NO`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CREATE_SELLER`(`CREATE_AT`, `SELLER_ID`) USING BTREE,
  INDEX `IDX_CREATE_USER`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 217 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台卖家分账表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PLATFORM_PAYMENT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PLATFORM_PAYMENT_DETAIL`;
CREATE TABLE `T_USER_PLATFORM_PAYMENT_DETAIL`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '订单编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户编号',
  `ACCOUNT_NO` bigint(20) NOT NULL COMMENT '提现账户号',
  `STORE_NO` bigint(20) NOT NULL COMMENT '店铺编号',
  `PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款币种',
  `PAYMENT_AMT` decimal(19, 2) NOT NULL COMMENT '付款金额',
  `ORIGINAL_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始手续费金额',
  `ORIGINAL_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始手续费币种',
  `DEDUCTION_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '抵扣外币手续费金额',
  `DEDUCTION_FEE_CNY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '抵扣人民币手续费金额',
  `REAL_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '实收手续费金额',
  `REAL_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实收手续费币种',
  `ADVANCE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '垫资手续费',
  `FEE_ID` bigint(19) NULL DEFAULT NULL COMMENT '手续费ID',
  `ADVANCE_FEE_ID` bigint(19) NULL DEFAULT NULL COMMENT '垫资手续费ID',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `WITHDRAWAL_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '提现手续费',
  `OVERSEAS_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '国际付款下发金额',
  `FEE_RATE` decimal(19, 2) NULL DEFAULT NULL COMMENT '手续费费率百分比',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81015 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '收款账户平台店铺付款明细' ROW_FORMAT = Dynamic;

