  `PAYEE_STORE_NO` bigint(19) NULL DEFAULT NULL COMMENT '收款店铺编号',
  `PAYEE_BANK_ACCOUNT_NO` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款银行帐号',
  `SOURCE_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出款币种',
  `TARGET_CURRENCY` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款币种',
  `SOURCE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '出款金额',
  `TARGET_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '收款金额',
  `ERROR_CODE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易失败的错误编码',
  `ERROR_MSG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易失败的错误信息',
  `NOTE` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易备注',
  `SPLIT_TYPE` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'GOODS' COMMENT '分账类型',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
