-- ----------------------------
-- Table structure for T_USER_PLATFORM_RELATION
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PLATFORM_RELATION`;
CREATE TABLE `T_USER_PLATFORM_RELATION`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
