-- ----------------------------
-- Table structure for T_USER_PLATFORM_RELATION_BIND
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PLATFORM_RELATION_BIND`;
CREATE TABLE `T_USER_PLATFORM_RELATION_BIND`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `PLAT_USER_NO` bigint(20) NOT NULL COMMENT '平台用户号(平台在GEP的用户号)',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台卖家编号',
  `SELLER_NAME` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台卖家名称',
  `SELLER_CERT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '在平台注册的卖家证件号码',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺编号',
  `BIND_STATUS` tinyint(2) NOT NULL COMMENT '绑定状态：-1 已删除 0-待绑定，1-绑定中，2-成功，3-失败',
  `RESULT_MSG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结果 一般是失败原因',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '关联流水表记录编号',
  `QUALIFIED_NO` bigint(20) NULL DEFAULT NULL COMMENT '资质编号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
