  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_RECORD_NO`(`RECORD_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 378 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户与平台卖家绑定关系表' ROW_FORMAT = Dynamic;

