-- ----------------------------
-- Table structure for T_USER_PLATFORM_RELATION_REQUEST
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PLATFORM_RELATION_REQUEST`;
CREATE TABLE `T_USER_PLATFORM_RELATION_REQUEST`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `PLAT_USER_NO` bigint(20) NOT NULL COMMENT '平台用户号(平台在GEP的用户号)',
  `PLAT_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台名称(OZON)',
  `PLAT_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台请求流水号',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台卖家编号',
  `SELLER_NAME` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台卖家名称',
  `ENTITY_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台卖家类型 Corporate、Individual',
  `SELLER_CERT_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '在平台注册的卖家证件号码',
  `COUNTRY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卖家的归属国家',
  `STORE_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卖家在平台中的店铺链接',
  `SETTLE_CURRENCY` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申请开通VA帐号的币种，多个币种时使用英文,分割',
  `REDIRECT_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'GEP的授权绑定回调地址',
  `BIND_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '绑定状态：-1 已删除 0-待绑定，1-绑定中，2-成功，3-失败',
  `RESULT_MSG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结果 一般是失败原因',
  `RESULT_MSG_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '消息CODE',
  `BACK_LINK_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '返回到平台页面链接',
  `ADDITIONAL1` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '附加字段1',
  `ADDITIONAL2` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '附加字段2',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `BUSINESS_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'Bind' COMMENT '业务类型: Bind、Kyc',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_PLAT_SELLER_ID`(`SELLER_ID`, `PLAT_USER_NO`) USING BTREE COMMENT '请求平台 卖家编号唯一',
  INDEX `IDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  INDEX `IDX_REDIRECT_URL`(`REDIRECT_URL`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 537 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户与平台卖家绑定关系请求流水表' ROW_FORMAT = Dynamic;

