  `AREA` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区域',
  `WHETHER_SAME_NAME` tinyint(2) NOT NULL DEFAULT 0 COMMENT '是否同名：1-同名 0-非同名',
  `FIRST_NAME` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人First name(名)',
