  `ESTABLISH_DATE` date NULL DEFAULT NULL COMMENT '成立日期 YYYY-MM-DD',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3573 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户POBO付款人信息表' ROW_FORMAT = Dynamic;

