  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_STORE`(`USER_NO`, `STORE_PLATFORM`, `CCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户预开户申请记录总数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PRE_FUND_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PRE_FUND_CONFIG`;
CREATE TABLE `T_USER_PRE_FUND_CONFIG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `OCCUPY_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '是否占用总额度 1-占用 2-不占用',
  `BIZ_TYPE` tinyint(3) NOT NULL COMMENT '业务类型：1-VCC',
  `AMT` decimal(19, 3) NULL DEFAULT NULL COMMENT '垫资金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '垫资币种',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态1启用 0暂停',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_USER_NO`(`USER_NO`, `BIZ_TYPE`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户垫资配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PRE_FUND_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PRE_FUND_ORDER`;
CREATE TABLE `T_USER_PRE_FUND_ORDER`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORDER_NO` bigint(20) NOT NULL COMMENT '订单编号',
  `BIZ_TYPE` tinyint(3) NOT NULL COMMENT '业务类型：1-VCC',
  `APPLY_AMT` decimal(19, 3) NOT NULL COMMENT '垫资金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '垫资币种',
  `RATE` decimal(19, 6) NULL DEFAULT 1.000000 COMMENT '垫资申请时汇率',
  `RECEIPT_1_DFS_ID` bigint(19) NOT NULL COMMENT 'DFS文件编号1',
  `RECEIPT_1_AMT` decimal(19, 3) NOT NULL COMMENT '文件1金额',
  `RECEIPT_1_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件1币种',
  `RECEIPT_2_DFS_ID` bigint(19) NOT NULL COMMENT 'DFS文件编号2',
  `RECEIPT_2_AMT` decimal(19, 3) NOT NULL COMMENT '文件2金额',
  `RECEIPT_2_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件2币种',
  `RECEIPT_3_DFS_ID` bigint(19) NULL DEFAULT NULL COMMENT 'DFS文件编号3(归还保证金凭证)',
  `RECEIPT_3_DFS_AT` timestamp NULL DEFAULT NULL COMMENT 'DFS文件3上传时间',
  `APPLY_REASON` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申请原因',
  `REBACK_AMT` decimal(19, 3) NOT NULL COMMENT '还款金额',
  `REBACK_FEE_AMT` decimal(19, 3) NOT NULL COMMENT '还款手续费',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_STATUS` tinyint(2) NOT NULL COMMENT '状态0待审核 1 审核通过 2 审核失败',
  `AUDIT_REMARK` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核原因',
  `REBACK_STATUS` tinyint(2) NOT NULL COMMENT '状态0待还款 1部分还款 2已还款',
  `REBACK_DEPOSIT_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '保证金归还状态0待还 1已还',
  `REBACK_DEPOSIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '保证金归还操作人',
  `REBACK_DEPOSIT_DATE` date NULL DEFAULT NULL COMMENT '保证金归还日期',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_ORDER_NO`(`ORDER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户垫资申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PRE_FUND_REBACK_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PRE_FUND_REBACK_ORDER`;
CREATE TABLE `T_USER_PRE_FUND_REBACK_ORDER`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `PRE_ORDER_NO` bigint(20) NOT NULL COMMENT '垫资订单编号',
  `ORDER_NO` bigint(20) NOT NULL COMMENT '订单编号',
  `AMT` decimal(19, 3) NOT NULL COMMENT '还款金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `FEE_AMT` decimal(19, 3) NOT NULL COMMENT '手续费',
  `USED_DAYS` int(4) NOT NULL,
  `STATUS` tinyint(2) NOT NULL COMMENT '状态0处理中 1 成功 2失败',
  `ERROR_MSG` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '失败原因',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_ORDER_NO`(`ORDER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_PRE_ORDER_NO`(`PRE_ORDER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户垫资还款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PURCHASE_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PURCHASE_ORDER`;
CREATE TABLE `T_USER_PURCHASE_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT 'Gep基金申购订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ACCOUNT_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '账户类型 7-B2B收款账户',
  `PURCHASE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '申购金额',
  `PURCHASE_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申购币种',
  `TRADE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易金额',
  `TRADE_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易币种',
  `FUND_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基金本身币种(可能与申购金额币种不一致)',
  `FUND_CODE` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基金代码',
  `FS_PURCHASE_ORDER_ID` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'FS侧业务申购订单号',
  `FS_BATCH_ID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'FS的批次号',
  `REMITTANCE_BATCH_ID` bigint(20) NULL DEFAULT 0 COMMENT '汇款批次号',
  `APPLY_TIME` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '申购订单完成时间',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '申购状态:1-申购中，2-申购成功，3-申购失败',
  `FILE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '文件处理状态:1-待生成25S文件 2-25S文件已生成送FS',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `DISTRIBUTOR_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商代码',
  `TRANSACTION_TIME` timestamp NULL DEFAULT NULL COMMENT '交易发生时间',
  `TRANSACTION_ACCOUNT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投资人基金交易账号',
  `EXTERNAL_ACCOUNT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CBP用户ID',
  `AVG_TRADE_AMOUNT_7DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户7天日均交易金额',
  `AVG_TRADE_AMOUNT_30DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户30天日均交易金额',
  `MAX_TRADE_AMOUNT_7DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '7天内发生的最大金融产品交易金额',
  `MAX_TRADE_AMOUNT_30DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '30天内发生的最大金额产品交易金额',
  `EXCHANGE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '交易汇率',
  `EXT1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE COMMENT 'Gep基金申购订单号',
  UNIQUE INDEX `IDX_FS_OUT_ORDER_ID`(`FS_PURCHASE_ORDER_ID`) USING BTREE COMMENT 'FS侧业务申购订单号',
  INDEX `IDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE COMMENT '汇款批次号索引',
  INDEX `IDX_FS_BATCH_ID`(`FS_BATCH_ID`) USING BTREE COMMENT 'FS的批次号',
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE COMMENT '创建时间索引',
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE COMMENT '完成时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 110 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基金申购订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_PWD
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_PWD`;
CREATE TABLE `T_USER_PWD`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `PWD` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '密码',
  `PWD_TYPE` tinyint(2) NOT NULL COMMENT '密码类型：1-登录密码，2-支付密码',
  `STATE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '密码状态：1-正常，2-锁定，3-失效',
  `ERROR_NUM` tinyint(3) NOT NULL DEFAULT 0 COMMENT '密码错误次数 默认为0',
  `LOCK_AT` timestamp NULL DEFAULT NULL COMMENT '密码错误次数锁定时间',
  `MODIFY_AT` timestamp NULL DEFAULT NULL COMMENT '最后一次修改密码时间',
  `VERSION` tinyint(2) NOT NULL DEFAULT 1 COMMENT '密码版本，默认版本1',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `BUSINESS_TYPE` tinyint(2) NULL DEFAULT 1 COMMENT '业务类型：1-收款账户 2-供应链金融',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11716 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户登录密码表' ROW_FORMAT = Dynamic;

