  `STAKEHOLDER_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '姓名',
  `STAKEHOLDER_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '证件号',
  `CERT_EXPIRY_DATE` date NULL DEFAULT NULL COMMENT '证件有效期',
  `BIRTH_DATE` date NULL DEFAULT NULL COMMENT '出生日期',
