  `ID_FRONT_DFS_ID` bigint(20) NULL DEFAULT NULL COMMENT '身份证或护照照片正面DFS编号',
  `ID_REVERSE_DFS_ID` bigint(20) NULL DEFAULT NULL COMMENT '身份证或护照照片反面DFS编号',
  `SHAREHOLDER_RATIO` decimal(19, 2) NULL DEFAULT NULL COMMENT '持股比率',
  `ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '住所地址',
  `STATE` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：0-删除，1-正常',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_INFO`(`USER_NO`, `USER_INFO_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 148 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户资质干系人信息表' ROW_FORMAT = Dynamic;

