-- ----------------------------
-- Table structure for T_USER_RATE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_RATE`;
CREATE TABLE `T_USER_RATE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键编号',
  `RECORD_ID` bigint(20) NOT NULL COMMENT '记录编号',
  `MEMBER_ID` bigint(20) NULL DEFAULT NULL COMMENT '商户编号',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `MEMBER_RATE` decimal(19, 3) NULL DEFAULT NULL COMMENT '商户浮动汇率百分比',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `STATUS` int(2) NOT NULL COMMENT '状态：1-启用，2-失效',
  `MEMBER_RATE_BP` bigint(10) NULL DEFAULT NULL COMMENT '商户浮动汇率bp',
  `BEGIN_DATE` timestamp NULL DEFAULT NULL COMMENT '开始时间，此汇率开始生效时间',
  `END_DATE` timestamp NULL DEFAULT NULL COMMENT '结束时间，此汇率结束生效时间',
  `RATE_SET_TYPE` int(1) NULL DEFAULT NULL COMMENT '浮动汇率设置方式：1-bp，2-百分比',
  `BUSINESS_TYPE` int(1) NULL DEFAULT NULL COMMENT '业务类型',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_RATE_BP
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_RATE_BP`;
CREATE TABLE `T_USER_RATE_BP`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录编号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户编号',
  `GROUP_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分组ID',
  `AGENT_NO` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商户号',
  `DATE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '日期类型：1-工作日，2-工作日非工作时间，3-节假日,4-非工作时间',
  `USER_TYPE` tinyint(2) NOT NULL COMMENT '3-跨境人民币(海外换汇分发) 4-VCC节假日BP，5-GEP节假日BP',
  `BIZ_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '业务类型：0-全局 1-兑换服务（汇率），2-结汇下发,3-电商收款，4-B2B收款，5-虚拟信用卡',
  `SOURCE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '原始币种',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `CLOSING_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交割模式',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：-1-已删除，1-正常，2-失效',
  `FLOAT_RATE_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '汇率浮动类型：1-BP，2-百分比',
  `SELL_RATE_VAL` decimal(19, 6) NOT NULL COMMENT '卖出汇率浮动值',
  `BUY_RATE_VAL` decimal(19, 6) NOT NULL COMMENT '买入汇率浮动值',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `START_TIME` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `END_TIME` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结束时间',
