  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新时间',
  `RECORD_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道汇率记录编号',
  `CHANNEL_ID` bigint(12) NULL DEFAULT NULL COMMENT '渠道编号',
  `BIZ_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '汇率查询使用业务类型：0-全局，5-vcc，7-gep汇兑，8-电商服贸，9-b2b',
  `TRADE_FLOAT_VAL` decimal(19, 4) NULL DEFAULT NULL COMMENT '交易员汇率浮动值',
  `SALE_FLOAT_VAL` decimal(19, 4) NULL DEFAULT NULL COMMENT '销售汇率浮动值',
  `AGENT_FLOAT_VAL` decimal(19, 4) NULL DEFAULT NULL COMMENT '代理商汇率浮动值',
  `TRADE_FLOAT_RATE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '交易员汇率浮动方式：1-BP，2-百分比',
  `SALE_FLOAT_RATE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '销售汇率浮动方式：1-BP，2-百分比',
  `AGENT_FLOAT_RATE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '代理商汇率浮动方式：1-BP，2-百分比',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_RATE_ID`(`RATE_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 468449 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户汇率记录表' ROW_FORMAT = Dynamic;

