-- ----------------------------
-- Table structure for T_USER_RECHARGE_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_RECHARGE_APPLY`;
CREATE TABLE `T_USER_RECHARGE_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '唯一单号',
  `ORDER_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
  `ORDER_AMT_FEE` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '手续费',
  `ORDER_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单币种，一般是外币',
  `ORDER_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '订单类型：1-内部资金划拨，2-Payoneer充值',
  `PAYEE_TYPE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人类型 0-收款账户 1-汇兑充值账户 2-Payoneer账户',
  `PAYEE_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款方账户',
  `PAYER_TYPE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '付款人类型 0-收款账户 1-汇兑充值账户  2-Payoneer账户',
  `PAYER_ACC_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款方账户',
  `AUDIT_RISK_STATUS` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `AUDIT_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '运营审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `UPLOAD_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '上传状态：0#未上传 2#已上传 ',
  `INCOME_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账状态：0-待入账 1-入账成功，2-入账失败 3-入账处理中 4-已撤销',
  `CLEAR_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算审核状态：0-待审核 1-审核暂停 2-审核成功 3-审核失败，4-无需审核',
  `ORDER_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单状态：0-处理中 1-处理完成，2-处理失败',
  `ORDER_SUCCESS_DATE` datetime NULL DEFAULT NULL COMMENT '订单完成时间',
  `CLEAR_PAYER_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算出款状态：0-无需出款，1-待出款 2-出款成功 ，3-出款处理中',
  `PAYER_TRANS_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款交易时间',
  `PAYER_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款交易编号',
  `PAYER_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易附言（备注）',
  `FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT '文件ID',
  `AUDIT_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '运营审核备注',
  `AUDIT_RISK_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `CLEAR_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_RISK_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_RISK_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `UPLOAD_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件上传人',
  `UPLOAD_AT` timestamp NULL DEFAULT NULL COMMENT '文件上传时间',
  `CLEAR_AUDIT_AT` datetime NULL DEFAULT NULL COMMENT '清算审核时间',
  `CLEAR_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算审核人',
  `CLEAR_AUDIT_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '清算审核备注信息',
  `VA_PAYER_NO` bigint(19) NULL DEFAULT NULL COMMENT 'VA付款单号',
  `BATCH_NO` bigint(19) NULL DEFAULT NULL COMMENT '批次号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `TAGS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易标签',
  `REVIEW_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '复核状态',
  `TRADE_SOURCE` tinyint(2) NULL DEFAULT 1 COMMENT '交易来源：1-用户前端，2-API请求，3-系统自动生成 ,6-微信小程序, 7-H5',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_ORDER_ID`(`ORDER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1088 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户充值申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_REDEMPTION_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_REDEMPTION_ORDER`;
CREATE TABLE `T_USER_REDEMPTION_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT 'Gep基金赎回订单号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ACCOUNT_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '账户类型',
  `REDEMPTION_AMOUNT` decimal(19, 2) NOT NULL COMMENT '赎回金额',
  `REDEMPTION_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '赎回币种',
  `TRADE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易金额',
  `TRADE_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易币种',
  `FUND_CURRENCY` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基金本身币种(可能与赎回金额币种不一致)',
  `FUND_CODE` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基金代码',
  `FS_REDEMPTION_ORDER_ID` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'FS侧业务赎回订单号',
  `FS_BATCH_ID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'FS的批次号',
  `APPLY_PRICE` decimal(10, 4) NOT NULL COMMENT '申请价格（下单时基金净值，通常保留4位小数）',
  `APPLY_QUANTITY` decimal(19, 4) NOT NULL COMMENT '申请赎回份额（支持大额赎回，保留4位小数）',
  `APPLY_TIME` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `COMPLETE_AT` timestamp NULL DEFAULT NULL COMMENT '赎回订单完成时间',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '赎回状态:1-赎回中，2-赎回成功，3-赎回失败 4-待生成25F文件 5-25F文件已生成送FS',
  `FILE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '文件处理状态 1-待生成25F文件 2-25F文件已生成送FS',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `EXT1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人',
  `INCOME_DETAILS_ID` bigint(19) NULL DEFAULT NULL COMMENT '赎回入账订单号',
  `EXCHANGE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '交易汇率',
  `DISTRIBUTOR_CODE` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分销商代码',
  `TRANSACTION_TIME` timestamp NULL DEFAULT NULL COMMENT '交易发生时间',
  `TRANSACTION_ACCOUNT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投资人基金交易账号',
  `EXTERNAL_ACCOUNT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CBP用户ID',
  `AVG_TRADE_AMOUNT_7DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户7天日均交易金额',
  `AVG_TRADE_AMOUNT_30DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '客户30天日均交易金额',
  `MAX_TRADE_AMOUNT_7DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '7天内发生的最大金融产品交易金额',
  `MAX_TRADE_AMOUNT_30DAYS` decimal(19, 2) NULL DEFAULT NULL COMMENT '30天内发生的最大金额产品交易金额',
  `ACCEPTED_DATE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受理日期',
  `CONFIRMED_DATE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认日期',
  `SETTLED_DATE` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算日期',
  `CONFIRMED_QUANTITY` decimal(19, 2) NULL DEFAULT NULL COMMENT '确认份额',
  `CONFIRMED_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '确认金额',
  `CONFIRMED_PRICE` decimal(19, 2) NULL DEFAULT NULL COMMENT '确认基金单位净值',
  `EXPECT_SETTLED_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '预计到账金额',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE COMMENT 'Gep基金赎回订单号唯一索引',
  UNIQUE INDEX `IDX_FS_OUT_ORDER_ID`(`FS_REDEMPTION_ORDER_ID`) USING BTREE COMMENT 'FS侧赎回订单号唯一索引',
  INDEX `IDX_FS_BATCH_ID`(`FS_BATCH_ID`) USING BTREE COMMENT 'FS的批次号索引',
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE COMMENT '创建时间索引',
  INDEX `IDX_COMPLETE_AT`(`COMPLETE_AT`) USING BTREE COMMENT '完成时间索引',
  INDEX `IDX_INCOME_DETAILS_ID`(`INCOME_DETAILS_ID`) USING BTREE COMMENT '赎回入账订单号索引'
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基金赎回订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
