  `NODE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '节点名称',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型：6-汇总明细 7-结汇明细',
  `DECISION_STATUS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '决策状态:PASS-通过、REJECT-拒绝、INITIAL-初始、EXCEPTION-异常、MANUAL-人工',
  `DECISION_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '决策时间',
  `DECISION_REMARKS` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '决策备注',
  `REMARKS` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `INPUT_PARAMS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '输入参数',
  `OUTPUT_PARAMS` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '输出参数',
  `RESULT_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '接口返回响应码',
  `RESULT_MSG` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '接口返回消息',
  `RISK_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对应风控备注',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对应客户备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_DECISION_RISK`(`ORDER_ID`, `ORDER_ITEM_ID`, `USER_NO`, `NODE_TYPE`, `BIZ_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39524 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'PAYFUL结汇明细决策结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SETTLE_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SETTLE_ORDER`;
CREATE TABLE `T_USER_SETTLE_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单唯一编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `SETTLE_CHANNEL` bigint(19) NOT NULL COMMENT '结汇渠道',
  `DETAILS_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '明细备案状态：1-待处理，2-处理成功 4-处理失败 5-处理中',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '01' COMMENT '行业类型：01=货物贸易 06=物流 07=软件服务 08=广告收入',
  `PICK_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '凑单类型：1-按照用户纬度，2-按照用户店铺纬度',
  `WORDS_FLAG` tinyint(4) NULL DEFAULT 0 COMMENT '是否检测到敏感词：1-是 0-否',
  `SETTLE_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '结汇状态：1-待打批处理，2-结汇成功 3-待凑单,4-凑单失败 5-结汇处理中',
  `SETTLE_DETAILS` tinyint(2) NULL DEFAULT NULL COMMENT '结汇明细类型：1-对公，2-对私 3-公私混合',
  `DECLARE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '申报证件类型',
  `DECLARE_ID_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报证件号码',
  `DECLARE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报姓名',
  `DECLARE_COUNT` bigint(19) NULL DEFAULT NULL COMMENT '申报明细笔数',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `RELATION_TYPE` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关系类型 1-供应商关系 2-受益人关系  3-董事 4-法人 5-本人 6-其他',
  `ACCESS_MODEL` tinyint(2) NULL DEFAULT NULL COMMENT '接入模式：0-普通模式，1-断直连模式',
  `DECLARE_CHANNEL` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报渠道：CUP:银联,NUCC：网联',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_ORDER_ID`(`ORDER_ID`) USING BTREE COMMENT '订单号唯一索引',
  INDEX `IDX_CREATE_AT_USER`(`CREATE_AT`, `USER_NO`) USING BTREE COMMENT '创建时间+用户号普通索引'
) ENGINE = InnoDB AUTO_INCREMENT = 22519 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户结汇订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SETTLE_ORDER_RISK
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SETTLE_ORDER_RISK`;
CREATE TABLE `T_USER_SETTLE_ORDER_RISK`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAIL_ID` bigint(19) NOT NULL COMMENT '交易明细编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `TRADE_TYPE` tinyint(2) NOT NULL COMMENT '业务或交易类型：24~33 结汇明细相关校验类型',
  `RISK_TYPE` tinyint(2) NOT NULL COMMENT '风控类型：7-结汇明细',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化 99-系统内部异常',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过风控时间',
  `RISK_REMARKS` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_RISK`(`DETAIL_ID`, `USER_NO`, `TRADE_TYPE`, `RISK_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_DETAIL_ID`(`DETAIL_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1080235 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP结汇明细风控信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SETTLE_STATUS_CHANGE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SETTLE_STATUS_CHANGE`;
CREATE TABLE `T_USER_SETTLE_STATUS_CHANGE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `SETTLE_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '变更后结算状态：-1待激活，0正常，1暂停，2关闭，3已注销',
  `CHANGE_AT` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '变更时间,YYYY-MM-DD格式',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `SEND_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '通知状态：1-已通知，0-未通知 2-不需要通知',
  `STATUS_CHANGE_REASON` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '状态变更原因',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CHANGE_AT`(`CHANGE_AT`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 955 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户结算状态变更记录表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for T_USER_STORE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE`;
CREATE TABLE `T_USER_STORE`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `STORE_NO` bigint(20) NOT NULL COMMENT '店铺编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `STORE_NAME` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺名称',
  `ALIAS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺备注名',
  `STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺所在平台',
  `STORE_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺链接',
  `STORE_STATE` tinyint(2) NOT NULL COMMENT '店铺状态 0-冻结 1-正常 2-失败 3-待审核',
  `TRADE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '店铺交易币种',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '材料审核备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `MANAGEMENT_CATEGORY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '经营范围',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卖家编号',
  `AWS_ACCESS_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '访问键编码，店铺认证类型=1时不能为空',
  `SECRET_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '秘钥，店铺认证类型=1时不能为空',
  `STORE_EXIST` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '是否有店铺, 是-Y，否-N',
  `SELLER_AUTH_TOKEN` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '店铺认证Token，店铺认证类型=2或3时不能为空',
  `SELLER_AUTH_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '店铺认证类型：1-secret Key方式;2-token方式',
  `EXCEPT_YEAR_SALES_AMOUNT` int(2) NULL DEFAULT NULL COMMENT '店铺的预计年收入 1：小于50万元 2：50-100万元  3：100-300万元  4：300-500万元  5：大于500万元',
  `THIRD_SELLER_AUTH_TOKEN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道方店铺认证Token，目前为SKYEE',
  `STORE_DFS_ID` bigint(20) NULL DEFAULT NULL COMMENT '店铺截图',
  `TRUSTEESHIP_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '店铺集管状态：0:未集管 1:集管处理中 2：正在被集中管理',
  `TRUSTEESHIP_RECEIVER_USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '店铺集中管理接收方用户编号',
  `PLATFORM_USER_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台用户名称',
  `STORE_BINDING_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺绑定日期',
  `PARENT_STORE_NO` bigint(20) NOT NULL DEFAULT 0 COMMENT '父节点店铺编号',
  `PAY_SERVICE_CODE_LIST` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付服务商编码集合,多个使用,分开',
  `PAY_SERVICE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支付服务商名称',
  `STORE_INFORMATION_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '店铺辅助资料状态 0待补充资料、1审核失败、2审核通过、3待审核,4-系统审核通过，-1：无需补充材料',
  `STORE_INFO_REQUISITE` tinyint(2) NULL DEFAULT 0 COMMENT '店铺材料是否必需的 0-非必须，1-必须',
  `STORE_AUTH_BIND_STATUS` tinyint(2) NULL DEFAULT NULL COMMENT '店铺在电商平台授权后的被动状态 2#无效 其他状态正常',
  `PLATFORM_NAME_LOCAL` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '本土平台自定义名称',
  `LAST_COMMIT_SUPPLEMENT_AT` timestamp NULL DEFAULT NULL COMMENT '最新提交补充材料时间',
  `RISK_REMARK` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_STORE_NO`(`STORE_NO`) USING BTREE,
  INDEX `IDX_LAST_COMMIT_SUPPLEMENT_AT`(`LAST_COMMIT_SUPPLEMENT_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_SELLER_ID_STORE_PLATFORM`(`SELLER_ID`, `STORE_PLATFORM`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9068 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_STORE_AUTH
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE_AUTH`;
CREATE TABLE `T_USER_STORE_AUTH`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `SELLER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '电商卖家店铺编号',
  `STORE_NO` bigint(20) NULL DEFAULT NULL COMMENT 'GEP店铺编号',
  `USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '用户号',
  `STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店铺所在平台',
  `AUTH_VERSION` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权接口版本',
  `AUTH_STORE_INFO` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权店铺信息JSON',
  `AUTH_STATE` tinyint(2) NOT NULL COMMENT '状态 0-失效 1-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_SELLER_ID`(`SELLER_ID`, `AUTH_VERSION`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 752 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺授权返回信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_STORE_CHANGE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE_CHANGE`;
CREATE TABLE `T_USER_STORE_CHANGE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `STORE_NO` bigint(19) NOT NULL COMMENT '店铺编号',
  `MODIFY_STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '变更店铺所在平台',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：0待审核；1待复核；2成功；3失败',
  `AUDIT_STATUS` tinyint(2) NOT NULL COMMENT '审核状态：0待审核、1初审通过，2审核失败；3审核成功',
  `FIRST_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '初审人员',
  `FIRST_AUDIT_AT` datetime NULL DEFAULT NULL COMMENT '初审时间',
  `REVIEW_AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '复审人',
  `REVIEW_AUDIT_AT` datetime NULL DEFAULT NULL COMMENT '复审时间',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `ORIGINAL_STORE_PLATFORM` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原平台',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户店铺平台变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_STORE_FILE_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE_FILE_CONFIG`;
CREATE TABLE `T_USER_STORE_FILE_CONFIG`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `STORE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型：1-店铺订单截图 2-店铺提现截图 3-平台绑定账号截图 4-店铺截图',
  `BIZ_COL_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务对应字段，兼容接口 后期可根据BIZ_TYPE传数组 ORDER_FILE_ID:店铺订单 STORE_WITHDRAWAL_FILE_ID:店铺提现  STORE_BIND_ACC_FILE_ID:店铺绑定账户 STORE_DFS_ID:店铺截图',
  `SAMPLE_IMG_PATH` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '示例图路径',
  `SAMPLE_OPT_DOC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作说明',
  `PARA_EMPTY_SHOW` tinyint(2) NOT NULL COMMENT '参数是否必填及页面显示 1-必填及显示 2-非必填可以不显示',
  `UPLOADS_JSON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '上传组件需要的信息JSON存储',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态：-1-删除 1-启用',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_PLATFORM_TYPE`(`STORE_PLATFORM`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 531 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '平台补充文件配置' ROW_FORMAT = Dynamic;

