-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE_FILE_CONFIG_TMP`;
CREATE TABLE `T_USER_STORE_FILE_CONFIG_TMP`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `STORE_PLATFORM` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '平台',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型：1-店铺订单截图 2-店铺提现截图 3-平台绑定账号截图 4-店铺截图',
  `BIZ_COL_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务对应字段，兼容接口 后期可根据BIZ_TYPE传数组 ORDER_FILE_ID:店铺订单 STORE_WITHDRAWAL_FILE_ID:店铺提现  STORE_BIND_ACC_FILE_ID:店铺绑定账户 STORE_DFS_ID:店铺截图',
