  `SAMPLE_OPT_DOC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作说明',
  `PARA_EMPTY_SHOW` tinyint(2) NOT NULL COMMENT '参数是否必填及页面显示 1-必填及显示 2-非必填可以不显示',
  `UPLOADS_JSON` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '上传组件需要的信息JSON存储',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '状态：-1-删除 1-启用',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_PLATFORM_TYPE`(`STORE_PLATFORM`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 220 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '平台补充文件配置' ROW_FORMAT = Dynamic;

