) ENGINE = InnoDB AUTO_INCREMENT = 1096 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户店铺补充材料表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for T_USER_STORE_TRANSFER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_STORE_TRANSFER`;
CREATE TABLE `T_USER_STORE_TRANSFER`  (
