  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `ID`(`ID`) USING BTREE,
  INDEX `IDX_STORE_NO`(`STORE_NO`) USING BTREE,
  INDEX `IDX_IN_USER_NO`(`IN_USER_NO`) USING BTREE,
  INDEX `IDX_OUT_USER_NO`(`OUR_USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 393 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户店铺迁移记录' ROW_FORMAT = Dynamic;

