  UNIQUE INDEX `UK_REQUEST_NO`(`REQUEST_NO`) USING BTREE,
  INDEX `STORE_NO`(`STORE_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '店铺解绑记录表' ROW_FORMAT = Dynamic;

