) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户预约额度表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SUB_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SUB_ACCOUNT`;
CREATE TABLE `T_USER_SUB_ACCOUNT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增编号',
  `APPLY_ID` bigint(20) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户号',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道ID',
  `BANK_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BANK_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户名称',
  `BANK_ACCOUNT_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账户号',
  `BANK_ACCOUNT_CCY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `BANK_ACCOUNT_TYPE` tinyint(3) NOT NULL DEFAULT 1 COMMENT '银行帐号类型：1-平台收款，2-外部其他收款 3-B2B收款',
  `BANK_SUB_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行分行代码',
  `ROUTING_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '路由编号、swift_code',
  `BANK_COUNTRY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行国家',
  `BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行地址',
  `PAYEE_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `MIDDLE_BANK_SWIFT_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中间行swiftcode',
  `MIDDLE_BANK_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中间行名称',
  `RESERVE_FIELD_ONE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `RESERVE_FIELD_TWO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `RESERVE_FIELD_THREE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `ACCOUNT_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '账户状态：1-启用，2-禁用',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建人',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建时间',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `DK_IBAN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'iban 欧洲 英国使用',
  `REMIT_REFERENCE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款附言',
  `TRADE_DATE` timestamp NULL DEFAULT NULL COMMENT '最后交易时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_APPLY_ID`(`APPLY_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_TRADE_DATE`(`TRADE_DATE`) USING BTREE COMMENT '交易时间索引',
  INDEX `IDX_CHANNEL_ID`(`CHANNEL_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1507 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户子账户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SUB_ACCOUNT_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SUB_ACCOUNT_APPLY`;
CREATE TABLE `T_USER_SUB_ACCOUNT_APPLY`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增',
  `APPLY_ID` bigint(19) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `USER_REQ_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户请求流水号',
  `STORE_NO` bigint(19) NULL DEFAULT NULL COMMENT '店铺编号',
  `ACCOUNT_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '收款账户类型：1-平台收款，2-外部其他收款 3-B2B收款',
  `COUNTRY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '国家',
  `CCY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支持的币种',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：1-处理中，2-申请中，3-成功，4-失败 -1-已删除[已注销] 5-待设置银行账号',
  `CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道编号',
  `SUB_ACCOUNT_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行子账号',
  `CHANNEL_REQ_ID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道请求编号',
  `REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `QUALIFIED_NO` bigint(19) NOT NULL DEFAULT 0 COMMENT '资质编号',
  `WEB_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 商户网址',
  `GOODS_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易商品大类',
  `GOODS_AREA` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易国家或地区',
  `GOODS_TRADE_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易类型',
  `GOODS_FILE_NO` bigint(19) NULL DEFAULT NULL COMMENT 'B2B收款账户 商品大类资质文件id',
  `GOODS_FILE_NOS` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品大类资质文件ids 多个文件',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `USER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  `TRADE_SOURCE` tinyint(2) NULL DEFAULT 1 COMMENT '来源：1-用户前台提交，2-API提交',
  `BANK_ACCOUNT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行子账号名称',
  `EXCEPT_YEAR_SALES_AMOUNT` tinyint(2) NULL DEFAULT NULL COMMENT '1:月交易量10万美元以下；2:月交易量10万（含）-30万美元；3:月交易量30万（含）-50万美元；4:月交易量50万（含）美元以上',
  `PLATFORM_TYPE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '经营平台：平台类（1688、中国制造网等 ），独立站、自建站',
  `BANK_CODE` tinyint(2) NULL DEFAULT NULL COMMENT '银行编码',
  `ACCOUNT_PAYEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款银行账户类型1-全球收款 2-本地收款',
  `GOODS_SUB_TYPE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易商品子类或其他',
  `INDUSTRY_TYPE` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型 06-物流 08-广告',
  `EXIST_PLATFORM` tinyint(3) NULL DEFAULT NULL COMMENT '是否已经关联平台：0-未关联，1-已关联',
  `CHANNEL_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '渠道账户唯一编号',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_WEB_URL`(`WEB_URL`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3324 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户子账户申请表' ROW_FORMAT = Dynamic;

