  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `QUALIFIED_NO` bigint(19) NOT NULL DEFAULT 0 COMMENT '资质编号',
  `WEB_URL` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 商户网址',
  `GOODS_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易商品大类',
  `GOODS_AREA` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易国家或地区',
  `GOODS_TRADE_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易类型',
  `GOODS_FILE_NO` bigint(19) NULL DEFAULT NULL COMMENT 'B2B收款账户 商品大类资质文件id',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '审核状态:-1-审核暂停，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `TRADE_SOURCE` tinyint(2) NULL DEFAULT 1 COMMENT '来源：1-用户前台提交，2-API提交',
  `BANK_ACCOUNT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行子账号名称',
  `EXCEPT_YEAR_SALES_AMOUNT` tinyint(2) NULL DEFAULT NULL COMMENT '1:月交易量10万美元以下；2:月交易量10万（含）-30万美元；3:月交易量30万（含）-50万美元；4:月交易量50万（含）美元以上',
  `PLATFORM_TYPE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '经营平台：平台类（1688、中国制造网等 ），独立站、自建站',
  `BANK_CODE` tinyint(2) NULL DEFAULT NULL COMMENT '银行编码',
  `ACCOUNT_PAYEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款银行账户类型1-全球收款 2-本地收款',
  `GOODS_SUB_TYPE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'B2B收款账户 贸易商品子类或其他',
  `INDUSTRY_TYPE` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行业类型 06-物流 08-广告',
  `EXIST_PLATFORM` tinyint(3) NULL DEFAULT NULL COMMENT '是否已经关联平台：0-未关联，1-已关联',
  `CHANNEL_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '渠道账户唯一编号',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_WEB_URL`(`WEB_URL`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1200 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户子账户申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SUB_ACCOUNT_CHANGE_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SUB_ACCOUNT_CHANGE_RECORD`;
CREATE TABLE `T_USER_SUB_ACCOUNT_CHANGE_RECORD`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `WORK_ORDER_NO` bigint(19) NOT NULL COMMENT '工单号',
  `APPLY_ID` bigint(19) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `CHANGE_TYPE` tinyint(2) NOT NULL COMMENT '变更类型: 1 首次变更 2 变更审核',
  `HAS_WEB_SITE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '有无网址: 0 无 1 有',
  `CHANGE_CONTENT` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '变更后内容',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `AUDIT_STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '审核状态:-1-审核驳回，0-无需审核，1-待审核，2-审核成功，3-审核失败',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `CUSTOMER_REMARKS` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '对客备注',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_WORK_ORDER_NO`(`WORK_ORDER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT_USER_NO`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_UPDATE_AT`(`UPDATE_AT`) USING BTREE,
  INDEX `IDX_APPLY_ID`(`APPLY_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2327 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '账户申请信息变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_SUB_ACCOUNT_copy1
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SUB_ACCOUNT_copy1`;
CREATE TABLE `T_USER_SUB_ACCOUNT_copy1`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增编号',
  `APPLY_ID` bigint(20) NOT NULL COMMENT '申请编号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户号',
  `CHANNEL_ID` bigint(20) NOT NULL COMMENT '渠道ID',
  `BANK_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行名称',
  `BANK_ACCOUNT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行账户名称',
  `BANK_ACCOUNT_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账户号',
  `BANK_ACCOUNT_CCY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `BANK_ACCOUNT_TYPE` tinyint(3) NOT NULL DEFAULT 1 COMMENT '银行帐号类型：1-平台收款，2-外部其他收款 3-B2B收款',
