-- ----------------------------
DROP TABLE IF EXISTS `T_USER_SUPPLEMENT_MATERIAL`;
CREATE TABLE `T_USER_SUPPLEMENT_MATERIAL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `BIZ_ID` bigint(19) NOT NULL COMMENT '业务单号',
  `BIZ_TYPE` tinyint(3) NOT NULL COMMENT '业务类型：1-收款，2-出款 8-入账退款收款人信息材料',
  `SRC_TYPE` tinyint(3) NOT NULL COMMENT '材料来源类型：1-风控上传，2-商户上传',
  `DFS_ID` bigint(19) NOT NULL COMMENT 'DFS文件编号',
  `FILE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `STATUS` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态：1-正常，2-失效',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
