  `RELATED_BIZ_IDS` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联的业务ID,支持多个',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `BIZ_ID_TYPE`(`BIZ_ID`, `BIZ_TYPE`, `SRC_TYPE`) USING BTREE COMMENT '业务ID类型索引'
) ENGINE = InnoDB AUTO_INCREMENT = 43955 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '商户业务补充材料表' ROW_FORMAT = Dynamic;

