-- ----------------------------
-- Table structure for T_USER_TRADE_DAILY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_TRADE_DAILY`;
CREATE TABLE `T_USER_TRADE_DAILY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `BIZ_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '业务类型 PLATFORM-电商 SERVICE-服贸 EXCHANGE汇兑 B2B-E贸汇',
  `USD_EXCHANGE_RATE` decimal(18, 8) NOT NULL COMMENT '换USD汇率',
  `CNH_EXCHANGE_RATE` decimal(18, 8) NOT NULL COMMENT '换CNH汇率',
  `ORI_PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT '入账金额',
  `ORI_PAYEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '入账币种',
  `USD_PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT 'USD入账金额',
  `CNH_PAYEE_AMOUNT` decimal(19, 2) NOT NULL COMMENT 'CNH入账金额',
  `ORI_PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '出款金额',
  `ORI_PAYMENT_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '出款币种',
  `USD_PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT 'USD出款金额',
  `CNH_PAYMENT_AMOUNT` decimal(19, 2) NOT NULL COMMENT 'CNH出款金额',
  `TRADE_DATE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易日期：yyyyMMdd',
  `REMARKS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `STORE_PLATFORM` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台站点',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_TRADE_AT_BIZ_TYPE`(`USER_NO`, `TRADE_DATE`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 154 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户交易记录日表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_TRADE_RISK
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_TRADE_RISK`;
CREATE TABLE `T_USER_TRADE_RISK`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `DETAIL_ID` bigint(19) NOT NULL COMMENT '交易明细编号或者用户号或者用户的客户号或者用户受益人的记录编号及其他开户主体的资质编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `TRADE_TYPE` tinyint(2) NOT NULL COMMENT '业务或交易类型：1-出款 2-收款 3-商户本体 4-商户-受益人 5-商户-法人 6-商户-董事 7-商户其他主体-本体 8-商户其他主体-受益人 9-商户其他主体-法人 10-商户其他主体-董事 11-商户代理人 12-商户其他主体代理人',
  `RISK_TYPE` tinyint(2) NOT NULL COMMENT '风控类型：1-白名单 2-道琼斯名单 3-黑名单 4-实名 5-证件有效期校验',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化 99-系统内部异常',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过风控时间',
  `RISK_REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CHILD_DETAIL_ID` bigint(19) NULL DEFAULT NULL COMMENT '同一个主体下的不同明细编号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_RISK`(`DETAIL_ID`, `USER_NO`, `TRADE_TYPE`, `RISK_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_DETAIL_ID`(`DETAIL_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 197988 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'GEP业务、交易风控信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_TRADE_SOURCE_REPORT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_TRADE_SOURCE_REPORT`;
CREATE TABLE `T_USER_TRADE_SOURCE_REPORT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
