-- ----------------------------
-- Table structure for T_USER_TRANSFER_FILE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_TRANSFER_FILE`;
CREATE TABLE `T_USER_TRANSFER_FILE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `FILE_BATCH_NO` bigint(19) NOT NULL COMMENT '文件批次号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `ORDER_COUNT` int(11) NOT NULL DEFAULT 0 COMMENT '订单笔数',
  `ORDER_SUM_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总金额',
  `FILE_DFS_ID` bigint(19) NOT NULL COMMENT 'DFS文件编号',
  `FILE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `DEDUCTION_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扣除手续费币种',
  `DEDUCTION_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '扣除手续费金额',
  `ORDER_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '订单人民币手续费金额',
  `ERROR_DFS_ID` bigint(19) NULL DEFAULT NULL COMMENT '错误的内容DFS编号',
  `FEE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '手续费汇率',
  `FEE_RATE_ID` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费汇率ID',
  `STATUS` tinyint(255) NULL DEFAULT NULL COMMENT '状态：0-待处理，1-处理中，2-处理成功，3-处理失败，4-处理异常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 286 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代付下发文件记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_TRANSFER_ORDER
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_TRANSFER_ORDER`;
CREATE TABLE `T_USER_TRANSFER_ORDER`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `TRANSFER_ID` bigint(19) NOT NULL COMMENT '下发唯一订单号',
  `TRANSFER_BATCH_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '下发批次号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户号',
  `USER_REQ_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户请求流水号',
  `CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道编号',
  `PAYEE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人名称',
  `PAYEE_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人账号',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号码',
  `PAYEE_ID_TYPE` tinyint(3) NULL DEFAULT NULL COMMENT '收款人证件类型：1-身份证，2-组织机构代码，3-护照',
  `BANK_PROVINCE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行省份',
  `BANK_CITY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行所在市',
  `BANK_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行名称',
  `BANK_BRANCH_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支行名称',
  `TRANSFER_AMT` decimal(19, 2) NOT NULL COMMENT '转账金额',
  `TRANSFER_CNY_FEE` decimal(19, 2) NOT NULL COMMENT '转账手续费人民币金额',
  `DEDUCTION_FEE` decimal(19, 2) NOT NULL COMMENT '扣除手续费金额',
  `DEDUCTION_FEE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '扣除手续费币种',
  `TRANSFER_REMARKS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '转账备注',
  `TRANSFER_SOURCE` tinyint(2) NOT NULL COMMENT '交易来源：1-用户前台提交，2-API提交',
  `TRANSFER_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '转账类型：1-收款账户，2-GEP转账,3-B2B结汇转账',
  `PAYEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人类型：1-对公，2-对私',
  `TRANSFER_STATE` tinyint(2) NOT NULL COMMENT '状态：1-交易待处理，2-交易处理中，3-交易成功，4-交易失败，5-交易异常',
  `COMPLETE_AT` datetime NULL DEFAULT NULL COMMENT '交易完成时间',
  `TRADE_REQ_IP` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易请求IP地址',
  `FEE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '手续费汇率',
  `FEE_RATE_ID` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手续费汇率ID编号',
  `PAYMENT_FEE_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费扣款类型：1-内扣，2-外扣',
  `REAL_TRANSFER_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '实际到账金额',
  `SETTLE_ORDER_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'CNH' COMMENT '结算币种',
  `SETTLE_MEMBER_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '结汇商户类型：1-宝付换汇，2-境外换汇，3-结汇垫资,4-独立商户号结汇',
  `CHANNEL_TRANSFER_ID` bigint(19) NULL DEFAULT NULL COMMENT '渠道转账订单编号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `RISK_STATUS` tinyint(2) NOT NULL DEFAULT 0 COMMENT '风控名单状态:1-通过名单 2-未通过名单 0-初始化',
  `RISK_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '风控检查时间',
  `RISK_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控备注',
  `CLEARING_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行代码',
  `INDUSTRY_TYPE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '01' COMMENT '行业类型：01=货物贸易 06=物流 07=服务贸易',
  `PLATFORM_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '平台名称',
  `RELATION_TYPE` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关系类型 关系类型 1-供应商关系 2-受益人关系  3-董事 4-法人 5-本人 6-其他',
  `APPLY_ID_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报人证件号',
  `APPLY_NAME` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申报人名称',
  `CHANNEL_RESP_NO` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回流水号',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_TRANSFER_ID`(`TRANSFER_ID`) USING BTREE,
  UNIQUE INDEX `UDX_USER_REQ_NO`(`USER_REQ_NO`, `USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_USER`(`CREATE_AT`, `USER_NO`) USING BTREE,
  INDEX `IDX_T_USER_TRANSFER_ORDER`(`TRANSFER_BATCH_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25085 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代付下发订单表' ROW_FORMAT = Dynamic;

