  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '用户号，用户登陆成功之后存入',
  `OPEN_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '微信平台openId',
  `BIND_STATE` tinyint(2) NOT NULL COMMENT '绑定状态：-1-已解绑，0-失效，1-已绑定,2-待绑定',
  `WEIXIN_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '微信帐号',
  `WEIXIN_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '微信名称',
  `NICKNAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '昵称',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `TOURIST_NO` bigint(20) NULL DEFAULT NULL COMMENT '游客编号',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_ADDITION
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_ADDITION`;
CREATE TABLE `T_USER_WITHDRAW_ADDITION`  (
