  `FREE_CASH_CARD_NO` bigint(20) NULL DEFAULT NULL COMMENT '额度免提卡号',
  `FREE_CASH_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '额度卡免提金额',
  `CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `RED_ENVELOPE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '红包使用金额',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1088 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_APPLY`;
CREATE TABLE `T_USER_WITHDRAW_APPLY`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现明细编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `REQUEST_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户请求流水号',
  `WITHDRAW_AMT` decimal(19, 2) NOT NULL COMMENT '提现金额',
  `WITHDRAW_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现币种',
  `WITHDRAW_FEE` decimal(19, 2) NOT NULL COMMENT '提现手续费',
  `REAL_WITHDRAW_FEE` decimal(19, 2) NOT NULL COMMENT '提现手续费',
  `DEST_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标币种',
  `RATE_CCY_PAIR` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `TRANSFER_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现汇率',
  `DEDUCT_AMT` decimal(19, 2) NOT NULL COMMENT '实际扣款金额',
  `WITHDRAW_FEE_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现费率',
  `CNY_WITHDRAW` decimal(19, 2) NULL DEFAULT NULL COMMENT '提现人民币金额',
  `CNY_WITHDRAW_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '应收人民币手续费',
  `REAL_CNY_WITHDRAW_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '实收人民币手续费',
  `DEDUCTIBLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '抵扣金额',
  `FC_DEDUCTIBLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '抵扣金额',
  `WITHDRAW_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '提现状态，0-待提现；1-提现处理中，2-提现成功，3-提现失败',
  `WITHDRAW_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '提现类型，1-余额提现；2-付款提现',
  `WITHDRAW_AT` timestamp NULL DEFAULT NULL COMMENT '提现完成时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `AUDITOR_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDITOR_AT` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `AUDITOR_STATE` tinyint(2) NULL DEFAULT 2 COMMENT '审核状态：-1：审核失败，0-待审核，1-审核成功，2-无需审核',
  `REMITTANCE_BATCH_ID` bigint(19) NULL DEFAULT 0 COMMENT '汇款批次号',
  `PAYMENT_REFERENCE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇款附言',
  `FEE_BEAR_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '手续费承担方式：1-SHARE，2-OUR',
  `PARTNER_NO` bigint(19) NULL DEFAULT NULL COMMENT '供应商编码',
  `VOUCHER_FILE_ID` bigint(19) NULL DEFAULT NULL COMMENT '交易凭证文件 ID',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UDX_WITHDRAW_ID`(`WITHDRAW_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_WITHDRAW_AT`(`WITHDRAW_AT`) USING BTREE,
  INDEX `IDX_REMITTANCE_BATCH_ID`(`REMITTANCE_BATCH_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1488 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

