  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1542 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_DISTRIBUTE
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_DISTRIBUTE`;
CREATE TABLE `T_USER_WITHDRAW_DISTRIBUTE`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '下发批次号',
  `WITHDRAW_BATCH_ID` bigint(20) NOT NULL COMMENT '汇款流水号',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现申请号',
  `ACCOUNT_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '提现账户',
  `BANK_NAME` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行名称',
  `BANK_CARD_HOLDER` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现银行卡持有人',
  `BANK_CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现银行卡帐号',
  `WITHDRAW_AMT` decimal(19, 2) NOT NULL COMMENT '提现金额',
  `WITHDRAW_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现币种',
  `WITHDRAW_FEE` decimal(19, 2) NOT NULL COMMENT '提现手续费',
  `DEST_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目标币种',
  `TRANSFER_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现汇率',
  `DEDUCT_AMT` decimal(19, 2) NOT NULL COMMENT '实际扣款金额，提现金额 + 提现手续费',
  `TRANSFER_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '归集状态，0-待转账；1-转账处理中，2-转账成功，3-转账失败',
  `WITHDRAW_STATE` tinyint(2) NULL DEFAULT NULL COMMENT '提现状态，0-待提现；1-提现处理中，2-提现成功，3-提现失败(宝付转账)',
  `SETTLE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '用户结算手续费',
  `WITHDRAW_AT` timestamp NULL DEFAULT NULL COMMENT '提现完成时间',
  `STATUS` tinyint(2) NOT NULL COMMENT '下发审核状态：0-待审核，1-审核通过，2-审核失败',
  `MEMBER_ID` bigint(19) NOT NULL COMMENT '下发商户号',
  `TERMINAL_ID` bigint(19) NOT NULL COMMENT '下发终端号',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息:填写审核失败原因',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 818 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户提现下发表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_FILE_UPLOAD
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_FILE_UPLOAD`;
CREATE TABLE `T_USER_WITHDRAW_FILE_UPLOAD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `FILE_BATCH_NO` bigint(20) NOT NULL DEFAULT 0 COMMENT '文件批次',
  `BATCH_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `FILE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件名称',
  `RECORD_COUNT` int(11) NOT NULL COMMENT '记录数',
  `SUCCESS_COUNT` int(11) NOT NULL COMMENT '成功数量',
  `FAIL_COUNT` int(11) NOT NULL COMMENT '失败数量',
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '状态，INIT:初始，TRUE:处理完成，FALSE：审核不通过，UPLOAD：已上传,PROCESSING：处理中,ERROR:文件数据有误,CANCEL:取消中',
  `DFS_FILE_ID` bigint(20) NOT NULL COMMENT 'DFS文件服务器ID编号',
  `FILE_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件类型:1-用户提现明细文件， 2-账户信息， 3-账户收入明细',
  `ORDER_TYPE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '0:服务贸易类型、1：货物贸易类型 、2：未知贸易类型',
  `ERROR_DFS_FILE_ID` bigint(11) NULL DEFAULT NULL COMMENT '错误明细文件DFS编号',
  `TOTAL_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '订单明细总金额',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CHANNEL_ID` bigint(20) NULL DEFAULT NULL COMMENT '渠道号',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4844 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户提现明细上传表' ROW_FORMAT = Dynamic;

-- ----------------------------
