  `WITHDRAW_AT` timestamp NULL DEFAULT NULL COMMENT '提现完成时间',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息:填写审核失败原因',
