  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '提现代付请求重发表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_SETTLE_ACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_SETTLE_ACCOUNT`;
CREATE TABLE `T_USER_WITHDRAW_SETTLE_ACCOUNT`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现明细编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `ACC_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '账户类型 1-对公，2-对私',
  `ACCOUNT_CCY` varchar(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账户币种',
  `FAMILY_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户姓（个人-GEP）',
  `ACCOUNT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户名',
  `CARD_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `BANK_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行名称',
  `BANK_BRANCH_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '支行名称',
  `CARD_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '银行卡类型',
  `BANK_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行编码',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户行国家',
  `SWIFT_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行代码SwiftCode',
  `ACCOUNT_DOCUMENT` bigint(20) NULL DEFAULT NULL COMMENT '收款账户证明文件（DFS编号）',
  `CITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '市',
  `PAYEE_BANK_ADDRESS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款银行地址',
  `PROVINCE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省',
  `PAYEE_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人地址',
  `BUSINESS_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '业务类型:1-银行卡, 2-收款方账号，3-付款方账号',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `PAYEE_ID_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '收款人类型1-身份证，2-组织机构代码',
  `PAYEE_ID_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人证件号',
  `PAYEE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收款人姓名',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1482 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_USER_WITHDRAW_SUM
-- ----------------------------
DROP TABLE IF EXISTS `T_USER_WITHDRAW_SUM`;
CREATE TABLE `T_USER_WITHDRAW_SUM`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `WITHDRAW_BATCH_ID` bigint(20) NOT NULL COMMENT '提现批次号',
  `MEMBER_ID` bigint(20) NOT NULL COMMENT '商户编号(目前是固定商户)',
  `SOURCE_ACC_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '转出账户号',
  `DEST_ACC_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标账户号',
  `WITHDRAW_AMT` decimal(19, 2) NOT NULL COMMENT '提现金额',
  `WITHDRAW_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现币种',
  `WITHDRAW_FEE` decimal(19, 2) NOT NULL COMMENT '提现手续费',
  `DEST_AMT` decimal(19, 2) NOT NULL COMMENT '目标金额',
  `DEST_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '目标币种',
  `WITHDRAW_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '提现汇率',
  `DEDUCT_AMT` decimal(19, 2) NOT NULL COMMENT '实际扣款金额，提现金额 + 提现手续费',
  `TRANSFER_STATE` tinyint(2) NOT NULL COMMENT '转账状态，0-待转账；1-转账处理中，2-转账成功，3-转账失败',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `CHANNEL_ID` bigint(19) NULL DEFAULT NULL COMMENT '海外渠道编号',
  `CHANNEL_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道成本',
  `EXCHANGE_GAIN_OR_LOSS` decimal(19, 2) NULL DEFAULT NULL COMMENT '汇兑损益',
  `TRANSFER_AT` timestamp NULL DEFAULT NULL COMMENT '转账完成时间',
  `CHANNEL_WITHDRAW_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道提现金额(外币)',
  `REAL_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '银行实际到账金额(外币)',
  `BANK_MIDDLE_COST` decimal(19, 2) NULL DEFAULT NULL COMMENT '中间行手续费(外币)',
  `REMITTANCE_BATCH_ID` bigint(20) NULL DEFAULT NULL COMMENT '汇款批次号',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_WITHDRAW_BATCH_ID`(`WITHDRAW_BATCH_ID`) USING BTREE,
  INDEX `IDX_MEMBER_ID`(`MEMBER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 633 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户提现汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
