) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户微信绑定关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_3DS_OTP
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_3DS_OTP`;
CREATE TABLE `T_VAS_3DS_OTP`  (
