-- ----------------------------
-- Table structure for T_VAS_AGREEMENT_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_AGREEMENT_APPLY`;
CREATE TABLE `T_VAS_AGREEMENT_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `APPLY_NO` bigint(19) NULL DEFAULT NULL COMMENT '申请编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `AGREEMENT_VERSION` tinyint(2) NULL DEFAULT NULL COMMENT '协议版本',
  `USER_SCENE_BATCH_NO` bigint(20) NOT NULL COMMENT '业务场景配置编号BATCH_NO',
  `RISK_SCENE_BATCH_NO` bigint(20) NULL DEFAULT NULL COMMENT '客户属性配置编号BATCH_NO',
  `RISK_ONE_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `RISK_ONE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核人',
  `RISK_ONE_AT` timestamp NULL DEFAULT NULL COMMENT '风控审核时间',
  `RISK_ONE_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `RISK_TWO_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控事中审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `RISK_TWO_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控事中审核人',
  `RISK_TWO_AT` timestamp NULL DEFAULT NULL COMMENT '风控事中审核时间',
  `RISK_TWO_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控事中审核备注',
  `FILE_ID` bigint(20) NULL DEFAULT NULL COMMENT '附件文件ID',
  `FILE_UPLOAD_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '上传状态：0#未上传 2#已上传 ',
  `UPLOAD_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件上传人',
  `UPLOAD_AT` timestamp NULL DEFAULT NULL COMMENT '文件上传时间',
  `STATUS` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '状态：0#待审核，1#审核中 2#审核通过 3#审核失败',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREAT_AT`(`CREATE_AT`) USING BTREE,
  INDEX `uniq_APPLY_NO`(`APPLY_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 213 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC协议申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_AUTHTRANS_FEENEED
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_AUTHTRANS_FEENEED`;
CREATE TABLE `T_VAS_AUTHTRANS_FEENEED`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `ORDER_ID` bigint(20) NULL DEFAULT 0 COMMENT '订单ID',
  `AUTHTRANS_ID` bigint(11) NOT NULL COMMENT '授权交易表id',
  `CARD_ID` bigint(11) NOT NULL DEFAULT 0 COMMENT '卡ID',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `PAY_USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '付费用户号',
  `LOCAL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开卡币种',
  `LOCAL_AMT` decimal(19, 3) NOT NULL DEFAULT 0.000 COMMENT '交易金额',
  `OCCUR_TIME` timestamp NOT NULL COMMENT '交易发生时间',
  `IS_FEE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '2' COMMENT '手续费收取标识 0：已收取  1:未收取；',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型：CTRIP  NIUM',
  `FEE_TYPE` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0授权处理费1交易退款处理费',
  `FEE` decimal(19, 3) NULL DEFAULT NULL COMMENT '手续费',
  `PAY_ACCOUNT_TYPE` tinyint(4) NULL DEFAULT 0 COMMENT '付款账户类型0基本 1未结算',
  `REAL_CCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实际扣费币种',
  `REAL_FEE` decimal(19, 3) NULL DEFAULT NULL COMMENT '实际扣费金额',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_RECORD_CHANNEL`(`RECORD_NO`, `CHANNEL_TYPE`, `FEE_TYPE`) USING BTREE,
  INDEX `IDX_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_UPDATE_AT`(`UPDATE_AT`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_USER_CURRENCY_IS_FEE`(`USER_NO`, `LOCAL_CURRENCY`, `IS_FEE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6925 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '授权交易手续费收取补单临时表' ROW_FORMAT = Dynamic;

-- ----------------------------
