  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道类型：CTRIP  NIUM',
  `LOCAL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开卡币种',
  `TRANS_COUNT` bigint(11) NOT NULL DEFAULT 0 COMMENT '交易总笔数',
  `TOTAL_FEE` decimal(19, 2) NOT NULL COMMENT '总手续费',
  `NEED_CHARGFEE` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '欠收手续费汇总',
  `NEED_CHARGTRANS_COUNT` bigint(10) NOT NULL DEFAULT 0 COMMENT '欠收手续费交易笔数汇总',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
