) ENGINE = InnoDB AUTO_INCREMENT = 570 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '授权交易手续费收取汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_AUTH_RECOR
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_AUTH_RECOR`;
CREATE TABLE `T_VAS_AUTH_RECOR`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_LOG_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡编号',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡号',
  `OCCUR_TIME` timestamp NOT NULL COMMENT '交易发生时间',
  `TRANS_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种',
  `TRANS_CURRENCY_AMT` decimal(19, 2) NOT NULL COMMENT '交易币种金额',
  `TRANS_RATE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种转换率',
  `LOCAL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡币种',
  `LOCAL_CURRENCY_AMT` decimal(19, 2) NOT NULL COMMENT '卡本币种交易金额',
  `RESP_CODE` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易响应码',
  `RESP_CODE_DESC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易响应码描述',
  `APPROVAL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '授权码',
  `DECLINE_REASON` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易拒绝原因',
  `MESSAGE_TYPE` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '信息类型',
  `MESSAGE_TYPE_DESC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '信息类型描述',
  `POST_DATE` timestamp NULL DEFAULT NULL COMMENT '入账日期',
  `SETTLE_DATE` timestamp NULL DEFAULT NULL COMMENT '出账日期',
  `BILL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账币种',
  `BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账币种对应金额',
  `ORIGINAL_BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账原金额',
  `TRANS_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型',
  `TRANS_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型码',
  `TRANS_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `IS_CREDIT` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收或付标识 1:收；0：付',
  `MERCHANT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户名称',
  `MERCHANT_CATEGORY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户MCC',
  `MERCHANT_COUNTRY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家码',
  `MERCHANT_CITY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家城市',
  `MERCHANT_STATE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家城市区域',
  `MERCHANT_ZIP_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家邮编',
  `MERCHANT_DESC` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户描述',
  `IS_SETTLE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '1' COMMENT '是否结算 1:否；0：是',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_APPROVAL_CODE`(`APPROVAL_CODE`) USING BTREE,
  UNIQUE INDEX `UIDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  INDEX `IDX_TRANS_NO`(`TRANS_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '授权交易记录表' ROW_FORMAT = Dynamic;

