-- Table structure for T_VAS_AUTH_TRANS_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_AUTH_TRANS_RECORD`;
CREATE TABLE `T_VAS_AUTH_TRANS_RECORD`  (
