  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段8',
  `EXT9` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段9',
  `EXT10` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段10',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  UNIQUE INDEX `UIDX_TRANSACTION_ID`(`TRANSACTION_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_HASH_ID`(`CARD_HASH_ID`) USING BTREE,
  INDEX `IDX_TRANS_DATE`(`DATE_OF_TRANSACTION`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_ORIGIN_RECORD_NO`(`ORIGIN_RECORD_NO`) USING BTREE,
  INDEX `IDX_SUB_SCENE_CODE`(`SUB_SCENE_CODE`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 630 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '授权交易记录表_NUIM' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for T_VAS_AUTH_TRANS_RECORD_PT
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_AUTH_TRANS_RECORD_PT`;
CREATE TABLE `T_VAS_AUTH_TRANS_RECORD_PT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号',
  `CARD_KEY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡ID',
  `ID_TYPE` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ID类型 member matrix',
  `ID_VALUE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ID值',
  `TRANS_DATE` timestamp NOT NULL COMMENT '交易时间',
  `TRANSACTION_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易ID',
  `ORIGIN_TRANSACTION_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原交易ID',
  `MASK_CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '掩码卡号',
  `CARD_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡币种',
  `TRANSACTION_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `STATUS` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易状态 pending authorized succeed failed void',
  `TRANSACTION_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易金额',
  `TRANSACTION_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种',
  `TRANSACTION_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '交易手续费金额',
  `TRANSACTION_FEE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易手续费币种',
  `CROSS_BROAD_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '跨境手续费金额',
  `CROSS_BROAD_FEE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '跨境手续费币种',
  `CONVERSION_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '汇率转换费金额',
  `CONVERSION_FEE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '汇率转换费币种',
  `TRANSACTION_FEE_RETURN_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '交易手续费退回金额',
  `CROSS_BROAD_FEE_RETURN_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '跨境手续费退回金额',
  `CONVERSION_FEE_RETURN_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '汇率转换费退回金额',
  `REFUND_FEE_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '退款手续费金额',
  `REFUND_FEE_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款手续费币种',
  `ACCOUNT_CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扣款币种',
  `ACCOUNT_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '扣款币种金额(除trans_amt之外的其他金额的币种都一样)不含手续费的金额',
  `ACCOUNT_GROSS_AMOUNT` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '扣款总金额',
  `CHECK_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '验证码',
  `MERCHANT_NAME_LOCATION` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商家名称位置',
  `MEMBER_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '会员号',
  `CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '状态码',
  `MSG` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '状态描述',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_AT` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `IS_SETTLE` tinyint(1) NULL DEFAULT NULL COMMENT '是否结算 1:是；0：否',
  `REFUND_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '销卡退款状态 1:已退 0:未退 2:观察待处理 3:金额超限 4:非美金卡 默认空无需处理',
  `COMMON_TRANS_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易类型：AUTH,REVERSAL,REFUND,FEE,OCT',
  `COMMON_TRANS_STATUS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易状态：APPROVED,DECLIENED',
  `COMMON_RESP_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易响应码',
  `COMMON_RESP_CODE_DESC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易响应码描述',
  `CHANNEL_RESP_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易响应码',
  `CHANNEL_RESP_CODE_DESC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易响应码描述',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  UNIQUE INDEX `UIDX_TRANSACTION_ID`(`TRANSACTION_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_KEY`(`CARD_KEY`) USING BTREE,
  INDEX `IDX_TRANS_DATE`(`TRANS_DATE`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 259 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BATCH_FILE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BATCH_FILE`;
CREATE TABLE `T_VAS_BATCH_FILE`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `FILE_BATCH_NO` bigint(19) NOT NULL COMMENT '文件批次号',
  `COUNT` int(11) NULL DEFAULT 0 COMMENT '详情总计',
  `FILE_DFS_ID` bigint(19) NOT NULL COMMENT 'DFS文件编号',
  `FILE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '业务类型：0#用户卡头批处理卡',
  `ERROR_DFS_ID` bigint(19) NULL DEFAULT NULL COMMENT '错误的内容DFS编号',
  `STATUS` tinyint(255) NULL DEFAULT NULL COMMENT '状态：0-待处理，1-处理中，2-处理成功，3-处理失败',
  `REMARKS` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_FILE_BATCH_NO`(`FILE_BATCH_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 226 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC文件批处理记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BILLING_ADDRESS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BILLING_ADDRESS`;
CREATE TABLE `T_VAS_BILLING_ADDRESS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `STATUS` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0 禁用 1 启用 2 删除',
  `COUNTRY` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家',
  `COUNTRY_CODE` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家编码',
  `BILLING_STATE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单州或者省',
  `BILLING_CITY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单城市',
  `BILLING_ADDRESS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单地址',
  `BILLING_ZIP_CODE` varchar(26) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账单地区邮编',
  `REMARK` varchar(266) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3381 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BOUNTY
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BOUNTY`;
CREATE TABLE `T_VAS_BOUNTY`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `BOUNTY_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '奖励金编号',
  `USER_NO` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户号',
  `USER_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商户名',
  `AGENT_NO` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '代理商号',
  `AGENT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '代理商名',
  `ISSUE_STATUS` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'init' COMMENT '发放状态',
  `ISSUE_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发放方式',
  `ISSUE_MONTH` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '发放月份',
  `ISSUE_CCY_AMT` json NULL COMMENT '发放币种金额',
  `RECEIVE_ACCOUNT` json NULL COMMENT '到账账户 币种+账户号',
  `UPLOAD_RESULT` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '上传结果',
  `FILE_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '所属文件',
  `DFS_ID` bigint(20) NOT NULL DEFAULT 0 COMMENT 'dfs文件ID',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_user_no`(`USER_NO`) USING BTREE COMMENT '用户号',
  INDEX `idx_created_at`(`CREATE_AT`) USING BTREE COMMENT '创建时间',
  INDEX `idx_update_at`(`UPDATE_AT`) USING BTREE COMMENT '更新时间'
) ENGINE = InnoDB AUTO_INCREMENT = 107 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商奖励金' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BOUNTY_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BOUNTY_DETAIL`;
CREATE TABLE `T_VAS_BOUNTY_DETAIL`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `BOUNTY_ID` bigint(20) UNSIGNED NOT NULL COMMENT '奖励金表ID',
  `DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '日期',
  `USER_NO` bigint(20) UNSIGNED NOT NULL COMMENT '用户号',
  `USER_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户名',
  `AGENT_NO` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '代理商号',
  `AGENT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '代理商名',
  `BIZ_TYPE` tinyint(2) UNSIGNED NOT NULL COMMENT '业务类型 0开卡 1充值 2交易',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '加密卡号',
  `CARD_ID` bigint(19) UNSIGNED NOT NULL COMMENT '卡ID',
  `RECORD_NO` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '系统订单号',
  `CHANNEL_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '渠道',
  `MCC` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'MCC',
  `MERCHANT_NAME` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '商户名',
  `COUNTRY_CODE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '国家码',
  `TRANSACTION_CCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易币种',
  `TRANSACTION_AMT` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '交易金额',
  `LOCAL_CCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '卡币种',
  `LOCAL_AMT` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '卡金额',
  `REBATE_AMT` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '返点',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_user_no`(`USER_NO`) USING BTREE COMMENT '用户号',
  INDEX `idx_created_at`(`CREATE_AT`) USING BTREE COMMENT '创建时间',
  INDEX `idx_bounty_id`(`BOUNTY_ID`) USING BTREE COMMENT '奖励金表ID'
) ENGINE = InnoDB AUTO_INCREMENT = 174539 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '代理商奖励金明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BOUNTY_OP
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BOUNTY_OP`;
CREATE TABLE `T_VAS_BOUNTY_OP`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `BOUNTY_ID` bigint(20) UNSIGNED NOT NULL COMMENT '奖励金表ID',
  `OP_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作类型',
  `OP_USER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作人',
  `OP_NOTE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '操作备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 290 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '奖励金操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_BUSINESS_SCENE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_BUSINESS_SCENE`;
CREATE TABLE `T_VAS_BUSINESS_SCENE`  (
  `ID` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `SCENE_CODE` int(4) NULL DEFAULT NULL COMMENT '场景编号',
  `SCENE_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '场景名称',
  `SCENE_LOGO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '场景logo',
  `PRIORITY` int(10) NULL DEFAULT NULL COMMENT '排序',
  `SCENE_STATUS` tinyint(2) NOT NULL COMMENT '场景状态 0#禁用 1#启用',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `REMARKS` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_SCENE_NAME`(`SCENE_NAME`) USING BTREE,
  UNIQUE INDEX `uniq_SCENE_CODE`(`SCENE_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC业务场景基础配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CAL_BACK_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CAL_BACK_CONFIG`;
CREATE TABLE `T_VAS_CAL_BACK_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `AGENT_NO` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '商户号',
  `TYPE` tinyint(2) NOT NULL COMMENT '类型,1代理商模式,2商户模式',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '类型,0开卡1充值2交易',
  `CHANNEL_TYPE` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道,多个逗号分隔',
  `CARD_BIN` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡bin,多个逗号分隔',
  `MCC` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'mcc,多个逗号分隔',
  `BLACK_MCC` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'mcc黑名单,多个逗号分隔',
  `USER_LINE_NO` bigint(19) NULL DEFAULT NULL COMMENT '商户客群ID',
  `FIXED_VAL` decimal(19, 6) NULL DEFAULT NULL COMMENT '固定',
  `RATE_VAL` decimal(19, 6) NULL DEFAULT NULL COMMENT '费率',
  `RATE_SG_VAL` decimal(19, 6) NULL DEFAULT NULL COMMENT '国家为SG费率',
  `RATE_US_VAL` decimal(19, 6) NULL DEFAULT NULL COMMENT '国家为US费率',
  `RATE_REFUND_VAL` decimal(19, 6) NULL DEFAULT NULL COMMENT '退款返佣费率（带符号）',
  `EFFECT_BEGIN_TIME` date NOT NULL COMMENT '有效期-开始',
  `EFFECT_END_TIME` date NOT NULL COMMENT '有效期-结束',
  `CAL_TYPE` tinyint(2) NOT NULL COMMENT '考核类型,1逐笔2按月3季度',
  `RANGE_BEGIN` decimal(19, 6) NULL DEFAULT NULL COMMENT '非逐笔必须-开始区间',
  `RANGE_END` decimal(19, 6) NULL DEFAULT NULL COMMENT '非逐笔必须-结束区间',
  `RANGE_CAL` tinyint(2) NULL DEFAULT 1 COMMENT '是否固定阶梯，还是分阶梯返点。1固定2分阶梯返点',
  `MER_WHITE_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户白名单',
  `MER_BLACK_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户黑名单',
  `GROUP_ID` bigint(20) NULL DEFAULT NULL COMMENT '考核类型2和3的情况下，相同表示一组',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态,0:失效,1:生效',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_1`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '返点配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CAL_BACK_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CAL_BACK_DETAIL`;
CREATE TABLE `T_VAS_CAL_BACK_DETAIL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID主键',
  `AGENT_NO` varchar(55) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '代理商号',
  `USER_NO` bigint(19) NULL DEFAULT NULL COMMENT '商户号',
  `ORDER_ID` bigint(19) NOT NULL COMMENT '订单号和biz_type组成唯一',
  `CAL_ID` bigint(19) NOT NULL COMMENT '返点配置ID',
  `REL_ID` bigint(19) NOT NULL COMMENT '关联表的ID',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '类型,0开卡1充值2交易',
  `CARD_ID` bigint(19) NULL DEFAULT NULL COMMENT '卡ID',
  `GROUP_ID` bigint(19) NULL DEFAULT NULL COMMENT 'groupId',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道',
  `CARD_BIN` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡bin',
  `MCC` varchar(18) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'mcc',
  `ORIGIN_MER` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始商户名',
  `USE_MER` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '优化后的商户名',
  `MERCHANT_COUNTRY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家码',
  `CAL_TYPE` tinyint(2) NOT NULL COMMENT '考核类型,1逐笔2按月3季度',
  `TRADE_AMT` decimal(19, 6) NULL DEFAULT NULL COMMENT '交易金额',
  `TRADE_CCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易币种',
  `TRADE_DATE` date NULL DEFAULT NULL COMMENT '交易日期',
  `FEE_AMT` decimal(19, 6) NULL DEFAULT NULL COMMENT '费用金额',
  `FEE_CCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '费用币种',
  `CCY_RATE` decimal(19, 6) NULL DEFAULT NULL COMMENT '汇率',
  `CAL_TOTAL_BEFORE_AMT` decimal(19, 6) NULL DEFAULT NULL COMMENT '金额(累积之前美元)',
  `CAL_ORIGIN_AMT` decimal(19, 6) NULL DEFAULT NULL COMMENT '返点金额-原币种金额',
  `CAL_ORIGIN_CCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '返点金额-原币种',
  `CAL_ID_NEW` bigint(19) NULL DEFAULT NULL COMMENT '返点配置ID-重新计算',
  `CAL_ORIGIN_AMT_NEW` decimal(19, 6) NULL DEFAULT NULL COMMENT '返点金额-原币种金额-重新计算',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_1`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_2`(`CHANNEL_TYPE`, `CARD_BIN`) USING BTREE,
  INDEX `IDX_3`(`USER_NO`) USING BTREE,
  INDEX `IDX_4`(`AGENT_NO`) USING BTREE,
  INDEX `IDX_5`(`TRADE_DATE`) USING BTREE,
  INDEX `IDX_6`(`ORDER_ID`, `BIZ_TYPE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 333 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '返点明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD`;
CREATE TABLE `T_VAS_CARD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号',
  `CARD_BIN_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡bin',
  `SCENE_CODE` int(4) NULL DEFAULT NULL COMMENT '场景code',
  `AIRLINE_CODE` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '航司code',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道类型：CTRIP  NIUM',
  `CARD_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '卡类型：0#为常规  1#共享子卡',
  `CARD_ORG` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡组织M:master V:visa',
  `USER_BILL_REL_ID` bigint(20) NULL DEFAULT NULL COMMENT '持卡人关联表ID',
  `BILLING_ADDRESS_ID` bigint(20) NULL DEFAULT NULL COMMENT '账单ID',
  `PAY_ACCOUNT_TYPE` tinyint(4) NULL DEFAULT 0 COMMENT '付款账户类型0基本 1未结算',
  `PAY_ACCOUNT_CCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款账户币种',
  `LOCAL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开卡币种',
  `BILL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '结算币种',
  `START_DATE` date NOT NULL COMMENT '卡生效时间',
  `END_DATE` date NOT NULL COMMENT '关卡时间',
  `AUTH_LIMIT_AMOUNT` decimal(8, 2) NOT NULL COMMENT '授权额度',
  `BALANCE_AMOUNT` decimal(8, 2) NULL DEFAULT 0.00 COMMENT '可用余额',
  `CHANNEL_BALANCE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道余额',
  `CARD_CLOSE_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '销卡金额',
  `CHANNEL_SYNC_TIME` timestamp NULL DEFAULT NULL COMMENT '渠道同步时间',
  `TRADE_MIN_AMOUNT` decimal(8, 2) NOT NULL COMMENT '交易最小金额',
  `TRADE_MAX_AMOUNT` decimal(8, 2) NOT NULL COMMENT '交易最大金额',
  `ENABLE_MULTI_USE` tinyint(4) NOT NULL COMMENT '是否多次使用1是0否',
  `CLOSE_PERCENTAGE` int(8) NOT NULL COMMENT '自动关卡百分数设定',
  `MAX_AUTH_TIMES` int(8) NULL DEFAULT NULL COMMENT '最大交易次数',
  `MERCHANT_CONTROL_METHOD` tinyint(4) NOT NULL COMMENT '商户MCC控制方式0指定商户号  1指定商户列表 2指定商户MCC 3 指定商户MCC列表 4 指定商户MCC数组',
  `MERCHANT_CATEGORY_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别码',
  `MERCHANT_CATEGORY_CODE_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别码列表 \'|\'分隔',
  `MERCHANT_CATEGORY_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别',
  `MERCHANT_CODE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户号',
  `MERCHANT_CODE_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户列表',
  `ENABLE_3DS` tinyint(4) NOT NULL COMMENT '是否支持3ds验证 0不支持  1支持',
  `ENABLE_CVV_CHECK` tinyint(4) NOT NULL COMMENT '是否启用CVV检验 0 不开启 1开启验证',
  `ENABLE_CURRENCY_CHECK` tinyint(4) NOT NULL COMMENT '是否启用交易币种验证 0 不限制  1只允许开卡币种作为交易币种',
  `USER_DEFINE_INFO` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户自定义信息，按照发卡商约定传送数据，一般在交易账单中体现',
  `CARD_INFO_EXTRA` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡扩展字段',
  `CHANNEL_CARD_ID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡唯一ID',
  `CHANNEL_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联到虚拟卡的id',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '加密卡号',
  `CARD_VERIFY_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '加密校验码',
  `CARD_EXPIRY_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '加密有效期',
  `STATUS` tinyint(2) NOT NULL COMMENT '卡状态1正常2销号',
  `CARD_ALIAS` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡别名',
  `CREATE_AT` timestamp NOT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `GROUP_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡组ID',
  `USED_AUTH_MONEY` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '已使用额度',
  `CARD_PREFIX` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密卡号前缀6位',
  `CARD_SUFFIX` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密卡号后缀4位',
  `CARD_LABEL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '卡标签',
  `USED_AMOUNT_LIMIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '使用限额',
  `VERSION_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '版本标识',
  `CHANNEL_AUTH_LIMIT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道限额',
  `BP_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT 'BP累计金额',
  `DAILY_LIMIT` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '日限额',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_1`(`CARD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_NO`(`CARD_NO`) USING BTREE,
  INDEX `IDX_GROUP_ID`(`GROUP_ID`) USING BTREE,
  INDEX `IDX_USER_BILL_REL_ID`(`USER_BILL_REL_ID`) USING BTREE,
  INDEX `IDX_BA_ID`(`BILLING_ADDRESS_ID`) USING BTREE,
  INDEX `idx_channel_cardid`(`CHANNEL_CARD_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_START_DATE`(`START_DATE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24244 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARDBIN_APPLY
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARDBIN_APPLY`;
CREATE TABLE `T_VAS_CARDBIN_APPLY`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
