  `CARD_SCENE_BATCH_NO` bigint(20) NOT NULL COMMENT '卡用途场景配置编号BATCH_NO',
  `RISK_ONE_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `RISK_ONE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核人',
  `RISK_ONE_AT` timestamp NULL DEFAULT NULL COMMENT '风控审核时间',
  `RISK_ONE_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `RISK_TWO_STATUS` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '风控事中审核状态 0#待审核 1#审核暂停 2#审核成功 3#审核失败',
  `RISK_TWO_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控事中审核人',
  `RISK_TWO_AT` timestamp NULL DEFAULT NULL COMMENT '风控事中审核时间',
  `RISK_TWO_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控事中审核备注',
  `IS_REPORT` tinyint(1) NULL DEFAULT NULL COMMENT '是否需要报备9#无需报备 1#需要报备',
  `STATUS` char(2) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0' COMMENT '状态：0#待审核，1#审核中 2#审核通过 3#审核失败',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_APPLY_NO`(`APPLY_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 146 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户卡bin申请表' ROW_FORMAT = Dynamic;

