  `LOCAL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开卡币种',
  `BILL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '结算币种',
  `START_DATE` date NOT NULL COMMENT '卡生效时间',
  `END_DATE` date NOT NULL COMMENT '关卡时间',
  `AUTH_LIMIT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '授权额度',
  `TRADE_MIN_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易最小金额',
  `TRADE_MAX_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易最大金额',
  `ENABLE_MULTI_USE` tinyint(4) NOT NULL COMMENT '是否多次使用1是0否',
  `CLOSE_PERCENTAGE` int(8) NOT NULL COMMENT '自动关卡百分数设定',
  `MAX_AUTH_TIMES` int(8) NULL DEFAULT NULL COMMENT '最大交易次数',
  `MERCHANT_CONTROL_METHOD` tinyint(4) NOT NULL COMMENT '商户MCC控制方式0指定商户号  1指定商户列表 2指定商户MCC 3 指定商户MCC列表 4 指定商户MCC数组',
  `MERCHANT_CATEGORY_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别码',
  `MERCHANT_CATEGORY_CODE_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别码列表 \'|\'分隔',
  `MERCHANT_CATEGORY_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC类别',
  `MERCHANT_CODE` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户号',
  `MERCHANT_CODE_LIST` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户列表',
  `ENABLE_3DS` tinyint(4) NOT NULL COMMENT '是否支持3ds验证 0不支持  1支持',
  `ENABLE_CVV_CHECK` tinyint(4) NOT NULL COMMENT '是否启用CVV检验 0 不开启 1开启验证',
  `ENABLE_CURRENCY_CHECK` tinyint(4) NOT NULL COMMENT '是否启用交易币种验证 0 不限制  1只允许开卡币种作为交易币种',
  `USER_DEFINE_INFO` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用户自定义信息，按照发卡商约定传送数据，一般在交易账单中体现',
  `CARD_INFO_EXTRA` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡扩展字段',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道类型：CTRIP  NIUM',
  `CHANNEL_REQ_TIME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道请求时间-补单用',
  `CHANNEL_RESP_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回id',
  `CHANNEL_RESP_STATUS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回状态',
  `CHANNEL_RESP_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回Code',
  `CHANNEL_RESP_MSG` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回MSG',
