-- ----------------------------
-- Table structure for T_VAS_CARD_BAL_CHANGE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_BAL_CHANGE`;
CREATE TABLE `T_VAS_CARD_BAL_CHANGE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号/卡组唯一编号',
  `CARD_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '卡类型：0#为常规  1#共享卡',
  `CHANGE_SOURCE` tinyint(2) NULL DEFAULT 0 COMMENT '卡类型：0#交易同步  1#自动任务同步',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型：CTRIP  NIUM  PT',
  `OLD_BAL` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '同步前余额',
  `NEW_BAL` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '当前余额',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33422 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC卡余额变更表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_BIN
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_BIN`;
CREATE TABLE `T_VAS_CARD_BIN`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
