  `CARD_ORG` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡组织M:master V:visa',
  `COUNTRY` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家',
  `REMARK` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `SUPPORT_AUTH_CONFIRM` tinyint(4) NULL DEFAULT 0 COMMENT '是否支持决策0不支持1支持',
  `CARD_BIN_NOTES` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡bin说明，客户端页面展示',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_1`(`CHANNEL_TYPE`, `CARD_BIN`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
