-- ----------------------------
-- Table structure for T_VAS_CARD_COUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_COUNT`;
CREATE TABLE `T_VAS_CARD_COUNT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
