  `TYPE` tinyint(2) NOT NULL COMMENT '类型：0开卡 1充值 2退款 3销卡 4清算汇差  5冲正后请款 6其他异常情况 7异常清算请款  11授权消费 12授权冲正 13清算退款',
  `AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '金额',
