  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13976 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '卡资金明细' ROW_FORMAT = Dynamic;

