  `TRADE_MAX_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易最大金额',
  `ENABLE_3DS` tinyint(4) NULL DEFAULT NULL COMMENT '是否支持3ds验证 0不支持  1支持',
  `ENABLE_CVV_CHECK` tinyint(4) NULL DEFAULT NULL COMMENT '是否启用CVV检验 0 不开启 1开启验证',
  `ENABLE_CURRENCY_CHECK` tinyint(4) NULL DEFAULT NULL COMMENT '是否启用交易币种验证 0 不限制  1只允许开卡币种作为交易币种',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道类型',
  `CHANNEL_REQ_TIME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道请求时间-补单用',
  `CHANNEL_RESP_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回id',
  `CHANNEL_RESP_STATUS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回状态',
  `CHANNEL_RESP_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回Code',
  `CHANNEL_RESP_MSG` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回MSG',
  `CREATE_AT` timestamp NOT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DAILY_LIMIT` decimal(18, 6) NULL DEFAULT NULL COMMENT '日限额',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `unique_user_no`(`USER_NO`, `USER_REQ_NO`, `OP_TYPE`) USING BTREE,
  UNIQUE INDEX `unique_ORDER_ID`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`, `OP_TYPE`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_UPDATE_AT`(`UPDATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51807 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_OP_AUTO_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_OP_AUTO_CONFIG`;
CREATE TABLE `T_VAS_CARD_OP_AUTO_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NOT NULL COMMENT '卡(常规/共享)唯一编号',
  `CARD_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '卡类型：0#为常规  1#共享卡',
  `OP_TYPE` tinyint(2) NOT NULL COMMENT '操作类型：1-充值',
  `START_DATE` date NULL DEFAULT NULL COMMENT '生效时间',
  `END_DATE` date NULL DEFAULT NULL COMMENT '失效时间',
  `INCREMENT_AMOUNT` decimal(8, 2) NOT NULL COMMENT '自动转入金额',
  `REMAIN_AMOUNT` decimal(8, 2) NOT NULL COMMENT '剩余余额',
  `TRANSFER_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '转入模式(1-转入固定值到余额 2-转入后余额至固定值)',
  `MOBILE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手机号（前缀-号码）',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态1正常2关闭',
  `CREATE_AT` timestamp NOT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_1`(`CARD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 373 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '卡自动操作配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_POOL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_POOL`;
CREATE TABLE `T_VAS_CARD_POOL`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '唯一单号',
  `USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号',
  `CARD_BIN_ID` bigint(20) NOT NULL COMMENT '卡bin',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型：CTRIP  NIUM',
  `LOCAL_CURRENCY` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开卡币种',
  `START_DATE` date NOT NULL COMMENT '卡生效时间',
  `END_DATE` date NOT NULL COMMENT '关卡时间',
  `AUTH_LIMIT_AMOUNT` decimal(19, 2) NOT NULL COMMENT '授权额度',
  `ENABLE_MULTI_USE` tinyint(4) NOT NULL COMMENT '是否多次使用1是0否',
  `CHANNEL_CARD_ID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道卡唯一ID',
  `CHANNEL_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联到虚拟卡的id',
  `CHANNEL_RESP_STATUS` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回状态',
  `CHANNEL_RESP_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回Code',
  `CHANNEL_RESP_MSG` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道返回MSG',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密卡号',
  `CARD_VERIFY_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密校验码',
  `CARD_EXPIRY_DATE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密有效期',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态 0-待处理 1-处理中 2-待分配 3-已分配 5-失败',
  `CARD_PREFIX` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密卡号前缀6位',
  `CARD_SUFFIX` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '加密卡号后缀4位',
  `VERSION_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '版本标识',
  `CREATE_AT` timestamp NOT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `CARD_USER_INFO_ID` bigint(20) NULL DEFAULT NULL COMMENT '上送渠道的持卡人id',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_1`(`ORDER_ID`) USING BTREE,
  UNIQUE INDEX `uniq_channel_card_id`(`CHANNEL_TYPE`, `CHANNEL_CARD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE,
  INDEX `IDX_CARD_POOL`(`CARD_BIN_ID`, `CHANNEL_TYPE`, `LOCAL_CURRENCY`, `ENABLE_MULTI_USE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2176 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_ROUTE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_ROUTE`;
CREATE TABLE `T_VAS_CARD_ROUTE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CARD_TYPE` tinyint(2) NULL DEFAULT 0 COMMENT '卡类型：0#为常规  1#共享子卡',
  `TYPE` tinyint(2) NOT NULL COMMENT '类型：0#全局  1#指定用户',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_BIN` varchar(12) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡头',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型：CTRIP  NIUM  PT PP EP',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态：0#禁用 1#正常',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `CCY` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '支持的币种：【,】分割',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_KEY`(`CARD_TYPE`, `TYPE`, `USER_NO`, `CARD_BIN`, `CHANNEL_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`CARD_TYPE`, `CARD_BIN`, `USER_NO`, `STATUS`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 162 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC卡路由切换表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_TRANS_DETAILS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_TRANS_DETAILS`;
CREATE TABLE `T_VAS_CARD_TRANS_DETAILS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NOT NULL COMMENT '卡id',
  `CHANNEL_CARD_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡id',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '加密卡号',
  `CARD_TYPE` tinyint(2) NOT NULL DEFAULT 0 COMMENT '卡类型：0#常规卡  1#共享卡',
  `CARD_STATUS` tinyint(2) NOT NULL COMMENT '卡状态 1-正常 2-销号 0-暂停',
  `GROUP_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡组ID',
  `GROUP_STATUS` tinyint(2) NULL DEFAULT 1 COMMENT '卡组状态 0暂停 1正常 2销卡',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `ORIGIN_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '原授权记录编号',
  `TRANS_TIME` timestamp NOT NULL COMMENT '交易时间',
  `CHANNEL_AUTH_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易id',
  `ORIGIN_CHANNEL_AUTH_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原渠道交易id',
  `APPROVAL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权码',
  `TRANS_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易币种',
  `TRANS_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易币种金额',
  `LOCAL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡币种',
  `LOCAL_CURRENCY_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '卡本币种交易金额',
  `ORIGIN_LOCAL_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始卡币种金额-不加bp',
  `MERCHANT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户名称',
  `MERCHANT_CATEGORY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户MCC',
  `MERCHANT_COUNTRY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家码',
  `CROSS_BOARD_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '跨境交易类型：0:境内 1:境外',
  `COMMON_TRANS_TYPE` tinyint(2) NULL DEFAULT NULL COMMENT '通用交易类型：1-AUTH 2-REVERSAL 3-REFUND 4-清算差额 5-冲正后请款 6-清算差额-退回 7-商家强制清算',
  `COMMON_TRANS_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '通用交易状态：0-PENDING 1-APPROVED 2-DECLIENED 3-SETTLED',
  `COMMON_RESP_CODE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易响应码',
  `COMMON_RESP_CODE_DESC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通用交易响应码描述',
  `CHANNEL_RESP_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易响应码',
  `CHANNEL_RESP_CODE_DESC` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易响应码描述',
  `CHANNEL_FEE_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道成本-币种',
  `CHANNEL_FEE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道成本-金额',
  `CHANNEL_BILLING_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道实际扣款币种(NIUM)',
  `CHANNEL_BILLING_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道实际扣款金额(NIUM)',
  `CHANNEL_SETTLE_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道清算币种(NIUM)',
  `CHANNEL_SETTLE_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道清算金额(NIUM)',
  `FUNDS_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '资金类型：0-常规卡 1-共享卡 2-账户',
  `FUNDS_DIRECTION` tinyint(1) NULL DEFAULT NULL COMMENT '资金方向：0-扣款 1-退款',
  `REVERSAL_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已冲正金额',
  `UNSETTLED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '未清算金额',
  `SETTLED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '总清算金额',
  `ORIGIN_SETTLED_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始清算金额',
  `REFUND_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '已退款金额',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `SETTLE_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '清算单号',
  `SETTLE_TIME` timestamp NULL DEFAULT NULL COMMENT '清算时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段8',
  `EXT9` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段9',
  `EXT10` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段10',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `IDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_CHANNEL_CARD_ID`(`CHANNEL_CARD_ID`) USING BTREE,
  INDEX `IDX_TRANS_TIME`(`TRANS_TIME`) USING BTREE,
  INDEX `IDX_AUTH_ID`(`CHANNEL_AUTH_ID`) USING BTREE,
  INDEX `IDX_ORIGIN_AUTH_ID`(`ORIGIN_CHANNEL_AUTH_ID`) USING BTREE,
  INDEX `IDX_APPROVAL_CODE`(`APPROVAL_CODE`) USING BTREE,
  INDEX `IDX_ORIGIN_RECORD_NO`(`ORIGIN_RECORD_NO`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11571 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '卡交易明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_USER_BILL_RELATION
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_USER_BILL_RELATION`;
CREATE TABLE `T_VAS_CARD_USER_BILL_RELATION`  (
