  INDEX `IDX_CARD_USER_ID`(`CARD_USER_ID`) USING BTREE,
  INDEX `IDX_BA`(`BILLING_ADDRESS_ID`) USING BTREE,
  INDEX `IDX_STATUS`(`STATUS`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4784 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CARD_USER_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CARD_USER_INFO`;
CREATE TABLE `T_VAS_CARD_USER_INFO`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `CARD_USER_ID` bigint(20) NULL DEFAULT NULL COMMENT '对外持卡人ID',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `STATUS` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0 禁用 1 启用 2 删除',
