  INDEX `IDX_CARD_USER_ID`(`CARD_USER_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 103385 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_CHANNEL_ACCOUNT_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_CHANNEL_ACCOUNT_DETAIL`;
CREATE TABLE `T_VAS_CHANNEL_ACCOUNT_DETAIL`  (
  `ID` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `CHANNEL_TYPE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '渠道',
  `CHANNEL_CARD_ID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '渠道卡ID',
  `RECORD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '流水号',
  `ACC_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账户币种',
  `TXN_AMT` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '交易金额',
  `TXN_TYPE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '交易类型 1. 寻汇 00-转入 01-转出 10-开卡手续费 11-结算手续费 12-退款手续费 13-授权手续费 14-chargeback 手续费 20-结算 21-退款',
  `PRE_BAL` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '期初余额',
  `POST_BAL` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '期末余额',
  `TXN_TIME` timestamp NULL DEFAULT NULL COMMENT '交易时间',
  `VERSION_FLAG` tinyint(2) NULL DEFAULT NULL COMMENT '版本标识',
  `REF_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联编号 ：结算退款 ID 寻汇',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
