-- ----------------------------
-- Table structure for T_VAS_DIFF_TRANS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_DIFF_TRANS`;
CREATE TABLE `T_VAS_DIFF_TRANS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡id',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道类型',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
