  `DIFF_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '异常处理状态：0-待处理 1-成功 2-失败',
  `VERIFY_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '核对状态：0-待审核(自动)  1-待审核(人工)  2-审核通过  3-审核拒绝',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
