  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_KEY`(`RECORD_NO`, `DIFF_TYPE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_RECORD_NO`(`ORIGIN_RECORD_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7364 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '异常交易明细' ROW_FORMAT = Dynamic;

