  `PARTICIPANT_SINK` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参与者接收方',
  `ORIGINAL_CURRENCY` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始货币',
  `ORIGINAL_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始金额',
