  `NON_FOREX_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '非外汇费用',
  `FOREX_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '外汇费用',
  `BALANCE_BEFORE` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易前余额',
  `BALANCE_ADJUSTMENT` decimal(19, 2) NULL DEFAULT NULL COMMENT '余额调整',
  `BALANCE_AFTER` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易后余额',
