  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `ORDER_ID` bigint(20) NOT NULL COMMENT '唯一单号',
  `USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '用户号',
  `CERTIFICATE_ID` bigint(20) NULL DEFAULT NULL COMMENT '证书编号',
  `ENCRYPT_TYPE` tinyint(2) NOT NULL COMMENT '加密方式 1私钥加密 ',
  `BIZ_TYPE` tinyint(2) NOT NULL COMMENT '业务类型1 vccwebhook',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态0待处理 1成功 2 失败',
  `NOTIFY_URL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '通知地址',
  `CONTENT` varchar(5024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '通知内容',
  `RESP_HTTP_CODE` int(8) NULL DEFAULT NULL COMMENT '响应的http状态',
  `RESP_MSG` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '响应内容',
  `CREATE_AT` timestamp NOT NULL,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `UPDATE_AT` timestamp NOT NULL,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `unique_order_id`(`ORDER_ID`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58969 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_OPERATE_LOG
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_OPERATE_LOG`;
CREATE TABLE `T_VAS_OPERATE_LOG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `OPERATE_TYPE` tinyint(2) NOT NULL COMMENT '操做类型 1 根据用户批量销卡',
  `CNT` int(5) NULL DEFAULT NULL COMMENT '操做笔数',
  `STATUS` tinyint(2) NOT NULL DEFAULT 1 COMMENT '0初始化 1 处理中 2完成',
  `OPERATE_KEY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '根据输入关键参数生成的key，用户锁定防止用户重复提交',
  `PARAME` varchar(1024) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '输入参数',
  `REMARK` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC操做日志' ROW_FORMAT = Dynamic;

