-- ----------------------------
-- Table structure for T_VAS_POSITIONS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_POSITIONS`;
CREATE TABLE `T_VAS_POSITIONS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `CURRENCY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `FUNDING_CHANNEL_ID` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '200014',
  `BALANCE` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '余额',
  `TRADE_DATE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易日期',
