  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'system' COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_CCY`(`CURRENCY`, `FUNDING_CHANNEL_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '卡头寸' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_POSITIONS_DETAIL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_POSITIONS_DETAIL`;
CREATE TABLE `T_VAS_POSITIONS_DETAIL`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `ORDER_NO` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易订单号',
  `CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '币种',
  `FUNDING_CHANNEL_ID` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '200014',
  `CURRENT_BALANCE` decimal(19, 2) NOT NULL COMMENT '交易前余额',
  `TRADE_BALANCE` decimal(19, 2) NOT NULL COMMENT '交易余额',
  `TRADE_END_BALANCE` decimal(19, 2) NOT NULL COMMENT '交易后余额',
  `TRADE_DATE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易日期',
  `TRADE_TYPE` tinyint(2) NOT NULL COMMENT '交易类型，1：开卡',
  `BALANCE_CHANGE_TYPE` tinyint(2) NOT NULL COMMENT '余额变动类型：1-增加，2-减少',
  `TRADE_DIRECTION` tinyint(2) NULL DEFAULT NULL COMMENT '交易方向，1：买入，2：卖出',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_ORDER_NO_CCY`(`ORDER_NO`, `CURRENCY`, `TRADE_DIRECTION`, `TRADE_TYPE`, `FUNDING_CHANNEL_ID`) USING BTREE,
  INDEX `IDX_TRADE_DATE`(`TRADE_DATE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21920 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '卡头寸明细表' ROW_FORMAT = Dynamic;

