-- ----------------------------
-- Table structure for T_VAS_P_ACCOUNT_RELATION
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_P_ACCOUNT_RELATION`;
CREATE TABLE `T_VAS_P_ACCOUNT_RELATION`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
