  `PROGRAM_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主账户ID',
  `CURRENCY` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主账户币种',
  `SUB_ACCOUNT_ID` bigint(20) NOT NULL COMMENT '子账户主键ID',
  `PAYEE_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户收款ID',
  `CHANNEL_PRIMARY_CARD_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道主卡ID',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态 1:正常, 2:关闭',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uk_gep_program_payee`(`GEP_MERCHANT_CODE`, `PROGRAM_ID`, `PAYEE_ID`) USING BTREE,
  INDEX `idx_program_id`(`PROGRAM_ID`) USING BTREE,
  INDEX `idx_currency`(`CURRENCY`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'P卡子主账户关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_P_SUBACCOUNT
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_P_SUBACCOUNT`;
CREATE TABLE `T_VAS_P_SUBACCOUNT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `ACCOUNT_TYPE` tinyint(2) NOT NULL COMMENT '子账户类型: 1 个人, 2 企业',
  `ACCOUNT_NAME` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户名称',
  `IDENTITY_NUMBER` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户证件号',
  `EMAIL` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户邮箱',
  `EMAIL_PASSWORD` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子账户邮箱密码（预留）',
  `MOBILE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户手机号',
  `STATUS` tinyint(2) NOT NULL COMMENT '状态 1: 正常, 2: 关闭',
  `REMARKS` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预留备注',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_email`(`EMAIL`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 115 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'P卡子账户信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_P_TRANSFER_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_P_TRANSFER_RECORD`;
CREATE TABLE `T_VAS_P_TRANSFER_RECORD`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `GEP_MERCHANT_CODE` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Gep商户号',
  `SUB_ACCOUNT_ID` bigint(20) NULL DEFAULT NULL COMMENT '子账户ID',
  `PAYEE_ID` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子账户收款ID',
  `CURRENCY` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '币种',
  `AMOUNT` decimal(10, 2) NOT NULL COMMENT '金额',
  `STATUS` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '转账状态',
  `DESCRIPTION` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款说明',
  `ACCOUNT_FLAG` tinyint(2) NOT NULL DEFAULT 0 COMMENT '转账标识(0:初始化1:已转账2:已退回)',
  `CHANNEL_RESP_CODE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '渠道返回码',
  `CHANNEL_RESP_MSG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '渠道返回信息',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `CREATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `UPDATE_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `AUDIT_BY` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `AUDIT_REMARK` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注/拒绝原因',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `idx_record_no`(`RECORD_NO`) USING BTREE,
  INDEX `idx_gep_merchant_code`(`GEP_MERCHANT_CODE`) USING BTREE,
  INDEX `idx_status`(`STATUS`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'P卡转账记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_REBATE_REPORT_CTRIP
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_REBATE_REPORT_CTRIP`;
CREATE TABLE `T_VAS_REBATE_REPORT_CTRIP`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT,
  `CARD_LOG_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡编号',
  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号',
  `USER_NO` bigint(20) NULL DEFAULT NULL COMMENT '用户号',
  `ORDER_ID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单ID',
  `TRANS_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件中的TransID 不唯一',
  `ACTIVITY_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '类型',
  `TRANS_DATE` date NULL DEFAULT NULL COMMENT '交易日期',
  `TRANS_TIME` timestamp NULL DEFAULT NULL COMMENT '交易时间',
  `CURRENCY` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '币种',
  `AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '币种金额',
  `PRODUCT_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品code',
  `CROSS_BOARD_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '跨境交易类型：0:domestic 1:international ',
  `COMMISSION_RATE` double(8, 2) NULL DEFAULT NULL COMMENT '返点比例',
  `COMMISSION_MCC_GROUP` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '返点mcc组',
  `MCC` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'mcc',
  `MERCHANT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户名称',
  `CHANNEL` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'channel',
  `BATCH_DATE` date NULL DEFAULT NULL COMMENT '批次日期',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_EVENT_TIME`(`TRANS_TIME`) USING BTREE,
  INDEX `IDX_CARD_LOG_ID`(`CARD_LOG_ID`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_REFUND_AUDIT
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_REFUND_AUDIT`;
CREATE TABLE `T_VAS_REFUND_AUDIT`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '关联交易单号',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型：CTRIP  NIUM  PT',
  `BIZ_TYPE` tinyint(2) NOT NULL DEFAULT 1 COMMENT '业务类型：1-冲正退款，2-清算退款',
  `TRADE_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种，一般是外币',
  `TRADE_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '交易金额',
  `TRADE_AT` timestamp NOT NULL COMMENT '交易发生时间',
  `TRADE_MERCHANT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易商户名称',
  `CARD_CHANNEL_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡ID',
  `CARD_CHANNEL_BAL` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '渠道当前余额',
  `CARD_BAL_AT` timestamp NULL DEFAULT NULL COMMENT '余额查询时间',
  `CARD_CLOSE_AMT` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '销卡已退金额',
  `CARD_CLOSE_AT` timestamp NOT NULL COMMENT '销卡时间',
  `CARD_BAL_STATUS` tinyint(2) NOT NULL COMMENT '渠道余额查询状态：1-余额查询成功，2-余额查询失败',
  `AUDIT_RISK_STATUS` tinyint(2) NOT NULL COMMENT '风控审核状态 0#待审核 2#审核成功 3#审核失败 8#无需审核',
  `RISK_REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '风控审核备注',
  `INCOME_STATUS` tinyint(2) NOT NULL COMMENT '入账状态：0-待入账 1-入账成功，2-入账失败 3-入账处理中',
  `ORDER_STATUS` tinyint(2) NOT NULL COMMENT '订单状态：0-处理中 1-处理完成，2-处理失败',
  `ORDER_SUCCESS_DATE` datetime NULL DEFAULT NULL COMMENT '订单完成时间',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `AUDIT_RISK_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `AUDIT_RISK_AT` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_RECORD_NO`(`RECORD_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
