  `BIRTH_DATE` date NOT NULL COMMENT '生日',
  `COUNTRY` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '国家',
  `COUNTRY_CODE` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '国家编码',
  `DELIVERY_ADDRESS1` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收货、住所地址',
  `DELIVERY_ADDRESS2` varchar(125) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行2',
  `DELIVERY_CITY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收货、住所地址所在城市',
  `DELIVERY_ZIP_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `EMAIL` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '邮箱',
  `BILLING_ADDRESS1` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账单地址',
  `BILLING_ADDRESS2` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行2',
  `BILLING_CITY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账单城市',
  `BILLING_ZIP_CODE` varchar(26) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账单地区邮编',
  `NATIVE_LANGUAGE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '本国姓名',
  `CORRESPONDENCE_ADDRESS1` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '通信地址1',
  `CORRESPONDENCE_ADDRESS2` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '行2',
  `CORRESPONDENCE_CITY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类别',
