  `TIMES_TRIGGERED` bigint(10) NOT NULL,
  PRIMARY KEY (`SCHED_NAME`, `TRIGGER_NAME`, `TRIGGER_GROUP`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_JOB_SIMPROP_TRIGGERS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_JOB_SIMPROP_TRIGGERS`;
CREATE TABLE `T_VAS_RISK_JOB_SIMPROP_TRIGGERS`  (
  `SCHED_NAME` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `TRIGGER_NAME` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `TRIGGER_GROUP` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `STR_PROP_1` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `STR_PROP_2` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `STR_PROP_3` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `INT_PROP_1` int(11) NULL DEFAULT NULL,
  `INT_PROP_2` int(11) NULL DEFAULT NULL,
  `LONG_PROP_1` bigint(20) NULL DEFAULT NULL,
  `LONG_PROP_2` bigint(20) NULL DEFAULT NULL,
  `DEC_PROP_1` decimal(13, 4) NULL DEFAULT NULL,
  `DEC_PROP_2` decimal(13, 4) NULL DEFAULT NULL,
  `BOOL_PROP_1` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `BOOL_PROP_2` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`SCHED_NAME`, `TRIGGER_NAME`, `TRIGGER_GROUP`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_JOB_TRIGGERS
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_JOB_TRIGGERS`;
CREATE TABLE `T_VAS_RISK_JOB_TRIGGERS`  (
  `SCHED_NAME` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `TRIGGER_NAME` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `TRIGGER_GROUP` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `JOB_NAME` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `JOB_GROUP` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `DESCRIPTION` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `NEXT_FIRE_TIME` bigint(13) NULL DEFAULT NULL,
  `PREV_FIRE_TIME` bigint(13) NULL DEFAULT NULL,
  `PRIORITY` int(11) NULL DEFAULT NULL,
  `TRIGGER_STATE` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `TRIGGER_TYPE` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `START_TIME` bigint(13) NOT NULL,
  `END_TIME` bigint(13) NULL DEFAULT NULL,
  `CALENDAR_NAME` varchar(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `MISFIRE_INSTR` smallint(2) NULL DEFAULT NULL,
  `JOB_DATA` blob NULL,
  PRIMARY KEY (`SCHED_NAME`, `TRIGGER_NAME`, `TRIGGER_GROUP`) USING BTREE,
  INDEX `IDX_QRTZ_T_J`(`SCHED_NAME`, `JOB_NAME`, `JOB_GROUP`) USING BTREE,
  INDEX `IDX_QRTZ_T_JG`(`SCHED_NAME`, `JOB_GROUP`) USING BTREE,
  INDEX `IDX_QRTZ_T_C`(`SCHED_NAME`, `CALENDAR_NAME`) USING BTREE,
  INDEX `IDX_QRTZ_T_G`(`SCHED_NAME`, `TRIGGER_GROUP`) USING BTREE,
  INDEX `IDX_QRTZ_T_STATE`(`SCHED_NAME`, `TRIGGER_STATE`) USING BTREE,
  INDEX `IDX_QRTZ_T_N_STATE`(`SCHED_NAME`, `TRIGGER_NAME`, `TRIGGER_GROUP`, `TRIGGER_STATE`) USING BTREE,
  INDEX `IDX_QRTZ_T_N_G_STATE`(`SCHED_NAME`, `TRIGGER_GROUP`, `TRIGGER_STATE`) USING BTREE,
  INDEX `IDX_QRTZ_T_NEXT_FIRE_TIME`(`SCHED_NAME`, `NEXT_FIRE_TIME`) USING BTREE,
  INDEX `IDX_QRTZ_T_NFT_ST`(`SCHED_NAME`, `TRIGGER_STATE`, `NEXT_FIRE_TIME`) USING BTREE,
  INDEX `IDX_QRTZ_T_NFT_MISFIRE`(`SCHED_NAME`, `MISFIRE_INSTR`, `NEXT_FIRE_TIME`) USING BTREE,
  INDEX `IDX_QRTZ_T_NFT_ST_MISFIRE`(`SCHED_NAME`, `MISFIRE_INSTR`, `NEXT_FIRE_TIME`, `TRIGGER_STATE`) USING BTREE,
  INDEX `IDX_QRTZ_T_NFT_ST_MISFIRE_GRP`(`SCHED_NAME`, `MISFIRE_INSTR`, `NEXT_FIRE_TIME`, `TRIGGER_GROUP`, `TRIGGER_STATE`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_RULES
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_RULES`;
CREATE TABLE `T_VAS_RISK_RULES`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称',
  `rule_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则描述',
  `rule_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则脚本',
  `rule_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '规则的状态',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `rule_only`(`rule_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风控规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_STRATEGIES
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_STRATEGIES`;
CREATE TABLE `T_VAS_RISK_STRATEGIES`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `strategy_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '策略代码',
  `strategy_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '策略描述',
  `strategy_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '策略类型',
  `strategy_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '策略脚本',
  `schedule` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '定时任务的执行频率',
  `schedule_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调度类型',
  `schedule_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调度状态',
  `next_run` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '定时任务的下一次执行时间',
  `last_run_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '定时任务的最后一次执行状态',
  `last_run_at` timestamp NULL DEFAULT '0000-00-00 00:00:00' COMMENT '定时任务的最后一次执行时间',
  `remark` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '策略状态',
  `version_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '版本描述',
  `version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风控策略表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_STRATEGIES_ACTION_REL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_STRATEGIES_ACTION_REL`;
CREATE TABLE `T_VAS_RISK_STRATEGIES_ACTION_REL`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `strategy_id` int(11) NOT NULL COMMENT '策略ID，与T_VAS_RISK_STRATEGIES表关联',
  `action_id` int(11) NOT NULL COMMENT '动作ID，与T_VAS_RISK_ACTIONS表关联',
  `execution_order` int(11) NOT NULL COMMENT '执行顺序',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '1正常 -1删除',
  `created_at` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_strategy_action`(`action_id`, `strategy_id`) USING BTREE,
  INDEX `strategy_id`(`strategy_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风控策略与动作关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_STRATEGIES_AUDIT
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_STRATEGIES_AUDIT`;
CREATE TABLE `T_VAS_RISK_STRATEGIES_AUDIT`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `strategy_id` int(11) NOT NULL COMMENT '策略ID，与T_VAS_RISK_STRATEGIES表关联',
  `operation_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型',
  `operation_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `operation_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人',
  `version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '版本号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `version_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `strategy_id`(`strategy_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风控策略审计日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_RISK_STRATEGY_DATASOURCE_REL
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_RISK_STRATEGY_DATASOURCE_REL`;
CREATE TABLE `T_VAS_RISK_STRATEGY_DATASOURCE_REL`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `strategy_id` int(11) NOT NULL COMMENT '策略ID，与T_VAS_RISK_STRATEGIES表关联',
  `data_source_id` int(11) NOT NULL COMMENT '数据源ID，与T_VAS_RISK_DATA_SOURCE表关联',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '1正常 -1删除',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_strategy_datasource`(`strategy_id`, `data_source_id`) USING BTREE,
  INDEX `data_source_id`(`data_source_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '策略与数据源关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_SCENE_CATEGORY_CONFIG
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SCENE_CATEGORY_CONFIG`;
CREATE TABLE `T_VAS_SCENE_CATEGORY_CONFIG`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `SCENE_CODE` int(11) NOT NULL COMMENT '场景分类编码',
  `SCENE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '场景分类名称',
  `PARENT_ID` bigint(20) NULL DEFAULT NULL COMMENT '父级分类ID，NULL表示一级场景',
  `LEVEL` tinyint(2) NOT NULL DEFAULT 1 COMMENT '分类层级：1-一级场景，2-二级场景',
  `PRIORITY` int(11) NULL DEFAULT NULL COMMENT '优先级，数值越小优先级越高，仅二级场景使用',
  `STATUS` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `REMARK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注说明',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_SCENE_CODE`(`SCENE_CODE`) USING BTREE,
  INDEX `IDX_PARENT_ID`(`PARENT_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '场景分类配置表（一二级合并）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_SCENE_INFO
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SCENE_INFO`;
CREATE TABLE `T_VAS_SCENE_INFO`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `SCENE_CODE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '场景编号',
  `SCENE_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '场景名称',
  `PARENT_SCENE_CODE` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父级场景编号',
  `SCENE_LEVEL` tinyint(4) NOT NULL COMMENT '等级',
  `PRIORITY_NUM` int(11) NULL DEFAULT 0 COMMENT '越小月靠前',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `REMARKS` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `uniq_SCENE_CODE`(`SCENE_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'VCC业务场景字典表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_SCENE_RULE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SCENE_RULE`;
CREATE TABLE `T_VAS_SCENE_RULE`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `RULE_ID` bigint(20) NOT NULL COMMENT '规则业务ID，同一规则的不同版本共享此ID',
  `SCENE_CODE` int(11) NOT NULL COMMENT '场景分类编码，关联T_SCENE_CATEGORY_CONFIG.SCENE_CODE',
  `SUB_SCENE_CODE` int(11) NULL DEFAULT NULL COMMENT '子场景分类编码',
  `RULE_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则名称',
  `RULE_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则类型：MCC_ONLY(仅MCC)，MERCHANT_ONLY(仅商户名)，MCC_MERCHANT(MCC+商户名组合)',
  `MCC_CODES` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'MCC码，多个用逗号分隔',
  `MERCHANT_MATCH_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户名匹配类型：EQUALS(等于)，CONTAINS(包含)，STARTS_WITH(开头)，ENDS_WITH(结尾)，REGEX(正则表达式)',
  `MERCHANT_PATTERN` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商户名匹配值或正则表达式',
  `PRIORITY` int(11) NOT NULL DEFAULT 100 COMMENT '规则优先级，数值越小优先级越高',
  `STATUS` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1-启用，0-禁用',
  `VERSION` int(11) NOT NULL DEFAULT 1 COMMENT '规则版本号',
  `IS_CURRENT` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否为当前生效版本：1-是，0-否',
  `EFFECTIVE_DATE` timestamp NULL DEFAULT NULL COMMENT '生效时间',
  `EXPIRE_DATE` timestamp NULL DEFAULT NULL COMMENT '失效时间',
  `REMARK` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则说明',
  `CREATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `CREATE_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `UPDATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_RULE_VERSION`(`RULE_ID`, `VERSION`) USING BTREE,
  INDEX `IDX_RULE_ID_CURRENT`(`RULE_ID`, `IS_CURRENT`) USING BTREE,
  INDEX `IDX_SCENE_CODE`(`SCENE_CODE`) USING BTREE,
  INDEX `IDX_SUB_SCENE_CODE`(`SUB_SCENE_CODE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 134 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '场景分类规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_VAS_SETTLEMENT_FILE
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SETTLEMENT_FILE`;
CREATE TABLE `T_VAS_SETTLEMENT_FILE`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `CHANNEL_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道类型,如:NIUM',
  `FILE_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '文件名',
  `BATCH_DATE` date NULL DEFAULT NULL COMMENT '批次日期yyyyMMdd',
  `CREATION_DATE` timestamp NULL DEFAULT NULL COMMENT '文件创建时间',
  `CLIENT_HASH_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户端的唯一ID',
  `FILE_IDENTIFICATION` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件标识',
  `RECORDS_COUNT` int(9) NOT NULL COMMENT '文件包含的记录条数',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `IS_SETTLE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '是否结算 1:是；0：否',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UNIQ_CHANNEL_TYPE`(`CHANNEL_TYPE`, `FILE_NAME`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 530 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '清结算文件表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for T_VAS_SETTLE_TRANS_RECOR
-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SETTLE_TRANS_RECOR`;
CREATE TABLE `T_VAS_SETTLE_TRANS_RECOR`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '记录编号',
  `USER_NO` bigint(20) NOT NULL COMMENT '用户号',
  `CARD_LOG_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡编号',
  `CARD_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡号',
  `APPROVAL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '授权码',
  `POST_DATE` timestamp NULL DEFAULT NULL COMMENT '入账日期',
  `SETTLE_DATE` timestamp NULL DEFAULT NULL COMMENT '出账日期',
  `BILL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账币种',
  `BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账币种对应金额',
  `ORIGINAL_BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账原金额',
  `TRANS_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型',
  `TRANS_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型码',
  `TRANS_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `IS_CREDIT` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收或付标识 1:收；0：付',
  PRIMARY KEY (`ID`) USING BTREE,
