  INDEX `IDX_TRANS_NO`(`TRANS_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '清算交易记录表' ROW_FORMAT = Dynamic;

