  `APPROVAL_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权码',
  `POST_DATE` timestamp NULL DEFAULT NULL COMMENT '入账日期',
  `SETTLE_DATE` timestamp NULL DEFAULT NULL COMMENT '出账日期',
  `BILL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '入账币种',
  `BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账币种对应金额',
  `ORIGINAL_BILL_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '入账原金额',
  `TRANS_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型',
  `TRANS_CODE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型码',
  `TRANS_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易流水号',
  `IS_CREDIT` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收或付标识 1:收；0：付',
  `CREATE_AT` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_AT` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道交易唯一号',
  `ORIGIN_TRANS_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原授权交易ID',
  `OCCUR_TIME` timestamp NULL DEFAULT NULL COMMENT '交易发生时间',
  `TRANS_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易币种',
  `TRANS_CURRENCY_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易币种金额',
  `LOCAL_CURRENCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡币种',
