  `ORIGIN_LOCAL_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始卡币种金额-不加bp',
  `MERCHANT_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户名称',
  `MERCHANT_CATEGORY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户MCC',
  `MERCHANT_COUNTRY_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家码',
  `MERCHANT_CITY` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家城市',
  `MERCHANT_STATE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家城市区域',
  `MERCHANT_ZIP_CODE` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户所在国家邮编',
  `MERCHANT_DESC` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户描述',
  `MERCHANT_EXTRA` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户额外信息',
  `TRANS_EXTRA` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易额外信息',
  `REFUND_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '销卡退款状态 1:已退 0:未退 2:观察待处理 3:金额超限 4:非美金卡 默认空无需处理',
  `CROSS_BOARD_TYPE` tinyint(1) NULL DEFAULT NULL COMMENT '跨境交易类型：0:domestic 1:international ',
  `CHANNEL_TRANS_FEE_CURRENCY` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '渠道手续费-币种',
  `CHANNEL_TRANS_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '渠道手续费',
  `REFUND_DISPLAY_STATUS` tinyint(1) NULL DEFAULT 1 COMMENT '销卡后退款显示状态 0-隐藏   1-显示',
  `SCENE_CODE` int(11) NULL DEFAULT NULL COMMENT '交易场景码',
  `SUB_SCENE_CODE` int(11) NULL DEFAULT NULL COMMENT '交易场景码-二级',
  `SCENE_RULE_ID` bigint(20) NULL DEFAULT NULL COMMENT '场景规则ID',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1-渠道返点',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段8',
  `EXT9` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段9',
  `EXT10` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段10',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  UNIQUE INDEX `UNIQ_TRANS_ID`(`TRANS_ID`) USING BTREE,
  INDEX `IDX_TRANS_NO`(`TRANS_NO`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_CARD_NO`(`CARD_NO`) USING BTREE,
  INDEX `IDX_POST_DATE`(`POST_DATE`) USING BTREE,
  INDEX `IDX_CARD_ID`(`CARD_ID`) USING BTREE,
  INDEX `IDX_ORIGIN_RECORD_NO`(`ORIGIN_RECORD_NO`) USING BTREE,
  INDEX `IDX_CARD_LOG_ID`(`CARD_LOG_ID`) USING BTREE,
  INDEX `IDX_ORIGIN_TRANS_ID`(`ORIGIN_TRANS_ID`) USING BTREE,
  INDEX `IDX_SETTLE_DATE`(`SETTLE_DATE`) USING BTREE,
  INDEX `IDX_SUB_SCENE_CODE`(`SUB_SCENE_CODE`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 257822 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '清算交易记录表' ROW_FORMAT = Dynamic;

