-- ----------------------------
DROP TABLE IF EXISTS `T_VAS_SETTLE_TRANS_RECORD_NIUM`;
CREATE TABLE `T_VAS_SETTLE_TRANS_RECORD_NIUM`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键Id',
  `RECORD_NO` bigint(20) NOT NULL COMMENT '记录编号',
  `ORIGIN_RECORD_NO` bigint(20) NULL DEFAULT NULL COMMENT '原授权记录编号',
