  `CARD_ID` bigint(20) NULL DEFAULT NULL COMMENT '卡唯一编号',
  `CARD_HASH_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '渠道卡ID UUID',
  `TRANSACTION_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `PARTNER_TRANSACTION_REFERENCE_NO` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权返回给nium的交易ID(RECORD_NO)',
  `RECORD_TYPE` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `POST_DATE` date NULL DEFAULT NULL COMMENT '渠道原清算日期yyyyMMdd',
  `EFFECTIVE_DATE` date NOT NULL COMMENT '结算生效日期yyyyMMdd',
  `BATCH_DATE` date NOT NULL COMMENT '批次结算日期yyyyMMdd',
  `TRANSACTION_TYPE` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易类型 D-入 C-出',
  `TRANSACTION_CODE` varchar(5) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易编码',
  `BILLING_AMOUNT` decimal(19, 2) NOT NULL COMMENT '账单金额',
  `BILLING_CURRENCY_CODE` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账单币种',
  `TRANSACTION_AMOUNT` decimal(19, 2) NOT NULL COMMENT '交易金额',
  `TRANSACTION_CURRENCY_CODE` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易币种',
  `AUTHORIZATION_CODE` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '6位授权码',
  `DESCRIPTION` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易说明',
  `CARD_ACCEPTOR_ID` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '卡接受者ID',
  `INTERCHANGE_REFERENCE` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商户提供的交易交换参考',
  `VISA_TRANSACTION_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'VISA为交易提供的唯一ID',
  `TOKEN_REQUESTOR_ID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ApplePay/GooglePay令牌请求者ID',
  `TOKEN_NUMBER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ApplePay/GooglePay令牌号',
  `FOR_FUTURE_PURPOSE` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '将来添加其他字段',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `IS_SETTLE` char(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '是否结算 1:是；0：否',
  `LOCAL_AMOUNT` decimal(19, 2) NULL DEFAULT NULL COMMENT '开卡币种对应金额',
  `ORIGIN_LOCAL_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '原始卡币种金额-不加bp',
  `LOCAL_CURRENCY_CODE` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开卡币种',
  `REMARK` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `REFUND_STATUS` tinyint(1) NULL DEFAULT NULL COMMENT '销卡退款状态 1:已退 0:未退 2:观察待处理 3:金额超限 4:非美金卡 默认空无需处理',
  `REFUND_DISPLAY_STATUS` tinyint(1) NULL DEFAULT 1 COMMENT '销卡后退款显示状态 0-隐藏   1-显示',
  `RRN` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '检索参考号  Retrieval Reference Number ',
  `SCHEME_TID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Scheme Transaction Identifier',
  `MID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Merchant Id 商户编号',
  `MTID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Merchant Terminal Id 商户终端ID',
  `MERCHANT_NAME` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商家名称',
  `MERCHANT_CITY` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商家城市',
  `MERCHANT_COUNTRY` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商家国家',
  `MCC` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'MCC',
  `MULTIPLE_SETTLEMENT_INDICATOR` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '多重结算指标 M多个 or F最终',
  `INTERCHANGE_FEE_SIGN` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交换费标志',
  `INTERCHANGE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '交换费',
  `ORIG_INTERCHANGE_FEE_SIGN` varchar(1) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '原始交换费标志 +或-',
  `ORIG_INTERCHANGE_FEE` decimal(19, 2) NULL DEFAULT NULL COMMENT '原兑换费',
  `SCENE_CODE` int(11) NULL DEFAULT NULL COMMENT '交易场景码',
  `SUB_SCENE_CODE` int(11) NULL DEFAULT NULL COMMENT '交易场景码-二级',
  `SCENE_RULE_ID` bigint(20) NULL DEFAULT NULL COMMENT '场景规则ID',
  `EXT1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `EXT2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `EXT3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段3',
  `EXT4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段4',
  `EXT5` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段5',
  `EXT6` varchar(2048) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '扩展字段6',
  `EXT7` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段7',
  `EXT8` decimal(19, 2) NULL DEFAULT NULL COMMENT '扩展字段8',
  `EXT9` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段9',
  `EXT10` tinyint(4) NULL DEFAULT NULL COMMENT '扩展字段10',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_RECORD_NO`(`RECORD_NO`) USING BTREE,
  UNIQUE INDEX `UIDX_SETTLE_NIUM`(`CARD_ID`, `INTERCHANGE_REFERENCE`, `TRANSACTION_TYPE`, `BILLING_AMOUNT`) USING BTREE,
  INDEX `IDX_CARD_HASH_ID`(`CARD_HASH_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_EFFECTIVE_DATE`(`EFFECTIVE_DATE`) USING BTREE,
  INDEX `IDX_TRANSACTION_ID`(`TRANSACTION_ID`) USING BTREE,
  INDEX `IDX_ORIGIN_RECORD_NO`(`ORIGIN_RECORD_NO`) USING BTREE,
  INDEX `IDX_POST_DATE`(`POST_DATE`) USING BTREE,
  INDEX `IDX_CREATE_AT`(`CREATE_AT`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 147 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '清算交易记录表_NUIM' ROW_FORMAT = COMPACT;

