  `CARD_TYPE` tinyint(1) NOT NULL COMMENT '卡类型：0#为常规  1#共享子卡',
  `CARD_CCY` char(3) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '卡币种',
  `TRANS_MODE` tinyint(1) NOT NULL COMMENT '1授权 2清算',
  `TRANS_TYPE` char(4) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易类型',
  `RESP_CODE` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易响应码(授权交易)',
  `TRANS_COUNT` int(8) NULL DEFAULT NULL COMMENT '交易笔数(卡币种)',
  `TRANS_AMT` decimal(19, 2) NULL DEFAULT NULL COMMENT '交易金额(卡币种)',
  `CREATE_AT` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `UPDATE_AT` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UIDX_TRANS_USER_DAILY_SUMMARY`(`USER_NO`, `TRANS_DATE`, `CHANNEL_TYPE`, `CARD_BIN`, `CARD_TYPE`, `CARD_CCY`, `TRANS_MODE`, `TRANS_TYPE`, `RESP_CODE`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE,
  INDEX `IDX_TRANS_DATE`(`TRANS_DATE`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4038 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'vcc用户交易日汇总' ROW_FORMAT = Dynamic;

