-- Table structure for T_WITHDRAW_CHANNEL_COST
-- ----------------------------
DROP TABLE IF EXISTS `T_WITHDRAW_CHANNEL_COST`;
CREATE TABLE `T_WITHDRAW_CHANNEL_COST`  (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `RATE_ID` bigint(19) NOT NULL COMMENT '费率唯一编号',
  `CHANNEL_ID` bigint(19) NOT NULL COMMENT '渠道编号',
  `FEE_TYPE` tinyint(2) NOT NULL COMMENT '费用类型：1-费率，2-费率加固定值，3-固定值，4-阶梯',
  `RATE` varchar(8) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费率，按照百分比形式保存',
  `FIXED_FEE` decimal(19, 2) NOT NULL COMMENT '渠道固定费用',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  `REMARKS` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_WITHDRAW_DISTRIBUTE_RESULT
-- ----------------------------
DROP TABLE IF EXISTS `T_WITHDRAW_DISTRIBUTE_RESULT`;
CREATE TABLE `T_WITHDRAW_DISTRIBUTE_RESULT`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID自增主键',
  `WITHDRAW_ID` bigint(20) NOT NULL COMMENT '提现申请号',
  `TRANS_NO` bigint(20) NOT NULL COMMENT '下发批次号-对应提现申请下发请求订单号',
  `TRANS_BATCH_ID` int(11) NOT NULL COMMENT '提现申请订单内卡生成的订单号',
  `TRANS_ORDER_ID` int(11) NOT NULL COMMENT '内卡拆单对应批次订单号',
  `TO_ACC_DEPT` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行名称',
  `TO_ACC_NAME` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现银行卡持有人',
  `TO_ACC_NO` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '提现银行卡帐号',
  `TRANS_MONEY` decimal(19, 2) NOT NULL COMMENT '提现金额',
  `TRANS_SUMMARY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '转账描述',
  `STATE` tinyint(2) NOT NULL COMMENT '下发结果：0-处理中，1-成功，-1-失败，2-已重发',
  `TRANS_REMARK` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `TRANS_ENDTIME` timestamp NULL DEFAULT NULL COMMENT '代付开始时间',
  `TRANS_STARTTIME` timestamp NULL DEFAULT NULL COMMENT '代付结束时间',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新时间',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 227 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '内卡反馈下发请求处理结果' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_WITHDRAW_ORDER_ITEM
-- ----------------------------
DROP TABLE IF EXISTS `T_WITHDRAW_ORDER_ITEM`;
CREATE TABLE `T_WITHDRAW_ORDER_ITEM`  (
