  `COMMODITY_NAME` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品名称',
  `ORDER_ID` bigint(20) UNSIGNED NOT NULL COMMENT '宝付订单号',
  `COMMODITY_AMOUNT` bigint(11) NOT NULL COMMENT '商品数量',
  `COMMODITY_PRICE` decimal(19, 2) NOT NULL COMMENT '商品价格',
