-- ----------------------------
DROP TABLE IF EXISTS `T_WITHDRAW_ORDER_LOGISTICS`;
CREATE TABLE `T_WITHDRAW_ORDER_LOGISTICS`  (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ORDER_ID` bigint(20) NOT NULL DEFAULT 0 COMMENT '订单号',
  `LOGISTICS_COMPANY_NUMBER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '快递公司编号（物流公司编号）',
  `LOGISTICS_NUMBER` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '物流单号（运单号）',
