  `CONSIGNEE_CONTACT` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收货人联系方式',
  `CONSIGNEE_ADDRESS` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '收货人地址',
  `DELIVERY_DATE` datetime NULL DEFAULT NULL COMMENT '发货日期',
