) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单运单信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for T_WORKSHEET_TYPE_CHANGE_RECORD
-- ----------------------------
DROP TABLE IF EXISTS `T_WORKSHEET_TYPE_CHANGE_RECORD`;
CREATE TABLE `T_WORKSHEET_TYPE_CHANGE_RECORD`  (
  `ID` bigint(19) NOT NULL AUTO_INCREMENT COMMENT 'ID主键编号',
  `RECORD_ID` bigint(19) NOT NULL COMMENT '记录编号',
  `USER_NO` bigint(19) NOT NULL COMMENT '用户编号',
  `BEFORE_CHANGE_WORKSHEET_TYPE` int(2) NOT NULL COMMENT '变更前工单类型：1-KA 2-加急 3-普通',
  `AFTER_CHANGE_WORKSHEET_TYPE` int(2) NOT NULL COMMENT '变更后工单类型：1-KA 2-加急 3-普通',
  `STATUS` int(2) NOT NULL COMMENT '状态：0-删除，1-正常',
  `REMARKS` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CREATE_AT` timestamp NOT NULL COMMENT '创建时间',
  `CREATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人',
  `UPDATE_AT` timestamp NOT NULL COMMENT '更新时间',
  `UPDATE_BY` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_RECORD_ID`(`RECORD_ID`) USING BTREE,
  INDEX `IDX_USER_NO`(`USER_NO`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '工单类型变动记录表' ROW_FORMAT = Dynamic;

