-- ----------------------------
-- Procedure structure for yingfeng
-- ----------------------------
DROP PROCEDURE IF EXISTS `yingfeng`;
delimiter ;;
CREATE PROCEDURE `yingfeng`()
BEGIN
DECLARE i INT DEFAULT 1;
DECLARE a INT DEFAULT 1;
DECLARE b INT DEFAULT 1;
DECLARE c INT DEFAULT 1;
##num_limit 要插入数据的数量,rand_limit 最大随机的数值
DECLARE rand_limit INT DEFAULT 10;
DECLARE num_limit INT DEFAULT 100000;
 
WHILE i<=num_limit DO
 
SET a = FLOOR(RAND()*rand_limit);
SET b = FLOOR(RAND()*rand_limit);
SET c = FLOOR(RAND()*rand_limit);
INSERT INTO CBCA.T_CHANNEL_TRADE_SUMMARY VALUES (NULL,900000+a,'2018-09',20+c,'CNY',10.00,'CNY',1.00,NULL,NOW(),'SYSTEM',NOW(),'SYSTEM');
SET i = i + 1;
 
END WHILE;
    END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
